/* 令和4年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20220302-3","meetingId":"r04-c-budget","date":"2022年3月2日","dateIso":"2022-03-02","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を166件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"あくつ副委員長","kind":"質問","question":"第４項、款別審査の質疑等についてです。なお、質問時間は、会派におかれましては、１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、無所属の委員は、答弁時間も含めて、１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問","question":"私からは４７ページ、新型コロナウイルス感染症対応地方創生臨時交付金の予防接種費からワクチン対応について、あとは時間があれば、６７ページのオリンピック・パラリンピック開催周知事業で、レガシーについてお伺いをしたいと思います。この１回目、２回目接種の、そもそもの目標値がどれぐらいのパーセンテージだったのかということと、これまでの評価、あとは課題がもしあれば教えてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"現時点で９３％を超える接種率まで、やってくることができました。課題としましては、まだ、もしかしたらご希望があるのにもかかわらず、受けていない方がいらっしゃるかもしれませんので、その辺りをどうするかということを今後検討していきたいというふうに考えております。","voiceIndex":11,"id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問・要望","question":"品川区はもともと１回目、２回目が少し遅かったということもあって、３回目はまだまだ目標値というものは低いのかと思うのですが、３回目の接種、全体の接種率をまずどう捉え、今後どうしていきたいのか、９０％とまた高い目標値を設定するのかお聞かせいただきたいということと、この３回目の接種が、国から８か月から６か月に前倒しをされたと認識をしていますけれども。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"期限を逃した方ということも含めまして、９月３０日までに打てるように、広報、ホームページ等々で周知をしていくことで、希望される方が打てるように、何とか体制を整えていきたいというふうに考えております。","voiceIndex":13,"id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問・要望","question":"ホームページ見てみると、１回目、２回目に関してはファイザーが７割ぐらい、それでモデルナが大体３割ぐらい打たれたということで、３回目に関しては、国から来るのがファイザーとモデルナ、５対５というふうに書いてあって、これはやはり混合接種を推奨していかないと、一部の方が打てなくなってしまうことも危惧されるというふうに書いてあるのですが、今モデルナに対して。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今後もし延長等々があれば、それはそれで柔軟に対応していければというふうに考えてあります。","voiceIndex":15,"id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問・要望","question":"ご見解をお聞かせください。子どものワクチンについても、接種目標というものが９０％ぐらいを予定されているのかお聞かせください。先日、昨日かな、報道で、民間企業がアンケートを取った際に、１,０００人ほどの保護者にアンケートを取って、約半数余りが接種させたくないというような意向を示したというふうにあって、これはなかなか課題が大きいのかなと思うのですが、まず目標数を教えてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"現時点でのモデルナ、それからファイザーの接種状況ですが、おおよそ、区民全体で見ると、今８万人強の方がもう既に追加接種を打ち終わっております。その中で、区内のモデルナ会場で打った方が約４万人いらっしゃいますので、大体半々ぐらいかなというふうには考えております。","voiceIndex":19,"id":"exchange-005"},{"speaker":"芹澤委員","kind":"質問・要望","question":"この子どもの集団接種会場に関しては、１回目や２回目、あと３回目の大人の接種と違って、今２か所だけに限られていると思うのです。すみません、もう１点。日本医師会の中川会長が記者会見で、小児接種を推奨する際に、医療的ケア児もぜひ優先的に接種するべきだというようなお話があって、この品川区の医療的ケア児に対しての接種推奨のやり方、どういったものがあったのかお聞かせください。","respondent":"有馬庶務課長、豊嶋新型コロナウイルス予防接種担当課長","answer":"子どもへのワクチン接種の学校への対応ですけれども、文部科学省から通知が来まして、それを学校に通知してあります。それで、あくまでも任意接種であるということをまず学校にきちんと伝えてくださいと。集団接種会場等々につきましての設置の方法ですが、事前に医師会の先生方、小児科医の先生方と協議をいたしまして、どこで接種をするべきかということをいろいろ協議いたしました。","voiceIndex":21,"id":"exchange-006"},{"speaker":"つる委員","kind":"確認","question":"第３３号議案の１３ページ、予防接種費、それから第１号議案の６１ページ、平和使節派遣費、７３ページ、産後の家事育児支援、それから産後ドゥーラ資格取得費用助成を伺っていきます。予防接種で、５歳から１１歳のワクチンについてでありますが、今、若干芹澤委員のほうからも質疑で確認されていたところがありましたけれども、まず予約です。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"区の予約システムにつきましては、１人ずつの予約というふうにはなりますが、予約自体は、追加接種で行っている同じサイシードというシステムを使いますので、同じ時間枠を希望、もしくは１枠ずらした時間枠を希望すれば、あとはその接種会場で柔軟に対応することで。","voiceIndex":25,"id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"予約のやり方はこれまでと、そのような意味では変わらないと思うのです。逆に言うと、確実に上の子、下の子で、例えば５歳から１１歳のお子さんがいたときに、同時といいましょうか、順番に打てるようになっているのか、もう１回それを教えてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"同時に接種を希望される方で、同時にいらっしゃったお子様につきましては、もちろん接種医師もそこは認識をしておりますので、その場でスムーズに接種ができるように、同じ時間帯で、同じ枠の中で打てるように、これからもお話をしてまいりますし。","voiceIndex":27,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"すごく現場では細かい対応になるかと思いますし、予約の段階で、保護者も上の子、下の子と、会場、それから時間もばらばらだったら、それだけで１日大変なことになってしまうので、いよいよこれから予約接種が始まるので、多子、多胎のお子様についての対応は、しっかりとお願いしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"具体的には、１５分で大体１人ないし２人ぐらいで接種が進んでいくもので、現在予約枠を作成していますので、様子を見ながら、その辺りは臨機応変に、次回以降の予約枠の作成の際に調整をしてまいりたいというふうに考えております。","voiceIndex":29,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"今回１バイアルで１０人分というところで、これもかなり調整が大変なのかなと思います。個別接種会場の場合、当然そこで個別でやっていただくところと区の予約システム、それぞれ使うにしても、キャンセル等がないようにお願いしますとなっているわけですけれども、ただキャンセルになってしまって、でもその日に打ちたいというときの全体の調整というものは、どこが担うのでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"その辺りの調整につきましては、各医療機関のほうに現時点ではお任せをしている状態ではありますが、今後医師会を通じて、どのようにするのが適切か、接種が始まってからも、様子を見ながら適宜改善をしてまいりたいというふうに考えております。","voiceIndex":31,"id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"ちょっと求めていた十分な答弁ではないのですけれども、いずれにしてもワクチンが無駄にならないような工夫というものは、当然医療機関の方へのご協力をしっかりお願いしていただくことと、区としてもしっかりその辺を差配というか、リードしていただいて、無駄にならないような、また、空いているのだったら打てるというご家庭があった場合に打てるような仕組み。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"集団接種会場の設置が、３月末からということで運用していくところです。現状、会場の下見が始まったところですので、今委員ご指摘のことも踏まえまして、会場設置で十分な体制に整えていきたいというふうに考えております。","voiceIndex":33,"id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"副反応、特に副反応のときだと思うのですが、お子さんによっていろいろまちまちだと思うのですけれども、１日２日で収まる人、４日ぐらいは何となく様子見てくださいねなどということが、子ども向けの書面でも出ている。そうしたときに、その学習の支援という部分ではどのように今考えているのか教えてください。","respondent":"勝亦学務課長","answer":"副反応、コロナ等でお休みになっている児童・生徒への学習の支援としては、まずオンライン、ハイブリッドの授業等を行う等々で、可能な限り学習の継続支援をしていくような体制を整えてあります。","voiceIndex":35,"id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"時間の関係で、次に７３ページの産後ドゥーラ資格取得費用助成について伺いたいと思いますが、これは補正でマイナスで、当初予算から見ると６６％強の執行率の現状ということで、今年度からそれを始めていただいたということで、昨日もドゥーラ協会の方とも、理事の方とも懇談させていただいて、品川区、今非常に優秀な方が資格取得に頑張っていただいているという声も聞きました。","respondent":"山下子ども家庭支援センター長","answer":"今年度より新たに取組を始めまして、上期の受講を終えられた方が３名、実際に申請をいただきました。今下期のほうにつきましても、一定講習が修了しておりまして、７名の方のご申請をいただくということで、計１０名の方にご申請をいただいたところです。","voiceIndex":37,"id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"これをお願いしたいなと思っています。ほかの日に、ドゥーラの利用助成だとか、この辺についても伺っていきたいなと思いますので、改めてそこについてはしっかり体制を取っていただきたいと思います。残った時間で平和使節派遣費、ここを１点伺いたいと思います。一般質問でも伺いまして、今年度と前年度、昨年と一昨年という言い方でしょうか、交流が中止になってしまった。","respondent":"古巻総務課長","answer":"平和使節派遣につきましては、現地に行くという意味も大変大きいのかなとは思いつつも、様々な理由で行けないというケースも考えられますので、オンラインを含めて、様々な手法で効果が出るような形でのやり方を追求していきたいなと考えています。","voiceIndex":39,"id":"exchange-014"},{"speaker":"つる委員","kind":"質問","question":"ぜひ平和、今すごく注目されて大事だと思います。区民の心の中にしっかりと平和の心を植えていくという意味での品川区の平和事業の推進を、しっかりお願いしたいなと思います。すまいるスクールのお弁当については、別の款でしっかりと伺っていきたいと思いますので、今日は以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問","question":"４７ページ、新型コロナウイルス感染症の予防接種費、３７ページで財政全般、６７ページ、経済センサス活動調査についてお伺いいたします。初めに４７ページ、新型コロナウイルス感染症の予防接種費についてお伺いいたします。これは５歳から１１歳児の方が対象で、２万３,０００人の方がいよいよ３月８日から接種を開始されるということです。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ただ、その辺りは医師会の先生方と情報共有はしっかりしておりますし、ほかの方法も先生方のほうで十分にご留意いただいておりますので、その辺りにつきましては、心配は特にはしておりませんが。","voiceIndex":43,"id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"確認","question":"分かりました。ワクチンについて、最後に１点だけちょっと確認したいというか、お尋ねなのですけれども、区への小児用のワクチンの供給スケジュールは、今後どのようになっていくのかということだけちょっとお聞きしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"その次が３月１７日に５８箱、２,９００人分が到着いたします。それ以降は、４月以降の配送という形になっております。","voiceIndex":47,"id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。ぜひよろしくお願いいたします。続いて３７ページ、財政全般についてお伺いをしたいと思います。令和３年度の執行率ですが、これが今マイナス補正になっている中で、どの程度の執行率があるのかということをお尋ねしたいと思います。","respondent":"黒田財政課長","answer":"執行率につきましては、この補正予算の後に、年度末までの執行状況を勘案して、大体９５％の執行率を想定しています。","voiceIndex":49,"id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。それは当然対応なさっているとは思うのですけれども、何か早急にやらなければいけないことが当然あった中で、対応方法というのですか、特に土木、建築関係の、マイナスになったのだけれども、どのように対応していたということをお尋ねしたいと思います。","respondent":"黒田財政課長","answer":"補正予算の見積りに当たりましては、年度の予算ですので、３月までの執行見込みを、工事関係であれば出来高等も含めて、所管のほうで事業者と調整して、執行できるところまでを予算として計上するという形で、補正予算を編成しています。","voiceIndex":51,"id":"exchange-019"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。どうもありがとうございました。最後に６７ページ、経済センサス活動調査についてお伺いをしたいと思います。そもそもこの経済センサス活動調査は、総務省からの委託というか、品川区に来ていると思うのですけれども、内容は大体把握しているのですが、これは毎年やっているものではないと思うのですけれども、そこのところを１点お尋ねしたいと思います。","respondent":"川島地域活動課長","answer":"こちらの経済センサス活動調査につきましては、５年置きに実施されるというものでございまして、平成２４年度から始めて今回３回目に当たるです。","voiceIndex":53,"id":"exchange-020"},{"speaker":"高橋（伸）委員","kind":"意見","question":"これはマイナス９００万円余というものが出ているのですけれども、大体あらかじめこの金額というものは分かっているかと思うのですが、このマイナス９００万円余というのはどのようなところでマイナスになったのかということをお尋ねしたいと思います。","respondent":"川島地域活動課長","answer":"こちらのほう、国が示す配置人員で調査員の人数について予算編成していたところなのですが、実際には効率的な事務処理で、４１０人の予定で予算編成しておりましたけれども、２１９人の配置で調査が無事完了したということで、減額補正をするものです。","voiceIndex":55,"id":"exchange-021"},{"speaker":"高橋（伸）委員","kind":"意見","question":"分かりました。この経済センサス活動調査も、私のところの事業所にも来て、回答はしたのですけれども、この回答を区がアンケート結果をまとめて、それが何か政策の立案に反映されているのかということが、何かちょっと見えないところがあるので、そこがどのようになっているのかお尋ねしたいと思います。","respondent":"川島地域活動課長","answer":"こちらの結果、私どものほうで品川区の統計にまとめまして、関係部署にお配りして活用しているほかに、国のほうも各種行政施策のほかに、地域の産業振興、商店街や中心市街地の活性化などの施策の、地方公共団体の各種施策の政策立案。","voiceIndex":57,"id":"exchange-022"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。ぜひ今後も何か見える形で、ほかの関係機関、部署とも連携をしていただきながら、やっていただきたいと思います。よろしくお願いします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"４７ページ、新型コロナウイルス感染症対応地方創生臨時交付金に関連して、ＰＣＲ等検査について伺います。では伺いますけれども、東京都が行っている、このＰＣＲ等検査無料化事業とは、区内ではどのようなところで、１日に何人の方が受けられる規模なのか伺います。","respondent":"鷹箸保健予防課長","answer":"今お尋ねのありました都の無料検査ですけれども、もともと、言い方が適当かどうか分かりませんが、ゲリラ的に、特に場所を公表せずに実施するという、その形で都から話を承っております。","voiceIndex":61,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"それもやっていますけれども、きちんと公表すべきだと。常駐でやるべきだと私は思っています。都に求めていただきたいと思いますが、それとともに薬局等でやっているものなのですけれども、そちらについては１日何人の方が受けられ、どこでやっているのか伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"申請から許可が下りるまで、２か月程度かかるというところで、今、都のホームページに公表されているのはたしか区内３か所だと思いますけれども、決して多くの人数ができる状態ではないというふうに伺っておりまして、個人の薬局にお伺いしたところでは。","voiceIndex":65,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"そうなのです。今最新の状況を見ますと、１７か所に増えてはいるのです。数としては十分ではないということは明らかだと思います。改めて、それなのになぜ都が行っていると区で実施しないということになるのか、これは区としても行う必要があると思うのですけれども、いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"本会議での答弁に加えまして、過日の厚生委員会の中でもお答えした部分ですが、区といたしましては、やはりまずは感染者の方、現状で本日の時点でもまだ数千人の方が区内で自宅療養している、その状況の中。","voiceIndex":67,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"コロナ第６波の感染者は高止まりしています。高止まりなのです。そのようなすごい実感があるのです。今までの検査はやればいいというものではないという答弁からは随分変化したように聞こえるのですが、質問しますけれども、品川区はこれまでの検査の有用性への懐疑的な認識というものを改めて、ＰＣＲ検査は有効であると、拡大すべきであるという立場に認識が変化したということなのでしょうか。伺います。","respondent":"鷹箸保健予防課長","answer":"ですが、その対象として、定期的な検査、無症状の方の定期的な検査を実施すべきかといったことについては、当初、昨年、一昨年でしょうか、もう、１０月から高齢者施設、あるいは障害者施設等の従事者については定期的に実施しているところですし、今回。","voiceIndex":69,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"過去のやり取りがどうだったかということを置いておいても、現在検査が有用だということをおっしゃっているわけです。ですから、もっとそれを積極的に区としてやるべきだと思うのです。これはどれだけ区民にとって心強いことなのでしょうか。世田谷区ではこうしたことをやっているわけですが、区はなぜそうした立場に立たないのか伺います。今からでもその体制実施を求めますが、いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"そういった方が自宅療養をされている場合もありますので、感染者への対応に注力していきたいと思います。","voiceIndex":71,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"私からは、ページ順でいうと、５４ページ、５７ページの繰入金のマイナス補正について、それから６２ページ、６３ページ、庁舎等管理費、庁舎整備基金積立金、６８ページ、６９ページ、７２ページ、７３ページ、７６ページ辺りに見えています都支出金の減について、それから、７６ページ、７７ページの保健予防費について伺います。最初に、保健予防費から伺います。７６ページ、７７ページの保健予防費です。","respondent":"黒田財政課長、崎村人事課長","answer":"こちらの予算書ですと、補正前の額というものが事業費ですので、そういった中で、特定財源を充てますと、その分一般財源が予定したところがつかなくなるというところ、全体の計算の中でマイナスとなっておりますので、この財源は。職員給与費の増の部分ですけれども、こちらは考え方の部分をまずお話しますと、令和３年度当初予算につきましては、令和２年１０月１日現在の職員数を基に、令和３年度の各課職員給与費を算定していたところです。","voiceIndex":74,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"それで、雇用形態を伺ったのですけれども、どうだったのでしょうか。改めて伺いたいと思います。次の質問に行きます。そしてこの質問は、以前も文化スポーツ振興基金のときの積立てをめぐって、同じような質問をさせていただいているのですけれども、ちょっとそのとき理解ができなかったので、改めて最終補正で３０億円という多額を１つの基金に積み立てる考え方について見解を伺います。","respondent":"崎村人事課長、黒田財政課長","answer":"人材派遣につきましては、人事課の６３ページのところで、今回補正予算としても、代替職員雇用経費といったことで、人材派遣については増額補正をお願いしています。庁舎整備基金についてですが、庁舎の整備の必要性が検討されまして、その中で整備費が一定額示されてきたという中では、それに対する資金を用意する必要があるというところで、庁舎は長年にわたって使う施設ですので。","voiceIndex":77,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは意見です。地方財政法第７条でしたか、繰越しが、剰余金が出たときにはその半分ぐらいは積み立てるべきということを、前の議論のときにご答弁で伺いました。もしあれでしたら、改めてご答弁を伺いたいと思います。地域振興基金の繰入れの充当事業は、地域振興事業が８０万円で、協働推進経費が４００万円ですか、地域活動費が減っているのかなと思います。その辺についても伺いたいと思います。","respondent":"黒田財政課長、川島地域活動課長","answer":"庁舎整備費につきましては、整備費の概算が検討する中で出てきたというところで、改めて資金の計画を明らかにするというところで基金を設置して積立てするというところでございまして、財源につきましては、繰り返しになりますが。コロナ禍の影響も大きいですが、ここ数年の区民活動助成制度の採択件数、確かに令和元年度が１２件だったものが、令和２年度が５件、令和３年度が５件と、少なくはなっているのですけれども、例えば令和３年度の採択事業を見てみますと。","voiceIndex":80,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"庁舎整備基金については、なかなかちょっと完全に分かりましたというところまではいかないのですけれども、やはり必要なお金であれば当初予算できちんと検討されるべきだと思います。最終補正で３０億円というのは、やはり何か、区民から見ても納得いかないのではないかなと思います。最後に、これは議案説明会の資料で見たのですけれども、都の支出金が全体で８億円減になっているのです。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長、山下子ども家庭支援センター長","answer":"私のほうが、４９ページになりますけれども、１６節から１９節の３つ、これは地域密着型の認知症高齢者グループホーム。こちらは、今年度八潮南特別養護老人ホームに導入を予定しておりますＩＣＴシステム、こちらで東京都の補助金の活用を見込んでおりましたが。一方利用の実績としましては、昨年度比、現段階で３倍を超える延べ申請者の申請を受けておりまして。","voiceIndex":83,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"コロナの影響があるかなと思っていたのですけれども、そのようなときだからこそ、このような福祉のいろいろな事業というものは必要なのではないかなと思って質問をいたしました。それからもう一つ、区内私立保育園開設経費もかなりの減額になっています。私立保育園のマイナス理由は何なのでしょうか。需要を満たしつつあるとしてのマイナスなのでしょうか。それとも他の要因があるのか伺いたいと思います。","respondent":"若生保育支援課長","answer":"その減った理由としましては、これは開設予定だった園を３園ほど減らしているところなのですけれども、そのうち１園は、当初予定していなかった土壌汚染等が発生したことによって、１年開設時期が延びたというところが１つと、あともう二つの園については。","voiceIndex":88,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"どう条件が合わなかったのか伺いたいところですが、ちょっと時間がないかなと思います。そのようなことで、条件が合わないということで区が求める質までに至っていなかったのだったら、それは無理に開設すべきではないと思います。ただ、やはりこれからも、そのような事業者の選定はきちんとしながら、区として、区の価値判断できちんとしながら、開設というものは目指していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-034"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、第３３号議案の１３ページ、予防接種費、第１号議案から７７ページ、生活保護費、８７ページ、鹿島庚塚児童遊園改修工事をお聞きしたいと思います。重なる部分もありますが、質問させていただきたいと思います。今回の追加接種は、１回目、２回目の接種実績と比べて、その進み具合、どのような状況と捉えているのか、現状をお聞かせいただきたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"これは品川区民、６５歳以上の住民票がある方を分母にした数字です。進み具合につきましてですが、品川区、６か月ということで、６か月の前倒し等々も含めまして、１月２１日より集団接種会場を開設しまして、接種を実施してまいりました。","voiceIndex":92,"id":"exchange-035"},{"speaker":"こんの委員","kind":"質問・要望","question":"先にするというか、それをよく使っていくというところで、高齢者の１・２回目の接種のときに、ファイザーから３回目はモデルナへの接種となることが不安という声と、それから、そのことによってファイザーを希望する方が多いということを踏まえながら、今ご答弁いただいたように、モデルナのほうにもできるように時間差を設けてくださっているという対策、若い方の声も。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"その他、モデルナワクチンの集団接種会場、それから職域接種で打った方もいらっしゃいます。アストラゼネカを一部打った方もいらっしゃいますので、ざっと７割弱がファイザーで、それでアストラゼネカがほんの数％、それ以外がモデルナという形で、初回接種は終了いたしました。","voiceIndex":94,"id":"exchange-036"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうした希望される方に対応できるだけのワクチンが配給されているか、配分されているか、それが非常に心配なところでありますけれども、現在配分されているモデルナ製とファイザー製の供給割合については、どのようになっていますでしょうか。今後のスケジュールなども、参考のために教えていただきたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"モデルナのほうが心筋炎を発症する確率が少し高いということもありまして、そういったことも踏まえて、３回目、追加接種の際は、モデルナワクチンをなるべくそれ以外の年齢層の方に打っていただけるような体制を整えるべく、前倒し接種でモデルナワクチンを使っていたです。","voiceIndex":96,"id":"exchange-037"},{"speaker":"こんの委員","kind":"質問・要望","question":"その中、そのように進めてくださってありがとうあります。医師会のほうでも、そうしたことが懸念されているということもありますので、私どもとしては、公明党の新型コロナウイルスワクチン対策本部プロジェクトチームを通じて、国のほうにこの配分スケジュールを、６か月に接種を前倒したのであれば、ワクチンの配分も前倒して供給をしていただくように要望しているところであります。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"その集団接種会場、今後予約枠に空き、もしくは余裕が出てきた際には、初回接種でも行いましたように、例えば予約なしの接種を行っていくであるとか、あと初回接種の際も、他区との合同接種ということも行ってまいりましたので、その辺りができないかということも含めて。","voiceIndex":98,"id":"exchange-038"},{"speaker":"こんの委員","kind":"質問・要望","question":"様々な対策を取っていただきながら、進めてくださっていることが分かりました。交互接種の、このファイザー、ファイザー、モデルナの効果や、今ご説明いただきましたけれども、こうした接種、交互接種の効果や、それから安全性、抗体の降下率というのでしょうか、抗体ができる率というものもお知らせをしながら、区民の方にモデルナも有効なのだということをお知らせをしていただきたい、このように思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"接種につきましては、皆さん関心が非常に高いものというふうに我々のほうでも認識しておりますので、適切な情報をいいタイミングで、いろいろな媒体を使って行っていくということは、今後も引き続き、鋭意進めてまいりたいというふうに考えてあります。","voiceIndex":100,"id":"exchange-039"},{"speaker":"こんの委員","kind":"質問・要望","question":"引き続きよろしくお願いいたします。そこで、当初のスケジュールから、完成までのスケジュールはずれ込むということになってしまうのでしょうか。ずれ込んでほしくないとともに、周りの隣接する区民の方々からもこの工事へのご協力が必要ですので、そうしたお声もきちんと対応していただきながら、完成を予定どおり進めていただきたいと思うところですが、現状を教えてください。","respondent":"高梨公園課長","answer":"委員ご案内のとおり、鹿島庚塚児童遊園におきましては、西側と東側で分割して工事を進めております。現在行っております東側の工事につきましては、年度末の完了というスケジュールは変わらずに、４月上旬の開園に向けて、現在予定どおり進めているところです。","voiceIndex":102,"id":"exchange-040"},{"speaker":"こんの委員","kind":"意見","question":"様々、近隣の方への対応を細かくやってくださっていることは承知しておりますので、引き続き双方が、区民の公園として区民の方が使える、その公園の整備について、ご苦労でしょうけれども、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-041"},{"speaker":"西村委員","kind":"質問","question":"４７ページ、新型コロナウイルス感染症対応地方創生臨時交付金、７４ページ、保育支援費より、コロナウイルス感染症における保育現場の現状について伺ってまいります。もう一つは、どのような事務連絡の体制を取っておられるのか、濃厚接触者や陽性者が保育園にいた場合、個別の家庭の連絡は園がやり、保健所にまとめて連絡をしているかなどをお伺いいたします。","respondent":"若生保育支援課長","answer":"それから保育所等でクラスターというか、感染が拡大しているというような場合の検査等につきましては、現在区では、保健所による行政検査というものは実施しておりませんが、保育所内で陽性者が発生した場合に関しましては、保育課および保育支援課が保健所と連携いたしまして。","voiceIndex":106,"id":"exchange-042"},{"speaker":"西村委員","kind":"質問・要望","question":"まさに横串につながることだと思いますし、ぜひとも引き続き体制を整えていただきたいと思います。コロナ禍で従業員が足りず、保育基準を下回ってしまうというような相談ですとか、事例、休園する園はあったでしょうか。感染者が出た場合の区や保護者、内部などへの連絡ですとか、事務手続にも、イレギュラーな多くの時間を要すると保育現場より伺っております。","respondent":"若生保育支援課長","answer":"保育士等が余裕を持って子どもに向き合っていただくための対策、支援等のことですが、私立保育園では、昨年度から継続して感染防止対策物品の購入補助を行っておりまして、それ以外にも、今年度保育園では、感染防止のために生じる消毒ですとか。","voiceIndex":108,"id":"exchange-043"},{"speaker":"西村委員","kind":"質問・要望","question":"現場の心配をしておりましたけれども、少し安心をしたところです。続きまして、私立認可、認証、小規模園などの在り方と、保育園の形態に合わせて、それぞれの課題をお伺いしてまいります。品川区は今急激に少子化が進んでいるという状況ではありませんけれども、昨年度４０点以上でないと入園できなかったところが、今年度３０点台でも入れたと、区民の方より伺いました。","respondent":"若生保育支援課長","answer":"今後、国のほうで、ご案内いただきました、こういった検討会の結果なども区としても参考にさせていただいて、委員ご提案のオアシスルームのような一時預かり事業というところ、こういったこともスペースの活用というところでは有効な方策の１つと考えています。","voiceIndex":110,"id":"exchange-044"},{"speaker":"西村委員","kind":"質問","question":"小規模園が大変な状況を伺いますと、国の補助が１人単価で換算されるので、小さな園は園児が１人でも入園しないと経営が圧迫されると伺っております。区は、小規模園の保護者が３歳児の壁に悩まないで済むように、認可への案内をしてきてくださいましたが、この際に、私立幼稚園で保育園と同じ時間帯で預かり保育に対応している園が、区内に８園あると伺っております。併せてお考えをお聞かせください。","respondent":"若生保育支援課長","answer":"私立幼稚園の入園は、区が関与していないところでありますので、連携園といったような設定はちょっと難しいところではありますけれども、何らかの形で連携できるような方策、こちらは区としても考えてまいりたいと思います。","voiceIndex":112,"id":"exchange-045"},{"speaker":"西村委員","kind":"提案","question":"保育支援課の業務量も心配しておりますが、どうぞ引き続き、運営会社への丁寧なサポートをお願いしたいと考えています。これ以外に、企業主導型事業所内保育所も含まれてきまして、幼稚園も含まれてくると、親御さんにとっても混乱している部分があるのではないかというところ、ご提案させていただきたいと思います。そこで、どうして認可がいいのと聞くと、よく分からないと大半の方がおっしゃいます。","respondent":"立木保育課長","answer":"ただ、チャートのようなものをご用意していませんので、これは例えば他の自治体等のものを参考にしたりなどして、研究をしてまいりたいと思います。当面は、より一層丁寧なご案内ということを心がけたいと考えています。","voiceIndex":114,"id":"exchange-046"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、補正予算書４７ページの新型コロナウイルス感染症対応地方創生臨時交付金から、子どものコロナウイルスワクチンについてお伺いいたします。本日はまず、今月から開始されることになった小児用コロナワクチン事業についてお伺いいたします。翻って我が国においても、３月から小児のコロナワクチンの接種が始まることになった経緯について、まずご説明をお願いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"区でも同様の状態で感染者が増えておりました。その中、我が国でも、２０２２年１月２１日に、５から１１歳を対象とした小児用新型コロナワクチンが薬事承認をされまして、接種が始まることとなりました。","voiceIndex":119,"id":"exchange-047"},{"speaker":"鈴木（博）委員","kind":"質問","question":"諸外国、西欧の諸国、アメリカに引き続いて、日本でも子どもにおいて新型コロナウイルスの流行がだんだん増えているという現状が、今お話を伺って理解できました。その前提として、正しい情報が適切な方法で区民に提供される必要があります。区の責務として、小児用コロナワクチンに対する正しい情報の提供をどのように進められるおつもりなのか、お伺いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"小児の接種につきましてですが、まず、その５歳から１１歳の小児接種につきまして、区としては、各ご家庭で接種のご判断をしていただきたいというふうに考えてあります。","voiceIndex":121,"id":"exchange-048"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"多くのご家庭に届くような情報提供の手段を、ホームページ掲載や接種券の資料同封以外にも、様々に検討するべきではないでしょうか。例えば、教育委員会に協力いただいて、各学校でコロナワクチンに対する分かりやすい詳しい資料を配布するとか、子ども育成課に協力をいただいて、児童センターに各種の資料を置くなど、このようなことも検討すべきと考えますが、区のお考え、取組はいかがでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、有馬庶務課長","answer":"東京品川病院、それから東邦大学医療センター大森病院などの感染症の専門家等の先生方のご講演につきましては、可否について、今後先生方とご相談の上、検討してまいりたいというふうに考えております。そのような意味では、学校全体、教員全てがその理解を深めることが必要だと思いますが、特に保護者からの相談を受ける養護教諭については、このワクチン接種について正しい理解を得る必要があると思いますので、校長会を通じて。","voiceIndex":123,"id":"exchange-049"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"コロナワクチン接種券を受け取り、いろいろ悩み、心配されている多くの区民の保護者と子ども本人に、区としても最大限親身に寄り添っていただきたいと心からお願いしたいと思います。そのためにも、子どものコロナワクチン接種に対しては、保健所だけでなく、教育委員会、子ども未来部も含めて、全庁で対応することを強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"デイサービスなどでも感染が広がり、一時閉鎖するところも幾つも出ていると伺いました。第６波での、高齢者施設や事業所での感染状況をお聞かせいただきたいと思います。この申込みが２月７日から３月１８日までということで、期限もあるものなのですが、品川区の各事業者がどれくらい手を挙げたのか、区が把握をされているのか、把握していたらその数についても伺いたいと思います。","respondent":"宮尾高齢者福祉課長、有馬庶務課長","answer":"私からは高齢者施設における感染の状況についてお答えをいたします。いわゆる東京都集中的検査の区立学校の取組ですけれども、２月３日に各学校のほうに通知をいたしまして、これは各学校が直接ウェブで申し込むというような形になっておりますので、正式なこちらでの集計は取っておりませんが。","voiceIndex":128,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これがファクスで送られてきているので、見逃したり、余裕のない職場がそのままになっていたりということで、趣旨が伝わってないために受けられないということがないのかどうなのかということが心配するところなのですけれども、締切りが３月１８日までとなっているので、私は区としても、周知をさらにしていただきたいということと、申請の把握をすることが必要だと思うのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"次にヘルパーステーションのことについてちょっと伺いたいのですけれども、ヘルパーステーションもかなりのリスクを抱えながら仕事をしているという状況です。それが１つです。私は事業所に対して、復帰するための検査キットとか、それからＮ９５マスクや防護服などを現物支給するか、または感染対策費として、区としてぜひ支給していただきたいと思うのですが、いかがでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"事業所に対する様々な支援です。衛生用品、コロナ対策の衛生用品に関する費用ですけれども、こちらは現在も東京都の補助制度にメニュー化されております。","voiceIndex":135,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、それから復帰するための検査キットというものも、区のほうとして配っていただけると。常に事業所に備えておきたいという、そのようなことでご要望を伺ったのですけれども、検査キットも配っていただけるということで、その確認をお願いしたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"それからキットにつきましては、東京都の週１回の定例的な活用もお願いすると同時に、単発的にとか、臨時的に必要になったときに備えて、ご希望いただければ、私どものほうにご連絡をいただければ、お配りをする、このようなことも支援をさせていただいているところです。","voiceIndex":137,"id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それであれば、それを事業者が活用できるようにということで、周知もお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":139,"id":"exchange-055"},{"speaker":"若林委員","kind":"質問・要望","question":"続いてその後の８月のピークを迎えた第５波、これは８月２２日までの１週間の新規陽性者が１,１６５人、ここで一気に５倍にもなった、また、自宅療養も１,２４５人に、１０倍以上ですか。そこで、前置きが長くなりましたけれども、職員の派遣で行える業務、逆に、そういった派遣職員では行えない業務はどのようなものか、確認をさせていただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"第３波までのところでは、本当に慣れない中で、後から後から起こってくる問題に、残念ながらその場その場で東京都と連携をしながら、考えつつ対応してきたですが、今、委員のご質問にもありましたとおり、その第５波、昨年の夏の大きな感染の山のときに。","voiceIndex":141,"id":"exchange-056"},{"speaker":"若林委員","kind":"確認","question":"この辺の、例えば保健所の持っている、いわゆる大本の情報、そこから国のいろいろな通知もあるでしょう。そういったものを区民に分かりやすくお知らせするのは、保健所と企画部の中で、どのような体制になっているのか、それは１つ確認をさせていただいて、また、そのような体制については、この１年間どういう強化をされてきたのかと。そういったところのお考えをお聞きしたいと思います。","respondent":"鷹箸保健予防課長、古巻総務課長","answer":"特に第６波におきましては、度重なる国および都の変更に対して、迅速に区民の方に分かりやすく広報する必要がございまして、例えば応援で来ていただいていた広報広聴課の職員に、土日であってもホームページを迅速に更新するなどの。ＢＣＰに関しましては、今第６波のいろいろな応援体制の中で、どういった対応を庁内で取ったらいいのか、その辺りも含めまして、今まさに現在進行形で検討しています。","voiceIndex":143,"id":"exchange-057"},{"speaker":"木村委員","kind":"質問","question":"私からは、令和３年度補正予算の総務費の中からお聞きをいたします。これはコロナが大きな原因となっての補正予算だったと思いますけれども、大変この質問も難しいのですが、一転してコロナが収まったときの事業には大きな費用と労力が必要になるのか、それとも、それほど労力と費用は必要ないのでしょうか。そして、過去にこのような前例などがあったのかどうか、そのようなこともお聞かせください。","respondent":"黒田財政課長","answer":"コロナ収束後の事業展開というご質問ですが、令和４年度当初予算におきましては、コロナ収束を見据えた予算編成としておりますので、そういった意味では、費用については予算としては計上させていただいているところです。","voiceIndex":147,"id":"exchange-058"},{"speaker":"木村委員","kind":"質問","question":"この事業もあれですね。この事業を立て直すために労力を使うとすれば、どのようなところになるのか、また、大きな原因はやはりコロナの影響が、もう大変大きかったなと思います。現在のこの時点では、お答え難しいのでしょうけれども、この一、二年間の事業の休止状態から本来の姿に戻るには、どれぐらいの労力と時間が必要でしょうか。分かる範囲で結構です。お聞かせください。","respondent":"黒田財政課長","answer":"費用のほうは予算のほうに計上していますが、１つイベント事業ですと、この間中止していくと、その開催のノウハウというところが少し薄れてしまうというようなところもあれば、そういったところをどのようにしていくかというところは。","voiceIndex":149,"id":"exchange-059"},{"speaker":"木村委員","kind":"質問","question":"６９ページの高齢者社会参加促進事業からの質問をいたしますけれども、特にこの気になるのが、スポーツの祭典オリンピック・パラリンピックも、１年遅れではありましたが、無事に行われた年でもありました。お聞きいたします。この事業、閉じ籠もらず、高齢者が幅広く社会に溶け込むこと、溶け込むという意味もあると私は思っていますけれども、この事業の真の目標はどこに置いてあるのでしょうか。","respondent":"菅野高齢者地域支援課長","answer":"６９ページの高齢者社会参加促進事業のマイナスの補正についてのお答えを、私のほうからします。","voiceIndex":151,"id":"exchange-060"},{"speaker":"木村委員","kind":"質問・要望","question":"高齢者の皆さんの１日も長い健康を、本当に心から願っている１人であります。ばりばりとは言いませんが、高齢者の頭脳、また考えやアイデアが活かされるときがやってくると思いますけれども、このことに対して、本区の理事者の皆さんはどのようにお考えでしょうか。高齢者の皆さんがこれからも頑張っていただくことを心から願っている１人でありますが、どうぞお答えをいただきたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"それが結果健康寿命の延伸になり、そして介護予防の推進になると考えていますので、そういった事業を高齢者クラブなどの活動の支援も通じて、いろいろな事業の仕掛けをして、なかなか今コロナで自粛をさせていただいているところもあるのですけれども。","voiceIndex":153,"id":"exchange-061"},{"speaker":"木村委員","kind":"質問・要望","question":"力強いそのお言葉、大変うれしく思います。我々もこれから年々年を取っていくわけでありますけれども、家族、そして社会が１つになって、これからの高齢者をしっかりと守っていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-062"},{"speaker":"松本委員","kind":"質問","question":"私からは、５５ページ、子どもの未来応援事業、７３ページ、同じく子どもの未来応援事業について伺います。この子どもの未来応援事業の寄附金ですけれども、これは報告を見ていくと、しあわせ食卓事業ということで今回は計上されているかと思います。","respondent":"伊東子育て応援課長","answer":"寄附というところの部分ですけれども、ガバメントクラウドファンディングということで、一応１２月末までに寄附をいただいて、それが食の支援ということで、しあわせ食卓事業のほうに活用させていただいているというのが現状です。","voiceIndex":157,"id":"exchange-063"},{"speaker":"松本委員","kind":"質問","question":"そうすると、例えば今回３００万円だったわけですけれども、これが物すごく多額に寄附が集まりましたなどという場合には、その寄附を受けたものというのは、どのタイミングでどのような使われ方をしていくというように考えればいいのでしょうか。","respondent":"伊東子育て応援課長","answer":"大きくは食材の購入費になるわけなのですけれども、そのような形で年に数回、令和３年度でいいますと、年に数回配布をしたという形で使われていくということになります。","voiceIndex":159,"id":"exchange-064"},{"speaker":"松本委員","kind":"質問","question":"その辺が会計の仕組み上、なかなか難しいのですけれども、１２月に結構集まったわけですよね。そうすると、今年度中に、例えば使い切れないなどということになるとか、そうするとちょっと何か、前年度などのものを見ていても、あまり予算上に計上されていないようにも見えるのですけれども、この辺りの仕組みというのはどうなっているのでしょうか。","respondent":"伊東子育て応援課長","answer":"基本的には、当初予算上５００万円と組んでいましたけれども、実績としては８００万円とか、昨年でいえば９００万円という形になってあります。それは、一応年度内に執行という形でやっております。","voiceIndex":161,"id":"exchange-065"},{"speaker":"松本委員","kind":"質問","question":"想定よりもたくさん入れば入るほど、たくさん使えるというように理解してよろしいでしょうか。","respondent":"伊東子育て応援課長","answer":"そのとおりです。目標額としては５００万円という形で、ここ２年、３年やってきておりますけれども、結果的には、初年度を除きまして、翌年以降は上回る寄附があったところです。それに関しては、年度内に使い切るという形で支出しております。","voiceIndex":163,"id":"exchange-066"},{"speaker":"松本委員","kind":"確認","question":"やはり寄附をした方から、どのように使われているのかということを聞かれることも多いので、確認をさせていただきました。明日以降、令和４年も５００万円と維持しているのですけれども、これももう少し高い目標を持つということもあってもいいのかなと思うのですが、この辺りはいかがお考えでしょうか。","respondent":"伊東子育て応援課長","answer":"その時々、これだけ子どもに関しての寄附の意思が高いというものは徐々に分かってきたところではありますけれども、この間、ちょっとコロナの関係ですとか、様々ほかの寄附にも流れるというような状況のある中で。","voiceIndex":165,"id":"exchange-067"},{"speaker":"松本委員","kind":"質問","question":"ぜひ高い目標を持っていただければと思います。その中で広報手段としては、例えば広報しながわなどにも載せていただいているのですけれども、区民の方も寄附できますということが、あまり目立たないのです。広報しながわの場合などというのは、あれは区民向けなので、もっと区民の方もできますということを強調していただいてもいいのではないかなと思うのですけれども、いかがでしょうか。","respondent":"伊東子育て応援課長","answer":"区民というところですけれども、様々いろいろとお話をする場面があるわけなのですが、そのときにはそのようなことも、区民も全然オーケーなのですよということで、それを広めてもらう意味で、その時々の会合等でお話はしています。","voiceIndex":167,"id":"exchange-068"},{"speaker":"松澤委員","kind":"質問","question":"私からは、補正予算書の６７ページ、品川区独自ボランティア「しな助」の活動、そして８５ページの密集住宅市街地整備促進事業についてお聞きいたします。この木密の市街地整備の事業についてです。密集住宅市街地整備促進事業の用地取得費についてお聞きいたします。今回この減額補正を計上している用地取得費、これについて当初の考え方と、減額に至った経緯を教えてください。","respondent":"森木密整備推進課長","answer":"今年度これまでに４か所の道路用地を取得しておりますけれども、特に広場用地について、地権者との交渉が進まなくて、年度内の取得の見込みが立たないというところでございまして、今回減額補正を計上しています。","voiceIndex":171,"id":"exchange-069"},{"speaker":"松澤委員","kind":"質問・要望","question":"人と人の話合いのあることですから、計画はなかなか進まないと思いますが、道路の幅を広げる、そのような防災広場の整備というものは、地域の防災性向上に大変大きく寄与する重要な取組だと考えていますので、土地をお持ちの区民の方に、事業の目的から手続の方法まで丁寧な周知をしていただいて、理解を得ながら進めていただきたいと考えています。この開放広場の今後の予定、これを教えてください。","respondent":"森木密整備推進課長","answer":"そのため、地域として一体的な広場整備ができないかということで、周辺の地権者の方へも声をかけさせていただきながら、ご意向を確認しています。","voiceIndex":173,"id":"exchange-070"},{"speaker":"松澤委員","kind":"質問・要望","question":"要は一体的な、基本的に、広場の整備、これを進めていくということですね。そのために周辺の権利者と話合いを進めているということは理解いたしました。地域からも大変要望があります。開放広場を今後防災広場として整備していく中で、消防団の格納庫の設置というものは、まず可能なのかどうか、ご見解をお伺いいたします。","respondent":"森木密整備推進課長","answer":"消防団の格納庫につきましては、設置の要望があった際には、消防団を所管する防災課とも情報共有をしながら、地域の意見を聞いて、設置の可否等について検討をしていきたいというふうに考えております。","voiceIndex":175,"id":"exchange-071"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひまたワークショップ、防災課との情報提供をしっかりとしていただきまして、広場の整備に当たっては、十分に要望を聞きながら、いろいろと対応して、必要な設備について検討していただければと考えています。次に、しな助に行きたいと思っています。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"区独自ボランティアしな助の減額についてのご質問かと思います。委員ご指摘のとおり、夏の東京２０２０大会、無観客となった関係上、しな助の活動の機会というものが大幅に減少してしまいました。そのことによる減額です。","voiceIndex":177,"id":"exchange-072"},{"speaker":"松澤委員","kind":"質問","question":"今回ちょっとしな助に対しては随分しつこく質問してしまいましたが、今回解散ということではなく継続、私も解散といろいろ聞いていたので、継続となったことは大変うれしいのですけれども、一度解散という方向性の中から、一体どのような話合いがあって継続に至ったのか、この経緯の説明をお願いいたします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"設立当初につきましては、東京２０２０大会の機運醸成のイベント等で、運営補助していただくという目的のために結成したものですので、大会が終了した時点でもうその役割は終わりということで、終了する予定でございました。","voiceIndex":179,"id":"exchange-073"},{"speaker":"松澤委員","kind":"質問","question":"そこでこの継続となりましたしな助なのですけれども、ボランティアに関わると今お話がありますが、これはもう具体的に社会福祉協議会につなげていくのか、それともスポーツボランティアでやっていくのか、また期日といいますか、これからの方向性というものを教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ボランティアマインドを醸成するような研修ですとか、またリーダーシップをもうちょっとつけていくような研修等も、併せて行うような予定です。そして、大体２年程度を目途に力をつけていただいて、しな助のほうは解散したいというような、そのような予定でおります。","voiceIndex":181,"id":"exchange-074"},{"speaker":"松澤委員","kind":"質問","question":"今ちょっと社協のお話が出たときに、この社協のボランティアセンターというものは、簡単でいいので、何名現在登録があって、年齢や性別の比率、そしてまた、このボランティアセンターの中の品川区地域貢献ポイント事業というものがあるのですけれども、この対象者は６０歳以上とあったのですが、この年齢制限がある理由というものを教えてください。","respondent":"宮尾高齢者福祉課長","answer":"それから年齢構成ですが、中心は６０代、７０代の女性が、全体の大体半分近くを占めていると、このような状況だというふうに聞いております。","voiceIndex":183,"id":"exchange-075"},{"speaker":"松澤委員","kind":"質問","question":"ボランティア開始の流れの中で、これから先、多分相談から活動先、ボランティアで活動する現場を見て、活動するしないという、そういった流れで認識していますけれども、何というのですか、このボランティアの活動の大事なポイント、これは幾つか項目があると思うのですが、やはりある程度心構えを持って、しっかりとこのボランティア活動に臨む、研究であったり、研修であったり。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"社協のボランティアセンターのほうにも、もう一応コンタクトを取っているのですけれども、一緒に連携しながら、皆さんが楽しみながら、気づいたら社会貢献していたというような、そのような状況ができるといいかなというふうに考えています。","voiceIndex":185,"id":"exchange-076"},{"speaker":"松澤委員","kind":"質問・要望","question":"東京都では東京ボランティアレガシーネットワークというものを開設しています。品川でもこういった、要は目に見える、ボランティアの活動をやりたいという、また、どこに行けばいいということが目に見える、そういった可視化といいますか、分かりやすいボランティアのシステムの構築、これはとても大変いい取組になると私は思っておりますが、可視化で分かりやすいこのシステムのご見解をお聞かせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今後そこも、いろいろなボランティアのジャンルが一緒に連携して大きなものをつくるということは、研究していきたいと考えています。","voiceIndex":187,"id":"exchange-077"},{"speaker":"横山委員","kind":"提案","question":"今日は補正の日なのですけれども、令和４年度の当初予算案のプレス発表を私が知ったときに、オアシスルームの利便性の向上、保育の質の確保・向上、またＨＰＶワクチン、生理用品の設置ほか、私たち会派の提案、要望を受け止めていただいて、実現をしようとしていただいているということに対して、私はほかのメンバーとともにとても感動しましてうれしかったです。本当にありがとうあります。質問に移ります。","respondent":"加島児童相談所移管担当課長","answer":"児童相談所移管推進事業の内容についてご説明を申し上げます。こちらは大きくハード整備とソフト面の体制検討に分かれまして、ハード整備につきましては、現在工事を着手いたしまして、今後、令和５年１月の竣工を予定しています。","voiceIndex":190,"id":"exchange-078"},{"speaker":"横山委員","kind":"質問・要望","question":"区のお考えをお伺いしたいと思っています。社会資源を紹介することがつなぐということではなく、先方にオーケーかどうかの確認を取っていただいて、必要であれば同行支援を行い、当事者がつながったことを見届けるというところまでがつなぐであり、今後も引き続き区職員の方々には実行いただきたいということを要望いたしますが、区はどのようにお考えでしょうか。","respondent":"山下子ども家庭支援センター長","answer":"その保健センターの保健師より、子ども家庭支援センターのほうにも連絡が参りまして、一緒に面談をするというようなことも、緊急な場合であっても対応しているところがあります。今後も引き続き、同行支援等を含めまして、丁寧な対応に取り組んでまいりたいと考えています。","voiceIndex":192,"id":"exchange-079"},{"speaker":"横山委員","kind":"質問・要望","question":"様々ご紹介、ありがとうございました。引き続きその辺りは注意して、注意というか、アンテナを張っていただきながら、取組を進めていただきたいと考えています。２点目に、代替職員雇用経費についてお伺いをいたします。代替職員雇用経費について、こちら予算書の内容を簡潔にご説明ください。","respondent":"崎村人事課長","answer":"令和３年度につきましては、今回のコロナの第５波、第６波の感染症対応強化に伴う保健予防課への増員のほかに、各種臨時給付金の関係事務が年度途中で新規に発生したことによる、繁忙職場への人材派遣の増員に伴いまして、約６,０００万円の増額補正をお願いしています。","voiceIndex":194,"id":"exchange-080"},{"speaker":"横山委員","kind":"質問・要望","question":"ご説明ありがとうございました。１日でも２日でもいいかなと思うのですけれども、職員の方々には、交代でリフレッシュ休暇やチャレンジ休暇を取っていただきたいというふうに要望いたします。責任感があるから頑張ってしまいますが、そのような職員の方々をどのように守っていくのかということも、個人の裁量に頼らず、いま一度組織的に考えてほしいと考えています。","respondent":"崎村人事課長","answer":"区では、令和２年に策定しました特定事業主の行動計画の中でも、充実した区民サービスを実施していくためには、ワーク・ライフ・バランスを実現していくことが重要であるとしまして、職員全員の年次有給休暇取得日数を１０日以上とすることを目標として掲げて。","voiceIndex":196,"id":"exchange-081"},{"speaker":"おくの委員","kind":"質問・要望","question":"私からは、６１ページ、非核平和都市品川宣言事業に関わって、ウクライナを侵略したロシアに品川区が抗議することを求めて質問いたします。２月２４日、ロシアのプーチン政権がウクライナへの侵略を開始しました。そこで、非核平和都市品川宣言を持つ品川区です。ロシアのプーチン政権に対して強く抗議をし、軍事行動を直ちに中止することを求めるべきだと思いますが、いかがでしょうか。","respondent":"古巻総務課長","answer":"ただ、やはり他国への対応といった意味におきましては、従来からもお話をさせていただいているとおり、これは国が専ら担うべき責務である、役割であるというようなことで考えておりますので、現時点におきましては。","voiceIndex":200,"id":"exchange-082"},{"speaker":"おくの委員","kind":"質問・要望","question":"国が専ら担うべきこと、それが基本だというようなご答弁でしたけれども、非核平和都市品川宣言、その内容は最初から外交・防衛に関することそのものなのです。それについて、品川区が自ら進んで宣言したものです。そこで改めて伺います。やはりプーチン政権に対して、ウクライナ侵略には強く抗議し、軍事行動を直ちに中止することを求めるべきだと私は思います。いかがでしょうか。もう一度伺います。","respondent":"古巻総務課長","answer":"非核平和都市品川宣言の趣旨につきましては、委員もご紹介のとおりですし、また先ほども答弁させていただいたとおりですけれども、やはり国は国の役割があり、自治体は自治体の役割があるということでは、品川区といたしましては。","voiceIndex":202,"id":"exchange-083"},{"speaker":"おくの委員","kind":"質問","question":"区としての役割ということですけれども、それに関して、外交・防衛に関することをそもそも宣言で扱ったのだから、品川区は自ら進んでそのようなことを扱う決意を表明したものだということが宣言に表れているのだということを申し上げました。それに加えて、このプーチン大統領の態度、２月２４日に、現代のロシアは今や世界で最も強力な核保有国の１つだと。そうは思いませんか。この点も伺います。","respondent":"古巻総務課長","answer":"ただ、取組に関しましては、品川区としては様々な平和事業を取り組んでおりますので、また、そういったところから、しっかりと非核平和都市品川宣言への取組が進むようにやっていきたいというふうに考えております。","voiceIndex":204,"id":"exchange-084"},{"speaker":"おくの委員","kind":"質問","question":"さらに加えて、２月２７日には、このロシアは、欧米諸国の経済制裁や攻撃的な発言を根拠として、その核戦力をいわゆる特別態勢に移行させるように命じました。国際社会を核で威嚇する姿勢をさらに鮮明にしたのです。品川区は、核兵器を使うというロシアに対して、宣言の立場でなぜ抗議をしないのか。宣言にのっとって抗議すべきだと思うのですけれども、いかがでしょうか。","respondent":"古巻総務課長","answer":"ただ、区といたしましては、区として与えられたといいましょうか、区としてやるべきことをしっかり取り組んでいくというスタンスで取り組んでまいりたいと考えています。","voiceIndex":206,"id":"exchange-085"},{"speaker":"おくの委員","kind":"質問・要望","question":"例えば武蔵野市では、２月２８日、声明、コメントですか、市長が、ロシアが核兵器使用を示唆したことに関する市長コメントと題して、「私は、世界連邦宣言都市及び非核都市宣言都市である武蔵野市の市民を代表し、また、平和首長会議の一員として、地域や国際社会の平和と安全を著しく損なう今回の行為に対し断固として抗議と遺憾の意を示すとともに、一日も早い攻撃の停止と撤退及び。","respondent":"古巻総務課長","answer":"それぞれの自治体において、それぞれの考え方があろうかと思います。品川区におきましては、国は国の役割をしっかり取り組んでいただく、品川区としてしっかり区の役割を取り組んでいく、そのような形で進めていきたいというふうに考えております。","voiceIndex":208,"id":"exchange-086"},{"speaker":"新妻委員","kind":"質問・要望","question":"６５ページ、シルバー大学、７３ページ、すまいるスクール運営費、７５ページ、八潮中央保育園改修工事実施設計委託について伺ってまいります。そのような中で、シルバー大学について伺ってまいります。第８号一般会計補正予算では、約４３０万円の補正、マイナス補正となっております。この内訳を教えていただくとともに、令和３年度の現在までの開催状況をお知らせください。","respondent":"篠田文化観光課長","answer":"令和３年度の実施状況ですけれども、委員からご指摘あったとおり、令和２年度はほとんどできなかったような状況ですが、今年度につきましては、例えばリスクを下げるために定数を半分にしたりなど、様々感染予防対策を取った上で、基本的な講座、途中の感染状況によっては１回。","voiceIndex":211,"id":"exchange-087"},{"speaker":"新妻委員","kind":"質問・要望","question":"私はこれまで、このシルバー大学の充実を求めて、議会でも質問をしてまいりました。かなり人気のある、このシルバー大学に、なかなか入れないというお声もいただきましたので、この人数の拡充や、また、シルバー大学のテーマとして取り上げられております終活について、このことについても、この終活がテーマになったことの経緯なども確認をさせていただき、このシルバー大学の充実を求めてきました。","respondent":"篠田文化観光課長","answer":"次年度の予定です。基本的には、今年度、それから昨年度、かなり縮小した状態でしたけれども、予算上は、来年度につきましてはそれ以前の状態にできるだけ戻せるような形で実施をしていきたいというふうに考えているところです。","voiceIndex":213,"id":"exchange-088"},{"speaker":"新妻委員","kind":"質問・要望","question":"これまで、品川区議会公明党は、コロナワクチンの予約ができない高齢者が多くいたことから、高齢者へのデジタルデバイド解消への対応を強く要望してまいりました。高齢者地域支援課だけではなく、シルバー大学の講座の中でも、このオンラインやＩＴ、スマホの活用などのテーマを設けて、ぜひ開催をしていただきたいと思いますが、見解を伺います。","respondent":"篠田文化観光課長","answer":"そういった講座としての実施につきましても、なかなかそういった環境を整えるのは難しいということがございまして、今のところは取り組んでいないというところは思っています。ただ一方で、委員からご指摘があったとおり、高齢者の方からも、オンラインでもやれないかと。","voiceIndex":215,"id":"exchange-089"},{"speaker":"新妻委員","kind":"質問・要望","question":"続きまして、すまいるスクールについて伺います。今回補正では、運営等委託としてマイナス１,０００万円となっておりますが、まず詳細をお伺いいたします。併せて、就学人口が増えている中での、今後、感染が収まってきた後のすまいるスクールの受入れについて、受け入れられる場所があるのかどうかというところ、どのようにこの新学期以降、場所の確保をされているのか、併せてお伺いをいたします。","respondent":"廣田子ども育成課長","answer":"コロナ禍が収束した後の受入れに関しては、人数が増えることでかなり苦慮することは予想されるのですけれども、学校と教室の使い方について、一緒に使っていくという、ある限られた面積の中でやっていかなければならないので、学校等と協力しながらということで。","voiceIndex":217,"id":"exchange-090"},{"speaker":"西本委員","kind":"質問","question":"というのは、昨年の暮れですか、子育ての給付金の件で、１０万円一括にするのか、５万円分割にするのかということで、結局５万円の給付金で決まったわけでありますけれども、補正予算を決めましたが、結局その後また臨時議会で１０万円一括給付があったのです。なので、何が起きたのか、それだけの余裕が品川区の体制としてはあるのでしょうかということ。その辺をお聞きします。目的と役割をお聞きします。","respondent":"黒田財政課長、廣田子ども育成課長、佐藤企画調整課長","answer":"補正予算全般ですが、補正予算の編成に当たりましては、当初予算の編成と併せて、年度末までの執行の状況を勘案して。すまいるスクールに関しましては、放課後の児童の安全・安心で過ごせる居場所としています。区長と都知事との懇談会というものを毎年行っております。各所管においては、各部局との連携を十分深めて、積極的に連携を取っているところです。","voiceIndex":220,"id":"exchange-091"},{"speaker":"西本委員","kind":"質問","question":"その後福祉部のほうですか。それで夜間７時まで見ることになったということで、初めは全児童対策だったのです。そうですね。どのようなことで、いわゆるどのように子育て、いわゆる保育ですから。今回ちょっとお聞きしたいのは、親育ての観点からすると、やはり私は必要だなと思っているのですが、その事業については、どのような方向性を持って保育事業を組み込んでやっているのか、お聞きしたいと思います。","respondent":"佐藤企画調整課長、廣田子ども育成課長","answer":"先ほどもご答弁したとおり、特別区長会を通じたところ、また各所管との対応、また、区長と都知事との懇談会というものも、ホームページにも出ておりますけれども、区長のほうは区で行っていることをまずしっかりと伝えて。保護者の方とも連携を取りながらというところなのですけれども、保育園とは違いまして、子どもの発達段階からいうと、自立もしていかなければいけないというところを。","voiceIndex":224,"id":"exchange-092"},{"speaker":"西本委員","kind":"質問","question":"親育てということの観点からはいかがでしょうか。今協力し合ってということでありますが、やはりまだまだ、学童保育のときには親教育というか、親支援というか、親に対してのアプローチもいろいろやっていました。今どうなのでしょうか。いかがですか。","respondent":"廣田子ども育成課長","answer":"確かに学童クラブの頃に関しましては、決まった４０人なら４０人、６０人なら６０人のお子さんと保護者という向かい合い方だったのですけれども、今につきましては、学童と違いまして、希望されれば利用できるというような形になっておりますので。","voiceIndex":227,"id":"exchange-093"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、親教育という意味でいうと、やはりもう少し力を入れていただきたいなと思います。ただそれというのは、子どもの育ちからするとどうなのだろうか。必要な人、必要なお子さんはいます。でも、面倒だからとか、そのようなことで、仕出し弁当を使えばいいのではないかというような議論というものは、やはりあまりに子どもを無視している状況ではないかと思いますが、その辺の考え方はいかがでしょうか。","respondent":"廣田子ども育成課長","answer":"預けっ放しというような形にならないように、午後６時を過ぎた場合には必ずお迎えに来ていただくというところで、コミュニケーションを取っていくというところは譲らないでいきたいと思っているところです。","voiceIndex":229,"id":"exchange-094"},{"speaker":"小芝委員","kind":"質問","question":"私からは７９ページの収集運搬事業と、８１ページの新型コロナウイルス感染症対応特別助成についてお伺いをいたします。収集運搬作業費についてです。この外国人のごみ出しについてお聞きいたします。品川区では、現在外国人による、主に定住の外国人によるごみ出しについて、どのような案内、啓発をされておるのか、教えてください。","respondent":"品川品川区清掃事務所長","answer":"ただ、一部には、やはり地域のほうからごみ出しがあまりよくないというようなことで行ってみると、外国人の方がお住まいだったりしますと、清掃職員のほうが訪ねまして、やはり同様のごみパンフレットを持って説明をして、大体しばらくすれば改善がされているような状況です。","voiceIndex":232,"id":"exchange-095"},{"speaker":"小芝委員","kind":"質問","question":"そうなりますと、要は言葉そのものが分からないのか、それともそのパンフレットの意味がなかなかそしゃくできていない、伝わっていないのか。どちらかなのかなとは思いますけれども、今の所長の答弁を聞いていますと、なかなかその、伝わっていなかったのかなというような認識でよろしいのでしょうか。","respondent":"品川品川区清掃事務所長","answer":"それぞれいろいろな生活習慣があると思いますので、そういった感覚で、最初はごみを出してしまうということがあるかもしれませんが、いろいろと清掃職員もコミュニケーションを取って、いろいろなやり取りをすることによって、その外国人のごみの出し方というものは。","voiceIndex":234,"id":"exchange-096"},{"speaker":"小芝委員","kind":"意見","question":"そういった取組を事前にやっておくということも１つの手かなとは思いますが、その辺のお考えのほうお聞かせください。","respondent":"品川品川区清掃事務所長","answer":"例えば、やはり品川区に住んでいる外国人でも、いろいろな国の方がいらっしゃいますので、それに全部対応した紙を貼っていくということになると、またかなり多くの量になるかなというところも考えられますし、ただ、やはりそのような外国人のごみの出し方については。","voiceIndex":236,"id":"exchange-097"},{"speaker":"小芝委員","kind":"質問・要望","question":"次の質問です。新型コロナウイルス感染症対応特別助成について、当初予算では１,０００件分の見込みをされていましたが、この助成金が前年度に引き続き申請ができるという点で、最初の年度はアクリル板や空気清浄機など、感染を防ぐためのツールに使い道を求めてきたのに対しまして、２年目については、恐らく別の用途に使用する目的で申請されている方もいらっしゃったのではないかなと思います。","respondent":"遠藤商業・ものづくり課長","answer":"当初予算、１,０００件という形で出させていただきまして、おおむね上半期から、コロナ自体がそれほどこう、ずっと続くのかなという部分もございまして、昨年、令和２年度と同じ予算で当初出させていただいたのですけれども、実際またオミクロン株などが出てきて。","voiceIndex":238,"id":"exchange-098"},{"speaker":"小芝委員","kind":"質問・要望","question":"先ほど更新された、延期された助成金のほうで、使い道というのは具体的に何か顕著なものがありましたら、ぜひ教えていただきたいのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"実際に使われているものですけれども、やはり当初と同様に、空気清浄機とか、衛生部門のものが非常に多いところではあるのですが、特に１０月、１１月ぐらいに一時収まった時期があったかと思います。","voiceIndex":240,"id":"exchange-099"},{"speaker":"小芝委員","kind":"提案","question":"特別助成が始まった頃に比べまして、経費の主な項目は、今課長おっしゃったとおり、感染飛沫対策から変化はあったと思います。そういった方にも寄り添った、新しい販路への道筋を、例えば品川区のほうで相談を受けたり、また専門スタッフを紹介するような案内を、ホームページ等で掲示することを提案したいと思いますが、ちょっとお考えのほうお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの部分につきましては、今ご指摘ございましたとおり、引き続きそのような部分の周知なども使いながら、新しい販売方法という部分について周知をさせていただければと考えています。","voiceIndex":242,"id":"exchange-100"},{"speaker":"小芝委員","kind":"意見","question":"商店のお店の方々には横のつながりがあるところもありますが、そのような中ではお互いに切磋琢磨して、この助成金にたどり着くこともあると思いますけれども、より多くの個人事業主、店舗の方が等しく機会を得られるよう、取り組んでいただきますようお願いをいたしまして、終わらせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":244,"id":"exchange-101"},{"speaker":"渡部委員","kind":"質問","question":"６３ページの代替職員雇用経費など、いろいろなページの職員給与費のところで、人事のことで少しお伺いしたいということと、あと、先ほど小芝委員のほうからもありました新型コロナウイルス感染症対応特別助成など、その辺、産業支援について伺っていきますが、人事の話に入る前に、先ほど若林委員の質問だったでしょうか、誰の質問だったかちょっと忘れてしまいました。","respondent":"古巻総務課長","answer":"今委員からもご紹介いただきました、品川区新型インフルエンザ等業務継続計画というものがございまして、基づくとするとこちらの計画ということにはなるのですけれども、かなりこの計画を策定したところと、現在の感染症の状況というものは違いがありまして、その辺り。","voiceIndex":247,"id":"exchange-102"},{"speaker":"渡部委員","kind":"質問","question":"そのような中で、様々人事に関わることでお伺いしていきたいなと思ったのですが、まず、その人数がどうこうというよりも、例えば、先ほどのＢＣＰにもつながっていくのですけれども、職員の皆様方が日常勤務をされている中で、当然それはコロナにだって罹患される方はいらっしゃる、そうなった場合は特定の休みというものを取らなければいけなくなる中で、いわゆるクラスターのような形で。","respondent":"崎村人事課長","answer":"働き方改革という観点からは、やはり有効な手段ではあると認識しておりますので、引き続き試行しながら検討して、取り組めるところから進めていきたいと考えております。","voiceIndex":249,"id":"exchange-103"},{"speaker":"渡部委員","kind":"質問・要望","question":"今、現状コロナ禍における対策の中で、できることはやっていただいていると思いますし、先ほどＢＣＰのお話もお伺いしましたけれども、その中で取れる対策を取って続けていただきたいなと思います。それで、ちょっと話は動くのですが、例えば今民間企業においても、大量退職があったり、企業の情勢によって早期退職等を図られることがあったりということをお伺いしています。","respondent":"崎村人事課長","answer":"今ご指摘いただきましたように、専門性を求められる職というところについては、こういったところで採用ができるのかなとは思っておりますけれども、これについても人事委員会の承認等々をいただく必要があるものではありますが。","voiceIndex":251,"id":"exchange-104"},{"speaker":"渡部委員","kind":"質問・要望","question":"それは何かといったら、自己負担なしで行えるといったセールス等にはご注意くださいというような、何か詐欺が横行していますよというような書き方が出てきて、赤字になっていてなどというようになっているのだけれども、ちょっとこの辺の説明をいただきたいなというところと、たしか１事業者１年度１回だったと思うのですが、これは１業者というのは、例えば個人事業主であれば個人が１回。","respondent":"遠藤商業・ものづくり課長","answer":"公平性という部分ありますので、そのような形で対応していますので、複数店舗を持っていただいても、事業主が１人、１という形であれば、１回だけのご利用でお願いしています。","voiceIndex":253,"id":"exchange-105"},{"speaker":"渡部委員","kind":"質問・要望","question":"それで、これからやはり品川区内で事業を継続していただくためにも、この辺の融資あっ旋、当然返せないものは貸せないわけですから、それは銀行なり、協会が判断していただくにしても、そのようなところから相談が役所にあった場合、どのような手続で、例えば借換えができたりとか何だとか、案内ができるようになっているのか、そこだけ教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"来年度の予算という形でお願いしていますけれども、借換専用資金なども用意いたしまして、いろいろな方法があろうかと思いますので、そのようなものを活用して、次年度以降も事業者様を全力でサポートするという形で考えているところです。","voiceIndex":255,"id":"exchange-106"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、令和３年度補正予算の国民健康保険、後期高齢者医療、そして介護保険について伺いたいと思います。１１１ページです。そうすると、令和３年度の区の法定外繰入れは、この当初予算の１０億円余から、今回の補正予算のマイナス６億円余を引いた３億９,５４６万９,０００円ということになるのか、これでいいのか、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":258,"id":"exchange-107"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、令和３年度補正予算の国民健康保険、後期高齢者医療、介護保険について伺いたいのですが、ではまず介護保険から伺いたいと思います。介護保険は、令和３年８月から介護保険の補足給付が改悪をされました。それなのに、この低所得者対策を縮小するということが、この８月に行われたのです。これは深刻な矛盾だと思うのですけれども、区の見解をまず伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"こちらは介護保険全体に関わる制度の見直しでございまして、趣旨といたしましては、在宅で暮らす方との食費、居住費に係る公平性、それから負担能力に応じた負担を図るという観点だというふうに認識をしています。","voiceIndex":260,"id":"exchange-108"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、この補足給付の改悪は主に２つです。１つ目が食費の負担。介護保険加入者の収入は８段階に区分されていまして、その第１段階から第３段階までが補足給付の対象です。月額５万９,０００円だったものが８万２,０００円、２万３,０００円も値上げがされます。この対象から外れてしまう人が区民で何人ぐらいいるのか、分かれば教えていただきたいのですが。","respondent":"宮尾高齢者福祉課長","answer":"対象から外れる方の人数ですけれども、ちょっと厳密にその人数ということではないのですが、目安といたしまして、令和２年度と令和３年度の同じ時期を比較した人数で、大体１割ぐらい、今年度に入ってこの対象の方が少なくなっているという情報を持っております。","voiceIndex":262,"id":"exchange-109"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当にひどい改悪だなと思うのです。低所得者の方にもう全財産を吐き出させるというような、これがもう国の思惑だと思うのですけれども、どの人も安心して老後を迎えられるように、こうした改悪はやめるべきと、ぜひ国に求めていただきたいと思います。なので、令和３年度の区の法定外繰入れというものは、この当初予算から今回の補正予算のマイナスを引いたものになるのかということを確認したいと思います。","respondent":"池田国保医療年金課長","answer":"法定外繰入金につきましては、今回の補正で３億９,０００万円ということでお願いするところです。","voiceIndex":264,"id":"exchange-110"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この国保の法定外繰入れが僅か３億９,０００万円ということで、２０１８年に国保の広域化が強行されて、法定外繰入れはゼロにしていくことが最大の目的で今進められています。引下げこそすべきですし、そのための税金投入をしていただきたいと思いますけれども、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"ただいまの保険料について、もう少し投入をというお話だと思いますけれども、実際に国民健康保険料につきましては、平成３０年度に広域化になりましてから、かなりの一般財源を入れさせていただきまして、今年、令和３年度の保険料につきましては。","voiceIndex":266,"id":"exchange-111"},{"speaker":"石田（ち）委員","kind":"質問","question":"平成２２年の頃から見れば、３５億円入れていた法定外繰入れが、もう今や３億円です。コロナもまだ終わっていませんし、まだまだ苦しい状態続いていますので、ぜひ、さらなる法定外繰入れの投入をお願いしたいと思います。今回のこの特例軽減、令和３年度で終了されたというところですけれども、これに対して、値上げに対しては区としてどう対応されたのか伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"今のお話につきましては、令和２年度、３年度の保険料についてのことだと思いますが、こちらのほうの保険料の値上げにつきましては、私どものほうではこれを国なり、東京都後期高齢者医療広域連合のほうで決めたことですので。","voiceIndex":268,"id":"exchange-112"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"広域連合に従っていくというところですけれども、それで区長会などで要望していくということなのですが、今回のこの令和３年度で、区が軽減のために負担したものというのはあるのでしょうか。分かれば教えていただきたいと思います。","respondent":"池田国保医療年金課長","answer":"後期高齢者医療の保険料については、自治体のほうで１００％受け持たなければいけないというものがございまして、例えばこの保険料の未収金についてのものなどもありますし、レセプトの点検手数料とか、そういったものについて４つの項目がありますけれども。","voiceIndex":270,"id":"exchange-113"},{"speaker":"石田（ち）委員","kind":"質問","question":"今伺ったのは、今課長が答弁されたのは、いつも入れている、入れなければならない軽減対策のお金です。ではなくて、特例軽減が終わることによって、これだけ３倍にも値上がってしまう、そのような状況に対して、軽減のために入れた額はあるのかということをお聞きしたのです。お願いします。","respondent":"池田国保医療年金課長","answer":"ですから今私がお話ししたものについては、軽減のために一般財源のほうでずっと入れさせていただいているです。","voiceIndex":272,"id":"exchange-114"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"要するに、今回の令和３年度で、特例軽減がなくなることで入れたものはないということなのです。それで、最後に意見表明をさせていただきたいと思います。法定外繰入れは、マイナスするのではなく、さらなる投入を求めたいと思います。よって、今回の令和３年度補正予算、第２号議案、国民健康保険、第３号議案、後期高齢者医療、第４号議案、介護保険に反対の態度を表明して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":274,"id":"exchange-115"},{"speaker":"たけうち委員","kind":"質問・要望","question":"９８ページ、９９ページ、繰越明許費のところでお願いします。それから９９ページのほうは、生活保護費のところで、住民税非課税世帯等臨時特別給付金のところでお聞きしたいのですが、この中で特にもう既に始まって、２月下旬から相談を開始されるというふうに聞いていますけれども、家計急変世帯の相談について、今現在の相談件数やその申請状況、そうした状況について教えてください。","respondent":"伊東子育て応援課長","answer":"それと、この給付金に関しては、昨年１１月ぐらいからお話があって、その後いろいろな変更がありまして、こちらのほうも内部的にもバタバタとしたところではありますけれども、年末に１０万円一括支給ということで、児童手当の受給者に関しましては１万８,９４１世帯。","voiceIndex":276,"id":"exchange-116"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それから家計急変世帯については、８４件の申請ということですが、そうすると、先ほどちょっとありましたけれども、百二、三十件の相談があって、そのうち申請できたのが８４件ということなのか、相談がどれくらい来ていてということ、それから当初の見込みでは、まだこれから９月ぐらいまであると思うのですが、見込みでは４,０００世帯分ぐらいの見込みを出しておりますけれども、そこについて今の現状。","respondent":"佐藤企画調整課長、櫻木生活支援臨時給付金担当課長","answer":"一方国において、社会保障に関わる所得制限について検討しているというところも把握しておりますので、その辺も踏まえながら、今後引き続き、また所得制限の在り方について検討してまいります。３月から、町会、自治会のほうにありますふれあい掲示板、区内５００か所以上あるかと思うのですが、そちらのほうにポスターを掲示する、またはホームページやケーブルテレビ品川等で放送していただく等でもって、積極的に周知をして。","voiceIndex":281,"id":"exchange-117"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今の、生活保護費のほうの臨時給付金ですけれども、いろいろな方がいらっしゃって、また、対象ではないがどうなのかというところで来られる方がいると思うので、丁寧に対応していただいていると思いますけれども、またお聞きする中で、例えば今回これは駄目ですが、このようなものがありますよとか、そのようなところまでぜひきめ細かに対応していただくとともに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":284,"id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問","question":"もう一つ、ちょっと順不同ですが、５５ページの繰入金についてお尋ねします。先に、この積立金のところです。これは寄附が予想される、想定されるので、その受皿ということでその項目が入っているのは理解できるのですが、この庁舎整備のほうの条例に関して、性格が異なるというふうに感じるのですけれども、この条文が、つまり寄附金について含んだというところは、何かお考えがあってのことでしょうか。","respondent":"東野庁舎計画担当課長","answer":"その中の基金の目的のために寄附された寄附金の額、こちらにつきましては、区民の方から実際に既に申し出がございました。ということで、これを区民の方からのご意向に沿った形での寄附という形で使いたいということで、こちらに載せさせていただいたものです。","voiceIndex":286,"id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問","question":"区民の方からそういった寄附、ありがたい寄附の申し出があったと。そうすると、今どなたかという話は、当然いろいろな事情があってあれなのですが、複数、あるいは幾つかのというようなことですから、そういった寄附が想定、ごめんなさい、事実として申し出があるということでよろしいでしょうか。","respondent":"東野庁舎計画担当課長","answer":"実際に申し出がございました。まだ１件ですが、今後増えていくことが想定されますので、活用させていただければと思います。","voiceIndex":288,"id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"寄附はありがたいお話ですので、十分に活用をしていただければと思います。それで、今の積立金のお話ですが、補正予算の中では３０億円という形であります。想定としては４００億円かかるというような想定が出ています。そうすると、目標額が、総務委員会の資料だと１２０億円ということなのですが、残りの２８０億円の財源はどのように調達するという、現時点で想定をされているのでしょうか。","respondent":"黒田財政課長","answer":"庁舎整備基金の目標積立額は、総務委員会のほうでも１２０億円というようにお答えさせていただきまして、残りの財源ですが、基本的に庁舎ですので、起債を検討しております。","voiceIndex":290,"id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"起債ができる部分、そしてできない部分、そして基金、それから、先ほどあった国なり都からの分担金ということですが、そのできる部分という話で、具体的にはどのような起債が想定され、それが起債可能という見込み、そちらをご説明いただきたいのですが。","respondent":"黒田財政課長","answer":"記載できる見込みにつきましては、庁舎の基本構想が出た後、１回東京都と事務的なところで区の基本構想の説明等に伺っていて、起債を検討してというところは東京都の起債を担当する部署とも連携を取っておりますので、今後基本計画が固まってくる中で。","voiceIndex":292,"id":"exchange-122"},{"speaker":"高橋（し）委員","kind":"質問","question":"その見込みということに関してはまだ、今、ご答弁なかったので、そこは分からないという状況と認識してよろしいでしょうか。そうすると、これまで地方交付税の措置、財調の都市計画交付金などによる財源の裏づけがある起債を、品川区ではずっと行われてきたと伺っています。そちらの見込みも伺いたいのですが、いかがでしょうか。","respondent":"黒田財政課長","answer":"例えば学校ですと、用地を買いますと、記載した償還元金については、財調で需要として算定されるでありますとか、都市計画事業ですと、地方債相当分については財調のほうで措置されるという制度がありますが、庁舎につきましては。","voiceIndex":294,"id":"exchange-123"},{"speaker":"高橋（し）委員","kind":"提案","question":"一般質問のほうで、基金の制定というか、条例の制定をご提案して、ここで今審議されているという基金条例については、大変ありがたいと思います。ただ、令和４年度の予算には５億円が計上されていて、それで総務委員会の資料では３０億円掛ける４年で１２０億円という計算なのですが、この５億円と３０億円、２５億円の差があるのですけれども、これはどのような経緯なのでしょうか。","respondent":"黒田財政課長","answer":"ただ、そうは申しましても、当初予算を編成するに当たりましては、様々な事業の財源を確保しなければならないというところで、令和３年度に最終補正で３０億円計上させていただきまして、今後も歳入の状況等を見ながら。","voiceIndex":296,"id":"exchange-124"},{"speaker":"高橋（し）委員","kind":"質問","question":"その事情は分かるのですが、それなら、どうして総務委員会のほうに３０億円ずつ積み立てて１２０億円というふうに数字をしっかりと書いてあるのかということです。ということは、補正予算をあらかじめ想定して当初予算を立てるということは、まずないということだと思うのですが、その点についていかがでしょうか。","respondent":"黒田財政課長","answer":"補正予算を想定して当初予算を立てているということではないのですが、当然その執行率の関係もありまして、必ずというわけではありませんけれども、毎年度歳入状況を見ながら、基金の積立てのほうにつきましては、他の基金についても行ってきてまいりますので。","voiceIndex":298,"id":"exchange-125"},{"speaker":"高橋（し）委員","kind":"質問","question":"令和４年度予算の話なので、これ以上はあれですけれども、それだったら初めに３０億円というふうにして計上すればよかったのではないかと。別の機会にお伺いします。最後に、先ほど床の話が出ましたが、総合庁舎の持分割合、国と都についての協議は、どのように現状は進んでいるのでしょうか。","respondent":"東野庁舎計画担当課長","answer":"持分割合につきましては、現在国、都が、現在の庁舎でいきますと、両方で２３％をお持ちということになりますので、それをベースに、新しい庁舎のほうでどれだけの必要面積か、そういったものを含めまして、協議を続けているところです。","voiceIndex":300,"id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"質問","question":"別の機会に伺いたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":302,"id":"exchange-127"},{"speaker":"湯澤委員","kind":"質問","question":"私からは、８６ページ、公園管理費、９１ページ、学校環境整備事業、関連して平和花壇にも触れたいと思います。区も、日頃から様々な公園整備、管理を行っていると思いますが、どうしても手が届かない、そういったところに関しましては、みどりと花のボランティアの活動にも支えられているかと思います。公園や区道への緑化や整備に対する区の考えを教えてください。","respondent":"高梨公園課長","answer":"区といたしましても、ぜひ区だけではなく、区民とともに一緒になって、緑化に対する意識を向上をさせる、していくということで、今後も積極的に取り組んでまいりたいというふうに考えているところです。","voiceIndex":304,"id":"exchange-128"},{"speaker":"湯澤委員","kind":"質問・要望","question":"東京都公園協会でも、協力金、助成金ですね。地域の輪が広がれば、町会会員の促進、そういったものにもつながるかもしれませんし、また、健康促進や観光にもつながれば、助成金以上の成果物になるかもしれません。緑化を進めるに当たって、課題といったものがあれば教えていただきたいので、事業参加者の拡充、それから活動の数値化、課題の３点、お知らせください。","respondent":"高梨公園課長","answer":"達成感といったところで、面積の数値化といったようなアイデアがございましたけれども、ホームページ等、今またＳＮＳ等もありますので、しっかりとその活動の状況を区としても発信していって、まずはしっかりと。","voiceIndex":306,"id":"exchange-129"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ただ、屋上部分につきましては、様々無駄なく活用していらっしゃるというお話や、あと学校菜園などにも取り組んでいらっしゃるということは承知しているのですけれども、例えば壁面緑化などで、子どもたちが自然と触れ合って学べる機会をより増やすことが大変重要だと思いますので、ぜひ拡充していただきたいと思いますが、これまでの取組と。","respondent":"有馬庶務課長","answer":"現在、学校では大体２４校程度屋上緑化をしているところでございまして、現在は改築校において、エコスクールというような形で、太陽光パネルの設置とともに屋上緑化を進めているということですので、また今後。","voiceIndex":308,"id":"exchange-130"},{"speaker":"湯澤委員","kind":"質問・要望","question":"この事業自体は総務課の所管になるかと思うのですけれども、世界では今、本当にあってはならないことが起こっておりまして、恒久平和を願う本区として、総務課は、ぜひ教育委員会や公園課と連携をして、この平和を願う花壇事業、区内全校や区内の各駅前、そういったところにできる限り取り組んでいただきたいなと思いますが、お考えをお知らせください。","respondent":"古巻総務課長","answer":"様々なところでというようなお話ですけれども、一応今のところ具体的な計画はないのですが、平和の花壇だけではなくて、花の種の配布などもしておりますので、そういったことも含めまして、花によって平和を考えていただくような機会を増やしていきたいなと考えています。","voiceIndex":310,"id":"exchange-131"},{"speaker":"湯澤委員","kind":"質問・要望","question":"学校においても、それから公園、そして区道、そういったところにおいても、品川区は大変スペースが限られて少ないとは思うのですけれども、マンションとか、ビルとか、そういった屋上、こういったところの民間の力なども借りながら、知恵を出し合って、緑と笑顔あふれる平和都市品川を目指していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":312,"id":"exchange-132"},{"speaker":"大倉委員","kind":"質問・要望","question":"７８ページ、清掃費から、コロナ禍のごみ収集に関連して伺わせていただければと思います。本当に今ごみ収集、第６波で感染が拡大している中で、感染のリスクを負いながら、まちのために、ライフラインとして生活を守る取組を日々続けていただいている清掃職員の人たちには、本当に感謝を申し上げます。","respondent":"品川品川区清掃事務所長","answer":"ただひたすらお風呂に入るというような対応も取ってあります。その他、細かなところをいろいろ努力して、なるべくクラスターが起きないことを一番に気をつけながら、日々作業のほう行っているところです。","voiceIndex":314,"id":"exchange-133"},{"speaker":"大倉委員","kind":"質問","question":"その前に、先ほどの新型コロナウイルスの検査用キットの処分のところで、針のあるもののお話をされましたが、針がないものについても、例えばこの千代田区の例だと、使用後はビニール袋に入れ、４日間保管をして、４日経過したら、針がないものは燃えるものとして収集が可能ということで掲載しておりますが、そうした掲載については、どのようにお考えでしょうかということと、また、そうした。","respondent":"品川品川区清掃事務所長","answer":"それプラスごみ袋にメッセージ等も書いてあったりとか、そういったことで大変区民の皆様からありがたいお言葉を頂戴しています。先ほど、こういったものを周知活動にうまく活用できないかというところも今後検討していきたいと、このように考えております。","voiceIndex":316,"id":"exchange-134"},{"speaker":"大倉委員","kind":"質問・要望","question":"そうした手紙を出した人たちも、当然既にもう意識のある方たちだと思いますが、そういうものも活用しながら、区民の人たちが、このような活動もあって私たちもしっかり取り組んでいかなければと思っていただきたいと思います。その中で、例えばケーブルテレビ等も含めたＬ字の、あのようなところに流す等も含めて、検討していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":318,"id":"exchange-135"},{"speaker":"須貝委員","kind":"質問","question":"私は補正全般から質問します。先ほどおくの委員からもありましたが……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":320,"id":"exchange-136"},{"speaker":"須貝委員","kind":"意見","question":"今、ロシアのウクライナ侵攻に抗議する声が全世界で始まっています。世界でも、国内でも、市民らが横断幕を掲げ、抗議の意思表示をしています。そこで品川区でも、横断幕や懸垂幕を作ったり、また、チラシ配布など様々な手段を使い、区民に呼びかけるべきではありませんか。そしてロシアに、やはりきちんと品川区として、自治体として訴えるべきではありませんか。お答えください。","respondent":"古巻総務課長","answer":"なので、現在の状況につきましては憂慮すべきところが多々あるのかなとは思っておりますが、国に対するそういったいろいろな働きかけにつきましては、国が専ら取り組むべき事柄ということで捉えておりますので、品川区といたしましては、非核平和都市品川宣言の趣旨にのっとった。","voiceIndex":324,"id":"exchange-137"},{"speaker":"須貝委員","kind":"質問","question":"これ人権啓発課も品川区はあるではないですか。これいったい皆さんどう思うのですか。それから高齢者、障害者を抱える福祉部、それから健康課はどうなのですか。このようなことをしっかり今こそ子どもたちに、そして、多くの区民の方に平和ということをしっかり明確に、品川区でも表現すべきではありませんか。それとも、教育委員会もほかの部署も、全然無関心でいるのですか。","respondent":"古巻総務課長","answer":"繰り返しになりますけれども、非核平和都市品川宣言、こちらは品川区として、核兵器の廃絶と恒久平和の願いを込めて宣言をつくったものですので、品川区といたしまして、しっかりと非核平和都市の取組を続けてまいりたいというふうに考えております。","voiceIndex":326,"id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"世界でこれだけの騒ぎになって、多くの人の人権が無視されて、平和もそうですよね、まさに。教育委員会だって小さなお子さんいるのでしょう。これは絶好の機会ではないですか。そうではないのですか。それともあくまで自分たちは知らんぷりなのですか。人権問題だ、虐待だ、いじめだ、ところがこのようなときは黙ってしまうのですか。そのような姿勢なのですか。ちょっと、もし答えられたらお答えください。","respondent":"古巻総務課長","answer":"決して黙っているというわけではございません。非核平和都市品川宣言の趣旨にのっとりまして、品川区としてしっかりと平和の事業を進めてまいりたいというふうに考えております。","voiceIndex":328,"id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"どうも今燃えてきました。このような方が、多くの方が虐殺されたり、国外に一方的に、もう避難せざるを得ない、そのような状況に置かれているということは、私は区としてしっかりアピールすべきだと思うし、そのようにしなければいけないのではないですか。だけれども、品川区、大都市の中にあるこの品川区が、このようなことでいいのですか。一応それだけ言わせていただいて、次の質問に行きます。","respondent":"宮尾高齢者福祉課長","answer":"人員に関しては、ちょっと申し訳ないのですけれども、例えばコロナを受けて何か人を増やすとか、そういったことは特段、区としてもなかなか難しいところがありますので、それはコロナ前からの基準に沿って運用させていただいているです。","voiceIndex":331,"id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"現実は、現状は見ているわけですよね。それから、どうも話していておかしいなとか、それは現場にいる人なら分かりますよね。その人のことを考えたら、やはり行ってちょっと顔を見て、話をして、ではちょっと散歩しましょうよ、１０分でも２０分でも。やはりそのような工夫というものはあってしかるべきだと思うのですけれども、そのようなものはあったのですか。すみません、もう１回お答えください。","respondent":"宮尾高齢者福祉課長","answer":"何でもかんでも、例えば感染が怖いからサービスを止めるとか、そのようなことにはつながっていないというふうに認識をしています。","voiceIndex":333,"id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"ちまたでは、やはり危ないということで、カラオケも今停止されています。それを何度も私はずっと言っていたのだけれども、何かできる仕組みというものは考えられないのでしょうか。何とかこちらで支援してあげてできるようにしないと、このままいったら、もしコロナが、あと何年続くか分からないですけど、もっともっと具合の悪い方、出てきてしまうのではないですか。ちょっとご見解をお聞かせください。","respondent":"菅野高齢者地域支援課長","answer":"ただ、そうはいっても、やはり１月以降、どうしても感染者数が増えると利用控えというものもありますので、なかなかこちらとしても、いろいろ策を練って、少しでもそういった方たちが気兼ねなくできるようにということは考えているところなのですが、ご家族が心配されたりとか。","voiceIndex":335,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"ゆうゆうプラザは確かに個室ですから、あそこはちょっとまた難しいところもあるかもしれません。でも、中には今扇風機もあるし、換気はそれぞれできるはずだし、それから、様々な、いろいろな高齢者のそのような施設なども、窓も開くだろうし、あと換気扇をつければ、もう換気も十分できるはずだし、仕切り板をつけたり、今言ったマスクもつけてやってください。絞ってやればいい。私は何とか、すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":337,"id":"exchange-143"},{"speaker":"中塚委員","kind":"質問","question":"６３ページ、庁舎整備基金積立金について伺いたいと思います。その前に、先ほどのロシアによるウクライナ侵略の質疑の中で、品川区の答弁が、現在の状況は憂慮すべきだという答弁がありました。そこで、現在の状況とはどのような状況を指しているのか、憂慮すべき事態とはどのような事態を指しているのか、伺いたいと思います。","respondent":"古巻総務課長","answer":"今現在起こっております、ウクライナに対するロシアの侵攻に対して、様々な動きが世界で広がっている状況です。そういった状況につきましては、非核平和都市品川宣言の趣旨から照らすと、なかなか何というのですか、憂慮すべき状況なのかなというふうに考えているところです。","voiceIndex":339,"id":"exchange-144"},{"speaker":"中塚委員","kind":"確認","question":"確認したいのですけれども、ロシアによるウクライナへの侵攻に憂慮を示しているということでよいのか、確認させてください。","respondent":"古巻総務課長","answer":"特定のというよりは、戦争につながりかねないような状況が生じていることに対しては憂慮しているということで考えております。","voiceIndex":341,"id":"exchange-145"},{"speaker":"中塚委員","kind":"質問","question":"つながりかねないというのは、どのような状況につながりかねないことを憂慮しているのでしょうか。","respondent":"古巻総務課長","answer":"言葉はなかなか難しいと思いますけれども、報道等から推測いたしますと、なかなか、何というのでしょうか、平和的な外交的な解決というよりは、少しこう激しい、何か動きがあるということに対しては、憂慮すべきかなというふうに考えているところです。","voiceIndex":343,"id":"exchange-146"},{"speaker":"中塚委員","kind":"質問","question":"やはり態度ははっきりすべきだと思うのです。少し激しい動き、つまり戦争が今起きているのです。それに対して品川区は抗議すべきだというふうに、先ほどから指摘が繰り返されているのだと思います。最後に、この激しい動きとは、つまりは戦争を指すことだということでよろしいのでしょうか。","respondent":"古巻総務課長","answer":"何をもって戦争というふうに定義づけるかということはなかなか難しいところはあるのかなと思いますけれども、いわゆる平和的なというか、話合いによるということではないという意味では、少し強い行動なのかなというふうに考えているところです。","voiceIndex":345,"id":"exchange-147"},{"speaker":"中塚委員","kind":"質問・要望","question":"本当にこのような区政ではいけないと改めて思いました。非核平和都市品川宣言にのっとって、ロシアによるウクライナ侵略はやめなさいと、区は態度を示すべきだと強く求めて、当初の質問に入りたいと思います。３０億円もの庁舎の積立金について、今日も何回かいろいろ議論がありましたけれども、改めてどこからかき集めたものなのか、財源を伺いたいと思います。","respondent":"黒田財政課長","answer":"いわゆる一般財源、補正予算に係る全体に言えるところですが、基本的に今回は区民税の増収であったり、財調の再調整での増で、減額補正による、予定していたところができないことの一般財源というところと、全体的なところの一般財源を補正予算の編成の中で増額補正する部分。","voiceIndex":349,"id":"exchange-148"},{"speaker":"中塚委員","kind":"質問","question":"区民税が思ったより増えたり、財調も思ったより増えたり、また減額補正も含めての財源ということですけれども、このコロナ禍で区民生活が厳しいときに、品川区の財政状況は随分余裕がある。その余裕分で３０億円もの庁舎基金を組み立てているということでよろしいのでしょうか。","respondent":"黒田財政課長","answer":"これは人口増に加えまして、失業率も納税義務者の数に影響しますので、そういったところもいろいろなところを勘案して見込みより増えたですので、余裕があるというところではないというふうに認識しています。","voiceIndex":351,"id":"exchange-149"},{"speaker":"中塚委員","kind":"質問","question":"当初の見通しよりも多くなった歳入を充てているのがこの３０億円という金額だと思います。こうした財源は、コロナで苦しい生活をされている方への支援にこそ充てるべきだと思います。当初予算で見ると、３０億円ではなく５億円のみの計上の件ですが、つまりはまた令和４年度の最終補正で余裕分があるから、最終補正で３０億円に増やすという考えをもう既に見通しているのかどうか伺いたいと思います。","respondent":"黒田財政課長","answer":"庁舎につきましては整備を計画しておりまして、現時点では、基本構想で４００億円ほど整備費用を見込んでいるですので、先ほども答弁いたしましたが、一定程度起債を活用しながら、分担金があれば分担金も財源となりまして。","voiceIndex":353,"id":"exchange-150"},{"speaker":"中塚委員","kind":"質問","question":"ほかの基金を見ても、財政調整基金積立金は５６億円、公共施設整備基金積立金は４０億円ですから、合わせると補正で１２６億円も積み増します。耐震工事も終わっております。１５年使えます。第３３号議案ですが、内容は必要なコロナ対策なので賛成しますけれども、十分な検査体制や検査の実施、また補償など、抜本的に強める必要があることを指摘して賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":355,"id":"exchange-151"},{"speaker":"大沢委員","kind":"質問・要望","question":"コロナの影響でということで、マイナス補正で、自分自身が質問をひねり出すのがなかなか大変であったのですけれども、ここでコロナ禍の影響ということで、コロナ禍だからこのようなことになってしまったというような、一言そのような文言で片づけていただかなくて、どのような予算編成だったのか感想をいただきたいということと、また、この予算編成、この補正予算を編成するに当たって。","respondent":"黒田財政課長","answer":"予算編成に当たって企画部からどのようにですが、そういったところで、補正予算ですので、３月までの執行見込みをしっかり立てていただきまして、歳入、歳出ともに予算編成に当たったです。","voiceIndex":357,"id":"exchange-152"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこのところでもう１回その事業内容を実証、検証して、コロナ禍であろうが、より効果的な事業を考えていく。より効果的な事業に流れを持っていくということは大事だと思うのですけれども、そこのところ、どのようにお考えになるのか教えてください。","respondent":"黒田財政課長","answer":"コロナ禍に対応した補正予算というものは、これまで補正予算を何回も編成しておりまして、全部で９号予算ということになりますので、そういった中では、年度を通して、そういったコロナの状況に応じて、ワクチン接種の対応を取ったり、商品券の増額発行。","voiceIndex":359,"id":"exchange-153"},{"speaker":"大沢委員","kind":"質問・要望","question":"この執行手続の項で、不用額の処理について、予算執行につき生じた差額（見積差、契約落差等）は、その要因を明確に区分し、減額補正または決算上の不用額とする、このように書いてありますけれども、この減額補正の考え方、これは基本的な考え方と思いますが、この考え方に基づいて今回は手続が行われたとは思うのですけれども、そこのところの感想なり、お考えを伺いたいと思います。","respondent":"黒田財政課長","answer":"ただいまご指摘いただいたとおり、補正予算につきましては執行見込みを３月まで立てて、結局減額補正になると。ただ、その歳出につきましては、例えばこの後急な対応がありますと、執行するために予算が必要というところでは、ある程度の余裕を見る必要もある。","voiceIndex":361,"id":"exchange-154"},{"speaker":"大沢委員","kind":"質問","question":"やはりコロナ禍であるから、このマイナス補正、人と対面のものについては、先ほども課長がおっしゃったように、人と接するものに対してはマイナス補正があり、また、コロナ対応についてはプラス補正、これはもう当然の流れだと思うのですけれども、今後、先ほどお話ししたように、対面をするところで、どのようにマイナスの補正をより補正幅。","respondent":"黒田財政課長","answer":"例えば、オンラインで実施することによって事業が工夫できるものというものも事業の中であるとすれば、経費を使って対面からオンラインで対応するというようなやり方で、執行方法を工夫する中で対応できるものがあれば、各所管のほうで対応しているような状況です。","voiceIndex":363,"id":"exchange-155"},{"speaker":"大沢委員","kind":"質問","question":"相互方向も。そこのところ、デジタル型の方たちについては、オンラインはすぐに受け止められるけれども、活字型の媒体の方たちについてはなかなか取っつきにくいものがあると思うので、そこは一工夫をお願いしたいと考えていますが、そこのところをいかがお考えになりますでしょうか。","respondent":"黒田財政課長","answer":"やはり全てがオンラインで対応できるということではないと思いますので、その事業の趣旨によって、様々効果が得られるような方法を各所管のほうでも模索しながら実施しておりますので、そういった形で進めてまいりたいというふうに考えてあります。","voiceIndex":365,"id":"exchange-156"},{"speaker":"大沢委員","kind":"質問・要望","question":"次の質問に移ります。私たちが知りたいのはその後、報告を受けあるいは答弁を受けているか、報告を受け、あるいはそこから何というのですか、報告を受けているから、その後どうなったのですかということを私は知りたいのですけれども、そこのところについての考え方を聞きたい。お願いします。","respondent":"多並都市開発課長","answer":"その聞いているところについては聞いているとお話をさせていただきましたが、やはり、事業をまちづくりとしてしっかり進めていただくためには、区としてもやはりそこはよく連携しながら進めるべきということで、今後もそのように進めていきたいと思っているところです。","voiceIndex":367,"id":"exchange-157"},{"speaker":"大沢委員","kind":"質問・要望","question":"やはり何々と報告を受けています、聞いておりますというものはなかなか理解しづらい表現ですので、そこのところを一工夫して、分かりやすいような説明をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":369,"id":"exchange-158"},{"speaker":"塚本委員","kind":"質問","question":"私からは、最初に７５ページの区内私立保育園経費から、主にコロナにおける休園の考え方等について、それから、次に６１ページの情報システム運営費について伺いたいと思います。現状のこのコロナ第６波における、区の、主に私立保育園における休園状況、現状今どのような状況になっているのか教えてください。","respondent":"若生保育支援課長","answer":"区として一律に、こういったケースでは休園にしますというような指示というか、方針等はお示ししておらず、感染状況等も日々変わっているところですので、そういった状況、園のほうと、そういった陽性ですとかの情報というものが区にも日々入ってまいりますので。","voiceIndex":371,"id":"exchange-159"},{"speaker":"塚本委員","kind":"確認","question":"そういった中で、その自粛、休園しないことによって、いわゆる、この国の小学校休業等対応助成金というものが活用、利用できないというようなお声を幾つか聞いたのですけれども、実際にこれをよく見てみると、自粛を要請されて登園しなかったという場合においても利用できる制度、助成金というふうにホームページには載っていたのですが、こういったことについて、この私立保育園側からの情報提供、周知。","respondent":"若生保育支援課長","answer":"こちら国のほうから事務連絡という形で、昨年の令和３年９月３０日付で、こういった助成金のほうが国のほうで用意しておりますと、これ令和２年度に実施していて、１回終了しまして、また令和３年度、８月から１２月末までの期間でまた再開しましたということなので。","voiceIndex":373,"id":"exchange-160"},{"speaker":"塚本委員","kind":"質問","question":"このシステムの委託費の中身がどうなのだという話は、時々議論に上がってきたかと思いますけれども、公正取引委員会のほうからこういった報告書で指摘されたということで、この問題、新たな局面を迎えたのかなと思いますが、区として、この囲い込みと言われるような状況について、今どのような認識なのかお伺いします。","respondent":"宮澤情報推進課長","answer":"特定のベンダーが製品や仕組みというものを組み込むことによって、システムの変更が困難になるというような状況ですけれども、区では調達ガイドラインというものを定めておりまして、調達する際にはプロポーザル等で業者を選定すると。","voiceIndex":375,"id":"exchange-161"},{"speaker":"塚本委員","kind":"質問","question":"そういった中での、今回のこの、いわゆるガバメントクラウドというものを目指す国の標準仕様と、こういったものが実現することで、３割ほどのコスト減を目指すというようなことも示されておりますけれども、ここに、この標準化によって、こういった囲い込み等の問題、コスト高止まりといったことが防止されていくというふうにも、私としては期待をしたいところですが、区としていかがでしょうか。","respondent":"宮澤情報推進課長","answer":"そのようなところで競争原理等が働きまして、システムの調達に関するコストというものも削減できてくると見込んでいるところです。","voiceIndex":377,"id":"exchange-162"},{"speaker":"塚本委員","kind":"意見","question":"ちょっと時間がないので、あまりこれ以上はあれですけれども、今ご答弁あったとおり、この標準化によって競争が、いわゆる健全に行われるようになるというようなことは大変にいいことだと捉えておりますので、令和７年度末ということを１つのお尻にして、今進めておられるわけですが、しっかりこれを進めていっていただけるようにお願いをしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":379,"id":"exchange-163"},{"speaker":"石田（秀）委員","kind":"質問","question":"出納閉鎖後、例えば令和３年度の基金残高の予想額というのはどれぐらいになるのか、また、単年度での基金は、これで積み上げられるものは何億円程度になるのか、それと併せて、先ほど来いろいろ出ているのだけれども、もう理由は何度も言っていらっしゃるからいいのですが、例えば区民税増、財調再調整増、それから事業の中止や延期などによる縮小というふうになっているのだけれども。","respondent":"黒田財政課長","answer":"基金残高の見込みですが、予算特別委員会の資料の中で、令和３年度末の予算ベースですけれども、８２４億円ほど、今、最終補正予算の中では基金残高を見込んでおりまして、当然この後決算がありますと、執行率の関係で一定程度不用額が出てきた中で。","voiceIndex":381,"id":"exchange-164"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ですから、私は６割、７割と思って区長に聞こうと思ったけれども、いらっしゃらないから、この辺について、基金についての考え方、多分これ８２４億円だから９００億円ぐらい出てくるのだろうなと思って今聞いていましたが、その辺の感覚を教えていただきたいということと、それからもう１個、経常収支比率、これも様々出てきていて、品川区はまだまだいいほうなのだけれども。","respondent":"黒田財政課長","answer":"経常収支比率でありますが、大体８割前後というところが、近年８０％か７０％台の後半というようなところで推移しておりますので、あまり高くなりますと財政が硬直化しているというような指標になりますので、こちらのほうも、ご指摘ありました児童相談所の人員については。","voiceIndex":383,"id":"exchange-165"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これができることが、私は来年度の１年に求められているのだろうと思っていまして、ぜひそれは、例えば高齢者だったら友愛事業、これを利用の項目をすごい拡大化するとか、町会、自治会だったらこれも弾力化で、これはもう今予算もつけてもらっているのだけれども、回数を増やしていくとか、あとは、例えば団体だったら商店街、例えばそれが商品券なのかどうかは別としても、それを増やしていくとか。","respondent":"黒田財政課長","answer":"ただ、横串のところにつきましては、今年度実施計画も策定いたしまして、これからまたその実施計画の実行、長期基本計画の実現に向けて、令和４年度から執行してまいりますので、そういった中で様々連携して、先ほど申し上げたとおり。","voiceIndex":385,"id":"exchange-166"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1144#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":129957,"voices":392}},{"id":"r04-20220303-3","meetingId":"r04-c-budget","date":"2022年3月3日","dateIso":"2022-03-03","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時３３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を170件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより、予算特別委員会を開会いたします。 それでは、第５号議案、令和４年度品川区一般会計予算","agenda":"○午前１０時００分開会 ただいまより、予算特別委員会を開会いたします。 それでは、第５号議案、令和４年度品川区一般会計予算","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"おはようあります。本日もどうぞよろしくお願いいたします。９３ページ、ヤングケアラー支援事業ほか２事業、１２１ページ、医療保健政策包括補助金に関連して、地域猫対策について、この２点、お伺いします。ヤングケアラー支援事業ですが、区議会公明党は、これまで国の予算を活用してのヤングケアラー支援を要望してまいりました。今回のこの支援事業の目的をお知らせください。","respondent":"山下子ども家庭支援センター長","answer":"この事業の目的ですけれども、やはりヤングケアラーというのは、ご自身からなかなかＳＯＳを発信できないですとか、なかなかこちらからの発見が難しいといったところから、やはり全庁的な対応が必要だろうというところは考えてございまして。","voiceIndex":4,"id":"exchange-001"},{"speaker":"新妻委員","kind":"確認","question":"子ども部門の所管ということで、支援が進んでいくということを確認させていただきました。次に、事項別説明書の中に事業内容が紹介されておりました。今回、３点ということで、まず、実態把握に向けた取組み、関係機関向けの職員研修、そして庁内連絡会の設置ということで、ここに明記されておりますが、３点それぞれについてご説明をお願いいたします。","respondent":"山下子ども家庭支援センター長","answer":"このヤングケアラーの支援体制の構築に当たりましては、区職員だけでなく、今ご紹介がありました民生・児童委員でありましたり、介護の部門でいうとケアマネジャー、障害者福祉の部門でいうと相談支援専門員、また、学校や医療のソーシャルワーカーの方々など。","voiceIndex":6,"id":"exchange-002"},{"speaker":"新妻委員","kind":"質問","question":"ちょっと話はかわりまして、次に、東京都の予算に関連してお伺いしたいと思います。東京都の予算で、今回、教育庁の部門からヤングケアラー対策等の充実ということで、スクールソーシャルワーカーの配置を充実する市区町村を支援するための予算がつけられております。東京都の予算の活用というところは、検討されたのか、その点をお知らせください。","respondent":"山下子ども家庭支援センター長","answer":"この中では、ヤングケアラー支援マニュアルの作成とかといったところで、東京都が実際に主体となりましてマニュアルの作成に当たるのかなというところが見えてありますので、そういったマニュアル等の活用につきましては積極的に考えてまいりたいと存じます。","voiceIndex":8,"id":"exchange-003"},{"speaker":"新妻委員","kind":"質問","question":"地域猫についてお伺いいたします。これまで様々なボランティアの方のお声を伺って、この地域猫の件、議会の中でも質問をさせていただきました。今日は、次年度の品川区の地域猫に対して、今現在、課題がどこにあるのか、また、そのことを通して、次年度はどこに力を入れていくのか、そのことをまずお伺いいたします。","respondent":"鈴木生活衛生課長","answer":"それと、最後にもう１つ課題としましては、地域におけるモデル地区活動の内容が、まだあまり知られていないという現状がありまして、その中での活動がしにくいということも聞いておりますので、今後は、その３点の課題に対して、より啓発の充実であったり、支援の改善。","voiceIndex":10,"id":"exchange-004"},{"speaker":"新妻委員","kind":"質問","question":"周知は非常に大事だと思います。小学生にも分かりやすい、ふりがなが振られた意識啓発のチラシも置かれておりまして、少しずつ周知の拡充に取り組んでいただいていることが伺えます。続きまして、東京都との連携についてお伺いするのですが、猫に関しては、品川区だけでなく、どの地域でも課題があると考えています。お伺いいたします。","respondent":"鈴木生活衛生課長","answer":"地域猫の活動についての情報共有、情報交換ですが、東京都との間におきましては、特別区の主管課長会に東京都の課長がいらっしゃいまして、事業内容の説明であったり、協力の依頼などがありまして、その際に各区から意見や要望。","voiceIndex":12,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"今回、東京都の予算案に、都民、関係者との協働による動物との共生推進拠点の調整を実施するということが盛り込まれておりますので、このようなことも踏まえて、ぜひ品川区からも、シェルターを東京都で設置、その情報を早く伝えてほしいと思うのですが、こういうこともぜひ要望していただきたいと思いますが、いかがでしょうか。","respondent":"鈴木生活衛生課長","answer":"都の設置する猫のシェルターですが、情報が来次第、内容を精査して、その上で、よい活用方法であったり、協力体制について声を出していきたいというふうに考えております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"横山委員","kind":"質問・要望","question":"１点目に、こころの健康づくり事業についてお伺いいたします。令和元年、昨年と質問いたしましたが、ゲートキーパー養成の進捗状況を確認させてください。品川区のＳＯＳカードは、すてきな猫のデザインになっているかと思うのですけれども、こちらは引き続き、性別に関わらず、思春期の子どもたちの目につきやすく、手に取りやすいデザインをお願いしたいというふうに思っておりますが、いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"その上昇した自殺率が、昨年、令和３年には若干減りはしたものの、令和元年の状態までは下がらず、依然としてコロナ禍における自殺の問題というのは、非常に喫緊の課題であるというふうに認識しています。次に、ゲートキーパーの養成状況です。","voiceIndex":17,"id":"exchange-007"},{"speaker":"横山委員","kind":"質問・要望","question":"オンラインとゲートキーパーの組合せはすごく効果が出ているということで確認できました。ありがとうございました。こちらは要望で終わります。２点目に、子ども・子育て支援交付金についてお伺いいたします。今後、少しずつほかの自治体の動向を研究しながら、性的虐待の予防を進めていただきたいということを要望いたしますが、区のご見解をお聞かせください。","respondent":"山下子ども家庭支援センター長","answer":"今、委員からご紹介がございましたノル教授の講演につきましては、当支援センターの福祉職、心理職の職員も複数名聴講しておりますので、そういった知見を活用してまいりたいと考えておりますし、今年度、子ども家庭支援センターでは。","voiceIndex":19,"id":"exchange-008"},{"speaker":"横山委員","kind":"質問・要望","question":"まだまだほかの性的虐待以外の部分も数が多いですけれども、こちらも割と特殊な部分がありますので、少しずつ進めていただきたいというふうに思います。３点目に、医療保健政策包括補助金についてお伺いいたします。保健所と学校保健が連携して進めていただきたいのですが、小・中学校における現在の取組みの実施状況と、教育委員会のお考えについては、教育費のところでお伺いしたいと思っています。","respondent":"高山健康課長","answer":"現段階では、補助要件等について詳細は明らかになっておりませんが、今後、詳細の把握に努めまして、関係所管として、保健センター、教育部門なども含めまして、この事業の実現性について検討してまいりたいと考えております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"横山委員","kind":"質問・要望","question":"４点目に、特別区財政調整交付金についてお伺いいたします。オール東京で、本来の広域調整とは何かというところを、区民や都民の利益を中心に据えて責任を持って考えていくのは、どこの組織で誰が責任を持つのでしょうか。都区の在り方について検討を進めるには、具体的にどのようにすればよいと区はお考えでしょうか。","respondent":"佐藤企画調整課長","answer":"都区のあり方検討委員会の現状、また、今後の都区のあり方についてですが、都区のあり方検討委員会の現状は先ほどお伝えしたとおりですが、この間の児童相談所やオリンピック・パラリンピックの関係、首都直下地震など、個別の課題に関しましては。","voiceIndex":23,"id":"exchange-010"},{"speaker":"横山委員","kind":"意見","question":"様々区として取り組んでいただいていると思うのですけれども、令和４年度にできることとしては、議論を進めていくこと、また、各区が区としての力をつけていくこと、昨日の補正予算では組織内コミュニケーション促進について触れましたけれども、都と区におきましても、それぞれの階層における交流が以前と比較して少なくなっているということが、お互いの立場を捉えにくくしており。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、８７ページの生活困窮者支援費についてと、８９ページの感染症予防費について伺いたいと思います。そのような中、東京都の集中検査についての続きを伺いたいのですが、保健所としても積極的に受けていただきたいということでした。品川区のホームページでも、これを掲載していただきたいと思いますが、いかがでしょうか。さらに延期を東京都に求めていただきたいと思いますが、いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"これについては、現状、もちろん対象の時期が延長されたことは認識していますが、改めて区のホームページに都のホームページのリンクを張るなどによりまして、積極的に区民に周知を図っていきたいというふうに考えております。","voiceIndex":27,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは保育園だけではなく、学校も、それから介護の施設もありますので、陽性率もまだまだ高く、２５％を超えていたり、ＰＣＲ検査センターの陽性率は５０％にもなっているという状況ですので、ぜひ検査はどんどん積極的に進めていただきたいと思いますので、ぜひ保健所の立場から進めていただきたいと改めて要望しておきたいと思います。次に、生活困窮者の支援について伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"社会福祉協議会が実施している生活福祉資金のうち、緊急小口資金につきましては６,１４０件、１２億２,２７６万円。こちらは令和３年度２月末までの実績となります。総合支援資金につきましては、合計で１万６１５件、再貸付けを含めた金額は５３億６,３５２万円です。","voiceIndex":29,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひこれを出していただきたいのと、６月まで延長になったということも早急にホームページに掲載していただきたいと思いますが、いかがでしょうか。そういうことになっているのであれば、これをぜひ徹底していただきたいと思っていますが、いかがでしょうか。そして、「困ったときには１人で悩まずに、お気軽にご相談ください」と、これを掲げていただきたいと思うのですが、いかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"それと、暮らし・しごと応援センターが見つけづらいというのは、庁舎の中でどのような形がいいかということで、経理課と相談しながら考えてまいります。就労を条件としないというところは、そのような方法でやっていると認識しております。","voiceIndex":31,"id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"感染症対策事業について伺います。昨日の補正予算や先ほどの質疑でもありました。続けます。自殺対策交付金について伺います。生活者ネットワークは、２０２０年から感染症の影響による自死の増加について、早急な対応を求めていました。ただ、１つ要望したいのですが、自殺対策計画について自殺対策のページですぐに確認ができるよう、リンクの添付などを求めたいのですが、見解を伺います。","respondent":"鷹箸保健予防課長","answer":"自殺対策です。商店街との連携につきましては、戸越銀座商店街で、一昨年度末に、商店街の皆さんと、かなり大きな放送なども含めてやらせていただいた以外に、大井町駅駅頭でのキャンペーンなども実施しております。","voiceIndex":34,"id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもの預け先や居場所を開けなくなる、保護者が働けなくなるということが起きないための感染防止策として取り組んでほしいと要望いたします。自殺対策についても、ネットカフェ等にいる方への情報提供は難しいと思いますが、ぜひ進めていただきたいと要望いたします。先ほど教育委員会の協力もあるとのことですが、ぜひそういった教育委員会も含めた体制となっているかを改めて確認させてください。","respondent":"山下子ども家庭支援センター長","answer":"子どもたちが一番長く過ごす場所は、家庭の次に、やはり学校であるというところから、学校が気づく端緒になり得る可能性をやはり秘めているというところがありますので、教育委員会との連携につきましては。","voiceIndex":36,"id":"exchange-016"},{"speaker":"田中委員","kind":"確認","question":"確認させていただきました。では、次の質問に進みます。子会社になった事業者は、区への報告が必要だと考えますが、報告の規定があると思いますが、確認をさせてください。子会社になった事業者から利用者に対して報告がされているのか伺います。その当該園のホームページを確認したところ、本ページでの報告は私が見た限りでは見当たりませんでした。影響があったのか、確認をさせてください。","respondent":"若生保育支援課長","answer":"様々ご質問いただきましたが、保護者への説明等に関しましては、これは当然、事業者側のほうで行っているということも聞いてあります。","voiceIndex":38,"id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"区のホームページでも報告すべきと考えますが、今後の再発防止策を伺います。議事録によると、２０２０年７月に東京都が特別立入検査を行い状況を確認した結果、判明したとのことです。区は、２０１８年１２月１１日の前例にならい、その他での報告を正副委員長に求めたとのことです。保護者への報告状況について伺うとともに、区のホームページ等でも情報提供すべきと考えますが、見解を伺います。","respondent":"若生保育支援課長","answer":"認証保育所の補助金返還に関しまして、ご報告に時間がかかった理由としましては、まず、一昨年の７月に都が実地検査を行いまして不正の実態が分かったところで、その後、事業者のほうで都や区へ報告するまでに時間を要したことと、その後。","voiceIndex":40,"id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"子会社化した事業者の事例についてです。生活者ネットワークが懸念しているのは、利用者や保育者への影響です。そして、不正受給についても、報告の在り方について方法を改めてほしいと思います。次に行きます。現在、子どもシェルターに関して、区で設置も含めた議論などはあるのでしょうか。都内には、民間が開設している子どもシェルターがありますが、連携などがあるのかも併せて伺いたいと思います。","respondent":"加島児童相談所移管担当課長","answer":"今後は、シェルターと弁護士の連携に向けて、子どもの安全権利擁護の観点から、選択肢の１つとして、先ほど申し上げたとおり、有用なものと考えておりますので、区児童相談所の開設に向けまして、他自治体の取組みを参考に。","voiceIndex":42,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"前向きなご答弁をいただけて、本当によかったと思います。ぜひそのまま進めていただきたいと思います。体罰防止のためにも、ぜひ暴力は絶対に駄目だというポスターを、今も都のハンドブックだったり、体罰防止のポスターを設置していると思うのですけれども、その拡充など、暴力に対する認識が広がる工夫を求めますが、見解を伺います。","respondent":"加島児童相談所移管担当課長","answer":"今でも子ども家庭支援センターなどにおいて家庭訪問の際などに活用されておりますので、児童相談所でもその手法を引き継いでまいりたいと考えております。","voiceIndex":44,"id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、予算書、９１ページ、新型コロナウイルスワクチン接種負担金から、昨日に引き続き、子どもの新型コロナウイルスワクチン接種事業および新型コロナウイルスワクチン３回目追加接種事業についてお伺いいたします。小児の新型コロナウイルスワクチンの実施について引き続きお伺いいたします。ファイザー社製コロナワクチンコミナティ筋注、５歳から１１歳用は筋肉注射で行います。お尋ねいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"小児接種に関してです。打合せは、両医師会、それから薬剤師会とはもちろんのこと、昭和大学の小児担当とも実施をしておりまして、先日は、集団接種２会場、荏原保健センターと品川保健センターの会場の下見にもご同行いただきました。","voiceIndex":47,"id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"質問","question":"その上、子どもは注射をするときに嫌がったり暴れたりする事態が日常茶飯事です。かかりつけ医で接種した場合は、このような症状が出現したときに、ある程度かかりつけ医で対応することが可能ですが、夜間に急に症状が出たような場合や、集団接種後の副反応発現時には、誰が、どのように、どこで対処するのでしょうか。区の対策をお知らせください。ご答弁をお願いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"その他、集団接種会場など、かかりつけ医以外での接種で副反応が出た場合、相談、それから対応してもらえるよう、昭和大学病院の担当医の方と現在調整を進めているところです。","voiceIndex":49,"id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"コロナワクチンの３回目の追加接種、ブースターショットについてお伺いいたします。昨日もコロナワクチン３回目追加接種について活発な質疑が行われましたが、３回目接種の立ち上がりはやや鈍いようです。現に練馬区では、１２歳から１７歳の区民に、接種票を誤ってと言っていいのかどうか分からないですが、誤配付するという事例まで起きています。この年齢層の３回目の接種は今後どうなるでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、渡辺委員長","answer":"大変心苦しいですが、現時点で、１２歳から１７歳の方の追加接種は、仮に希望があったとしても接種をすることはできませんが、今後対象になった際、体制は構築してまいりたいと考えております。保健整備担当部長はご退席いただいて結構です。第２委員会室の品川区保健所および健康課の関係理事者の方々もご退席ください。ありがとうございました。進めます。次に、湯澤委員。","voiceIndex":51,"id":"exchange-023"},{"speaker":"湯澤委員","kind":"質問","question":"私は、９３ページ、ヤングケアラー支援事業についてお伺いいたします。新規でありますので、まず事業概要からお伺いしたいと思います。支援体制の強化を目的とした実態調査とありますけれども、区はこれまでどのような支援体制を行ってきたのか。これからどういったことを強化していくのかをお知らせください。","respondent":"山下子ども家庭支援センター長","answer":"実際に養育が困難であるということであれば、子ども家庭支援センターのほうにおつなぎいただきましたり、そういった形で支援に臨んできたところです。今回、委員ご指摘のとおり、国の予算でヤングケアラーについての取組みを進めていく方針が示されております。","voiceIndex":54,"id":"exchange-024"},{"speaker":"湯澤委員","kind":"意見","question":"ヤングケアラーの支援で最も重要とされているのは、やはり周囲の気づきであると言われておりますが、気づいてあげることが困難であることから、今回の実態調査も、そちらが大きな課題になると考えています。それから、本人からの相談が多く寄せられていたのはどこなのか。ＳＮＳや電話等もあるかと思いますので、そちらを含めて、以上３点、お知らせいただければと思います。","respondent":"山下子ども家庭支援センター長","answer":"時期については、少し不透明な部分もありますけれども、まずは区職員が、ヤングケアラーがどういった方なのか、どういったところにそういった方がいるのかというところを認識しまして対応に努めてまいりたいと考えています。","voiceIndex":56,"id":"exchange-025"},{"speaker":"湯澤委員","kind":"意見","question":"これが全てヤングケアラーの人数であるとは言い切れませんけれども、少なくともそれくらいの方が家族の世話をしている可能性があることを視野に、今後の調査を行っていくべきと考えます。国の方針である３年間の集中取組期間の中で、中高生の５割以上がヤングケアラーについて知ることを掲げておりますが、この５割以上という目標値について、区はどのように捉えているのか、お知らせ願います。","respondent":"山下子ども家庭支援センター長","answer":"紙ベース以外のほかの方策につきましても、種々検討を進めてまいりたいと考えています。","voiceIndex":58,"id":"exchange-026"},{"speaker":"湯澤委員","kind":"質問・要望","question":"今、ポスターとか、様々周知の方法がありましたけれども、今、様々な俳優などを使った動画などもありますので、ぜひそういったものも活用していただきたいと思います。ヤングケアラーが世話をする家族に対して、区はどのような接し方や取組みを行っていくのか、家族が気づかないうちに自分が世話をさせてしまっているというケースもあると思いますので、これまでの取組みもあれば、併せてお知らせください。","respondent":"山下子ども家庭支援センター長","answer":"そういったところから、令和４年度、関係職員向けの研修ということで、まずは、実際にヤングケアラーに関わる可能性の高い職種の方々を含めまして研修を実施し、ヤングケアラーについて浸透させていきたいと考えています。","voiceIndex":60,"id":"exchange-027"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ぜひスクールカウンセラーとか、そういった学校現場の方にも啓発していただいて、そういったケアラーとなるべき人をしっかりとサポートできるような体制をつくっていただきたいと思います。ヤングケアラーを孤立させないために、気づくことは本当に大切なことですし、また、その家族に対しての支援も併せて取り組んでいただきたいと考えています。","respondent":"山下子ども家庭支援センター長","answer":"国のほうからは、予算のメニュー等で、オンラインのものでありましたり、ピアサポートでしたりといったものが出ておりますけれども、実際この品川区でどういった支援策が必要になってくるのか、必要と考えられるのかというところは、実態調査、把握に臨みまして。","voiceIndex":62,"id":"exchange-028"},{"speaker":"湯澤委員","kind":"質問・要望","question":"これから実態調査を進めていただくわけですから、しっかりとその辺もお願いしたいと思います。今この瞬間も気づいてあげるべき子どもたちがいるかと思いますので、スピード感も重要であります。ぜひ周知目標は高く掲げていただき、結果の伴う支援体制の構築を要望いたしまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-029"},{"speaker":"くにば委員","kind":"質問","question":"本日は、１４３ページ、客引き行為等防止過料、１５３ページ、放置自転車等保管料についてお伺いいたします。は放置自転車についてです。区内についてお伺いいたします。その取りに来なかった自転車を、区ではどういうふうにしているのか、区内での放置自転車再生リサイクルの仕組みについてお伺いいたします。","respondent":"川口交通安全担当課長","answer":"そのうち処分をして売却をしたものに関しては１,１７５台、また、リサイクルをしたものに関しましては１２７台となっております。現在の放置自転車の台数ですけれども、こちらにつきましては……。後ほどお答えします。","voiceIndex":66,"id":"exchange-030"},{"speaker":"くにば委員","kind":"質問","question":"併せて、放置自転車再生リサイクルの仕組みについてもお伺いしたので、答弁をお願いします。","respondent":"川口交通安全担当課長","answer":"失礼いたしました。リサイクル関係の内訳につきましては、社会福祉法人のふれあい作業所に８９台、また、自転車商の組合に３８台をリサイクルとして回しています。","voiceIndex":69,"id":"exchange-031"},{"speaker":"くにば委員","kind":"意見","question":"１点気になったのですけれども、平成２９年、以前の委員会での答弁で、３,７０７台中、リサイクルは４００台、区内で再生に回したとの答弁でした。このうち、今は、１２７台のみの実績ということですけれども、これは大分減少しているように感じるのですが、なぜこれだけ減少したのかという部分が１点。ふれあい作業所に８９台、こちらのほうに払下げというか提供したとのことです。","respondent":"川口交通安全担当課長","answer":"ふれあい作業所につきましては、全ての台数のうち約二、三台については部品取りとして活用して再生を行っているというふうに承知しております。","voiceIndex":71,"id":"exchange-032"},{"speaker":"くにば委員","kind":"質問","question":"ふれあい作業所のほう、部品取りをしたものを除いては、提供したもの全ての販売を完了したと。要するに、譲り渡したものを必ず販売しないで、例えば、関係者の方が、報告をしなければ、これに関しては知りあいに譲ってしまおうとか、必ず販売の報告書を提出しなければ、身内に譲り渡すことができてしまうと思うのですけれども、今おっしゃった覚書の中で、そこに関して報告をどのようにするのか伺います。","respondent":"川口交通安全担当課長","answer":"そちらに関しましては、現在、自転車商のリサイクルの立会いを八潮北保管所のほうで行っているのですけれども、リサイクルに持っていくに当たりましては、一定の、要するに、処分というか、再生して販売するというような形のものを対応していますので、ほぼ、お渡しするときには。","voiceIndex":73,"id":"exchange-033"},{"speaker":"くにば委員","kind":"質問・要望","question":"何度か答弁と行ったり来たりしているので、私が今、答弁を伺った限りの認識では、あくまで社会福祉協議会に提供した自転車に関して、きちんと販売をしたかどうかの報告書の提出は求めていないというふうに認識いたしました。","respondent":"川口交通安全担当課長","answer":"リボンが閉鎖になることに伴いまして、中小企業センターでの販売回数を増やしていこうというふうに検討しているということで聞いております。","voiceIndex":77,"id":"exchange-034"},{"speaker":"くにば委員","kind":"質問","question":"今お伺いした限りでは、リサイクルは最終的にふれあい作業所を含めて１２７台、年間でリサイクルができたと。先ほど、私のほうで申し上げたシルバー人材センターの活用についてです。そのようなシルバー人材センターへの無償提供と、品川区のシルバー人材センターの活用について、見解をお伺いします。","respondent":"川口交通安全担当課長","answer":"シルバー人材センターの活用ということですけれども、そのような形の要望等があれば、その際は検討していきたいというふうに考えております。","voiceIndex":79,"id":"exchange-035"},{"speaker":"くにば委員","kind":"質問・要望","question":"本年、予算計上されているのが５万円、１件相当で、これに関してですけれども、平成２７年に品川区で「品川区公共の場所における客引き行為等の防止に関する条例」が制定されて以降、現在までに過料を科した件数や推移、これらに関しては、基本的に区内では、指導、警告、勧告、それらの段階を経て、ようやく過料を科すことができると理解しておりますけれども。","respondent":"森田生活安全担当課長","answer":"指導に応じず、警告にいき、また、警告から勧告、公表になる、こういった状況ですが、現在までの件数はございません。","voiceIndex":81,"id":"exchange-036"},{"speaker":"くにば委員","kind":"質問","question":"ということは、基本的に、これは条例を制定したけれども、条例を制定した段階で相当の抑止効果になって、その後、この特定地区を含めて全くもって客引き等はいなくなった、現在、被害等は全くない、苦情もない状況という認識でよろしいでしょうか。","respondent":"森田生活安全担当課長","answer":"ですが、警察ではまだ取締りを継続しておりますし、目を光らせておりますので、その点については、全てがなくなっているというわけではございません。取締りも警察のほうで継続してやっておるところです。","voiceIndex":83,"id":"exchange-037"},{"speaker":"くにば委員","kind":"質問・要望","question":"それが現実です。さらに、きゅりあんの裏口のほうに行く暗い道のほうでも、常に五、六人、客引きの方々がいらっしゃったり、外国人女性の方に「マッサージ、どうですか」と声をかけられたりすることもあります。それらのいわゆる特定対象地区でないところに関しても、やはりパトロールが必要であったり、警戒、今後もしていただきたいというふうに、時間がないので、これは要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-038"},{"speaker":"木村委員","kind":"確認","question":"私は、議会費からの質問をいたします。地方都市行政視察経費からですけれども、令和３年度の予算は５４２万円、来年度の予算も、令和３年度と同じく５４２万円の予算が組まれていました。しかし、せっかく組まれた予算、本区にはないところを目や耳で確認し、よいところは参考にする機会を約２年間ほど失ったことになりました。この事態に対してのご見解をお聞かせください。","respondent":"工藤区議会事務局長","answer":"地方都市行政視察経費の件です。２年間、行政視察は中止になってきました。令和２年度、令和３年度です。やはり新型コロナウイルスの感染拡大、そして蔓延の状況、こういった部分を鑑みて、議会として、やむなく中止の判断をしたです。","voiceIndex":87,"id":"exchange-039"},{"speaker":"木村委員","kind":"意見","question":"使い切ることが目標ではありませんけれども、有効な視察、本区にとって参考になる視察が必要だと思いますし、その結果を形に変えることが目標ですけれども、コロナの関係で、過去２年間ほど泊まり込みでの行政視察は見送られてきましたが、令和４年度の視察も、現在の状況からでは大変厳しい状況ではないかと思いますけれども、関係部署の皆さんのお考えをできればお聞かせいただければと思います。","respondent":"工藤区議会事務局長","answer":"現在、新型コロナウイルスの状況は予断を許しませんが、今後、新型コロナウイルスの感染状況を見極めながら、議会の中で視察の可能性を検討しまして、可能な状態だという判断がなされた場合には、速やかに手続きができるように。","voiceIndex":89,"id":"exchange-040"},{"speaker":"木村委員","kind":"意見","question":"関係部署の皆さんのお考えをまたお聞かせいただければと思いますし、今回のこのコロナ騒動、各地方自治体においても独自の封じ込め対策で大変苦労をしながら調査研究が行われ、また、これからも行われることと思いますけれども、今回のこのコロナ騒動が落ち着くことを待っていると、まだまだ時間がかかりそうですけれども、このことに対して、行政の皆さんはどのように読んでいるのか。","respondent":"工藤区議会事務局長","answer":"そういった意味では、先ほども申し上げましたように、コロナの状況等を見極めながら、また議会の中でその対応を検討していくです。","voiceIndex":91,"id":"exchange-041"},{"speaker":"木村委員","kind":"質問","question":"議会広報費からの質問であります。１６３ページ、区議会だより発行６回、約２,９８４万円とありますけれども、年間６回発行し、住民世帯約２２万６,８００世帯、人口は約４０万３,７００人に対して行っている事業でありますけれども、お聞きいたしますが、年６回発行し、希望者には家庭に配布する。通常はスタンドに設置しているのでしょうか。それとも違うシステムになるのでしょうか。","respondent":"工藤区議会事務局長","answer":"１回、新年号というのがございまして、こちらにつきましては、シルバー人材センターの対応がとれないということで、紙面、新聞の折り込みと、もう１つ加えまして、駅のスタンド、区内に３８か所あります。","voiceIndex":93,"id":"exchange-042"},{"speaker":"木村委員","kind":"質問・要望","question":"家庭に配布ということでありますけれども、家庭数、約２２万６,８００世帯の発行部数、プラス、スタンドに置くということでありますけれども、どれぐらいの部数をスタンドに置くのでしょうか。そして、１人でも多くの区民の皆さんに、現在の品川区の状況を知っていただきたいとの思いで発行をしていることと思いますけれども、全家庭に配布するのであれば、一定の部数をなぜスタンドに置く必要があるのか。","respondent":"工藤区議会事務局長","answer":"スタンド配布につきましては、新年号のみですが、やはり様々な方に見ていただきたいです。駅を利用されている方、そういったところで、なるべく区議会だより、目に触れていただきたいという考えで、スタンド配布も新年号に関しては行っているです。","voiceIndex":95,"id":"exchange-043"},{"speaker":"木村委員","kind":"質問","question":"すみません、そうですか、そこのところを理解しておりませんでした。６回中５回は自宅に配布をする、そして、そのうちの６回目だけが、そのようなところでスタンドに置くということでよろしいでしょうか。もう一度、そこだけお答えください。","respondent":"工藤区議会事務局長","answer":"新年号以外の５回分につきましては、ご自宅のほうに確実にお届けしているということで、スタンド配布は現在してございません。","voiceIndex":97,"id":"exchange-044"},{"speaker":"松本委員","kind":"質問","question":"令和４年度に、これは令和５年度に向けてだと思うのですけれども、この割合をもう１回協議するというような話があるのですが、それまでの間は、品川区の話というよりも、他区の話になるかとは思うのですけれども、どんどん需要額自体が増えるのではないかというふうに思うのですが、割合で決められてしまって、キャップというか、頭が決まってしまうと、特別区の支出がどんどん。","respondent":"黒田財政課長","answer":"これはもともと地方分権の中で、都と区の役割を明確化するという大都市事務の整理の中でそういうふうに一旦決まったものでございまして、今般の児童相談所の財源につきましては、東京都の主張としては。","voiceIndex":103,"id":"exchange-045"},{"speaker":"松本委員","kind":"質問","question":"この０.１％の部分ですけれども、令和２年度ですよね、協議結果を見ると、先行の３区の部分に対応するような形になっているかと思っていて、そうすると、令和３年度に開設している港区とか、令和４年度、また他区も複数開設予定ですけれども、これについては、もう全く配慮がされていないというか、基準財政需要額に入ってもいないということなのでしょうか。お願いします。","respondent":"黒田財政課長","answer":"現在、児童相談所の準備をしている区につきましては、５５.１％の中で、設置区の経費については、対応補正という補正の中で、かかる経費を財調の全体の算定の中で見ているということでありますので、その他、足りている、足りていないというところは。","voiceIndex":105,"id":"exchange-046"},{"speaker":"松本委員","kind":"確認","question":"一応確認ですけれども、０.１％の部分は、先行３区の部分だけかなと思っていたのですけれども、残りの設置されている港区とか、来年度、令和４年度に設置される区の分も、財政需要額には入るけれども、別に割合は変わらない。先行３区以外のところも需要額に入れているのかどうかというところの確認をお願いします。","respondent":"黒田財政課長","answer":"児童相談所に係る経費でありますので、５５.１％の中で、特別区の需要を算定するという中で、需要に算定されておりますが、補正という形ですので、設置していく区が増えてくれば、そこの部分の需要が積み上がってきますから、当然足りないというのが特別区側の主張です。","voiceIndex":107,"id":"exchange-047"},{"speaker":"松本委員","kind":"質問","question":"このふるさと納税については、芹澤委員が、従前からすごくやられていて、追加でやるのもなかなかお恥ずかしいところですけれども、やっぱりどういうふうに増やしていくのかというのは大事だと思っています。その中で、この寄附金ですけれども、区内と区外、どの程度の割合で寄附があったのか。こういうことが把握されていないようであれば、把握したほうがいいと思いますが、ご見解を伺います。","respondent":"伊東子育て応援課長","answer":"様々な媒体を使ってやっておるところですけれども、まだ行き渡らない部分もあろうかと思いますので、これから研究して、広く周知していくことに努めていきたいというふうに考えております。","voiceIndex":109,"id":"exchange-048"},{"speaker":"松本委員","kind":"確認","question":"ちょっと答弁があれかなというふうに思うのですけれども、アンケート、どこで知ったのかというアンケートがなされているかの答弁がなかったので確認したいのと、ツイッターとか、公式ＬＩＮＥのほうでの告知がされていないように思いますので、こちらもやっていただければと思いますが、いかがでしょうか。","respondent":"伊東子育て応援課長","answer":"アンケートにつきましては、その都度、配送した方からもいただいておりますし、あとは寄附者からもいただいているというところで、それを分析して、次回の配送に生かすということですとか、寄附者に関しては、また次回も継続していただきたいという思いでの活用をしています。","voiceIndex":111,"id":"exchange-049"},{"speaker":"つる委員","kind":"質問・要望","question":"質問項目は、５０ページの特別区民税、それから、関連して９３ページの子ども・子育て支援交付金、１０３ページの就学援助費等について伺っていきたいと思います。令和３年から令和４年の落差は、令和３年を低く見立て過ぎたということがあって大きな差があるというのは伺っているところであるわけですけれども、人口の増減によって様々な影響が出てくるのが特別区民税だと考えています。","respondent":"佐藤計画担当課長","answer":"こちらにつきましては、今年度策定しております総合実施計画の策定に当たりまして、令和２年の中ほどから人口が減少傾向にあるということを受けまして、改めて区民の居住意向についてお尋ねしたというものです。","voiceIndex":114,"id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"だけれども、毎年毎年ですが、小一の壁の１つとして、やはり夏の学童の問題が出てくる。前も本会議場で質問しましたけれども、別に区にお金を出してくださいということではなくて、その仕組みを活用してほしいということ。これは当然、数字上に出てきているわけではないのですが、今後の大きい部分としてはある。これは公費の部分も含めて、１食当たり幾らになるのか教えてください。","respondent":"勝亦学務課長","answer":"こちらを児童・生徒数、それから１食当たりの食数で割り返しますと、１食当たり大体３９０円から４００円程度になると考えています。","voiceIndex":116,"id":"exchange-051"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう意味では、できる家庭はお弁当をしっかり作っていただいて、できない家庭には、そういうものを活用できる、そういうことすら活用できない家庭もあるかもしれないけれども、そういう考え方でぜひ考えていただきたいなと思いますので、すまいるスクールにおけるお弁当マッチングサービスの活用、これは今日、歳入なので、今日はあえて答弁は求めないで要望だけで終わろうかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-052"},{"speaker":"松澤委員","kind":"質問","question":"私からは、５２ページの特別区たばこ税、関連しまして、１４３ページの歩行喫煙防止過料、そして７９ページの獣医衛生手数料についてお聞きいたします。は獣医衛生手数料の中の狂犬病予防注射済票交付について質問いたします。生後９１日以上の犬は、一生に一度の登録、そして年１回の狂犬病予防注射が義務づけられております。この義務を怠ると罰金があるのか教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-053"},{"speaker":"松澤委員","kind":"質問・要望","question":"変えます。たばこ税の質問です。大阪そして中央区でも意識調査を行って、喫煙所の設置、また、アンケートをとりまして、どちらも８５％以上が設置の要望、そして８０％近くがよい取組みだというお答えがあります。品川区でも、たばこ税、これは一般財源に充てられているとのお話でありましたが、副流煙の出ない喫煙所の設置を要望しまして、これが実現したことは大変うれしく思っております。お願いします。","respondent":"森田生活安全担当課長","answer":"パトロールについては、車での広報をしながらのパトロールであるとか、また、２人ないしは３人で、チョッキまたは旗竿などを掲げながらの実施、または、裏通り、または苦情があった場所なども含めまして、いろいろな場所のパトロールをしています。","voiceIndex":122,"id":"exchange-054"},{"speaker":"松澤委員","kind":"質問","question":"これは路上喫煙の禁止であったり、地域美化推進地区ということになると思います。この路上喫煙禁止地区に、まずコンテナ型喫煙所の設置が始まっていくのかなと思っていますが、そのお考えをまずお聞きしたいのと、民間の喫煙所助成、これもたしか去年辺り始まりましたが、これについても同様の考えなのか、また、始まったばかりですが、現状はどう進んでいるのか教えてください。","respondent":"森田生活安全担当課長","answer":"なかなか現実、自分のところに喫煙所を設けて一般の方々に開放するというのは、ちょっとハードルがあるようなことでは聞いておりますが、中には前向きに検討していただいているところもありますので、引き続き、これは求めながら、現状を進めてまいりたいと考えています。","voiceIndex":124,"id":"exchange-055"},{"speaker":"松澤委員","kind":"質問","question":"さっきのお話だと、路上喫煙禁止地区、またコンテナの２か所という、直していく場所というのは、なかなか困難なのかなとは思っております。そうすると、路上喫煙禁止地区の広がりというものが見えれば、そういう喫煙所の検討というのもだんだんされていくのではないでしょうか。こういった路上喫煙禁止地区の見直し、そしてまた拡充のお考えがありましたら教えてください。","respondent":"森田生活安全担当課長","answer":"現在のところ、そういった指定地区でのみの過料の徴収となっておりますが、今後も駅前の状況であるとか、委員がおっしゃいました地区の状況であるとか、そういったものも加味しまして、また、品川区全体のことも考えながら。","voiceIndex":126,"id":"exchange-056"},{"speaker":"松澤委員","kind":"確認","question":"千代田区では、建築確認が不要な喫煙トレーラーがあったり、ＪＴ、そういった企業との連携を考える自治体も出てきております。ですが、こうやって喫煙所を賛成だとか反対だとか、そういった考え方を持つのではなくて、これからの品川区、このまちをどうしていくべきかを考えることがとても重要かなと考えています。この喫煙の課題から見えるまちづくりについて、課長のお考えを教えてください。","respondent":"森田生活安全担当課長","answer":"喫煙所が設置されることで、受動喫煙、またはポイ捨てなども減るであろうということは考えのうちに入ってありますが、今後もそういった３つの取組みをしながら、喫煙する人も、しない人も、より快適にできるようなまちづくりができたらと考えています。","voiceIndex":128,"id":"exchange-057"},{"speaker":"松澤委員","kind":"質問・要望","question":"課長のおっしゃるとおり、まちづくりというものは、区内の他者を思いやる、そういった心を育てる活動というのですか、思いやりを育む活動がまちづくりだと私も思います。この２つの条例は、同じ喫煙を示していますけれども、守るという考え方が全く違う。さらに住みよいまちづくりを目指しまして、コンテナ型喫煙所の拡充を要望しまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"９１ページと１０３ページの学校改築推進経費および校舎等整備、９９ページ、社会資本整備総合交付金について伺います。学校改築推進経費に関連して、三木小学校の建て替えについて伺います。三木小学校は、来年度、開校１００周年を迎えます。三木小の建て替えを要望する声について、区教委はどのように把握しているのか伺います。以上、３点伺います。","respondent":"有馬庶務課長","answer":"それから３番目の建設についての課題ということですが、確かに三木小学校の周辺道路は狭いので、実際に工事をやろうとすれば、かなり大きいものを入れるのに苦労するですとか、そういったことは課題として困難性があるだろうというふうには考えておりますが、実例として。","voiceIndex":132,"id":"exchange-059"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほど、地域の方の声も紹介しましたけれども、実際の老朽度合いですとか、あるいは地域のお声が、やはりかなり思い入れが強い学校ですので、ぜひ、もっと直に聞いていただきたいというふうに思います。区教委にも伺いたいのですが、現在、区教委は、将来的な三木小の建て替えについて、再開発手法で検討しているということはあるのでしょうか、伺います。","respondent":"有馬庶務課長","answer":"冒頭にもお答えしましたけれども、現在、三木小学校の改築の計画の予定はございません。","voiceIndex":134,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、区教委は、これまでも学校改築を進めてきたと思うのですが、その中で、当事者、関係者の声を反映する仕組みをどのように担保してきたのでしょうか、伺います。併せて、三木小についても、ＯＢ会や、児童、学校、地域の方が加わった改築の計画を検討する枠組みを、来年度、今年ですけれども、迎える１００周年に向けて、私はつくっていただきたいと思いますけれども、いかがでしょうか。","respondent":"有馬庶務課長","answer":"その懇談会のメンバーとして、町会長や同窓会の会長、ＰＴＡ会長、地元の商店街の方、会長とか、そういった方に入ってもらって、まずそこで説明会なり、考え方を聞き、そういう場を設けて進めていくということで進めているものです。","voiceIndex":136,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問・要望","question":"社会資本整備総合交付金の開発補助金について伺いたいと思います。私、代表質問でも触れましたが、２３区調査を行いまして、これを改めて紹介します。質問しますけれども、区が２３区でも突出して超高層開発に税金を投入して推進している事実について、区はどのように受け止めているでしょうか、聞かせてください。税金の使い方として正しいと思っているのでしょうか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"事業を実施するに当たりましては、品川区の最大の課題でもあります木造密集地域の解消であったり、また、にぎわいの創出であったり、その地域地域で課題がある中、地域の方と一緒に考えながら、それを実現する手法として、これまでの事業を一緒に考えながら進めてきたところです。","voiceIndex":138,"id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"成果だと２回言っていますけれども、昔から、昭和の時代から取り組んできたと。私、代表質問で、莫大な税金を投入する事業なのに、都市計画審議会にも、議会にも、補助金も含めた資金計画を明らかにせず決定する、都市計画決定するというのは不当なのではないかと指摘し、改善を求めました。これは、補助金の額を公開しないというのは当然だという認識ですか。改めて伺いたいと思います。","respondent":"多並都市開発課長","answer":"特に地区計画であったり、再開発等促進区を定める地区計画といいますか、そこの地区の中で整備するべき公共施設の位置であったり内容、また、それに合わせた規制をかけながら、壁面線といいまして、空地をどこまで求めなければいけないかということを定めながら。","voiceIndex":140,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"その段階的にやっていくというのは、要するに、決定前に明らかにしてしまったら、まずいと。自分たちが明らかにしたくない数字を隠すための段階ですよね。莫大な区民の税金が投入されています。仮に、税金投入そのものの是非を置いておいたとしても、こういう対応は、区民の理解を到底得られません。そして、明らかに最低限の説明責任すら果たしていないと思うのですけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"それを行うべき実施段階になりまして事業という形で、その実施主体が、資金計画、事業計画を示しながら、それを認可して進めていくということで、そういう内容ですので、そういうご理解をいただく必要があるかと思います。","voiceIndex":142,"id":"exchange-064"},{"speaker":"渡部委員","kind":"質問","question":"都の補助金について、減のものを少しお伺いしたいと思っていて、１１０ページの総務費補助金に関しては、オリンピック・パラリンピックが終わったので、その辺の事業がなくなって減るのは分かるのだけれども、防犯設備整備補助金の中で、昨年まであった、額にしたらそんなに大きい額ではない、３００万円ぐらいだったけれども、生活安全活動費が今回の予算書から消えていて。","respondent":"森田生活安全担当課長","answer":"それまでには設置が実質間に合いませんでしたので、補助については、ないという形になります。それと、今後、要望等々があるのかですが、これについては、折に触れて、そういった機会があればお願いしてまいりたいとは思っております。","voiceIndex":145,"id":"exchange-065"},{"speaker":"渡部委員","kind":"質問・要望","question":"分かりました。だって、それは地域の方々が地域の中でそういうものをつくろうとして、やろうという意識の中でやってくれるわけだから、こんなにありがたい話はなかったのだけれども、残念ながらお金がなくなってできなくなってしまったというところで、今、事あるごとにといいましょうか、何か機会があるときにとおっしゃっていただいたので、何とか東京都のほうに復活の要望はしていただきたいと。","respondent":"遠藤商業・ものづくり課長","answer":"産業経済費補助金です。こちら、減少になったものは、今年度、西大井創業支援センターの工事などがありまして、そちらで多くいただいていたところがありますが、一定、工事等が終わりましたので減額になったです。","voiceIndex":147,"id":"exchange-066"},{"speaker":"渡部委員","kind":"確認","question":"すみません、ちょっと数字だけの追いかけで申し訳なかったのですが、何かこの大きな減額があって、要は、コロナで何かおかしくなってしまって大きな減額というのでは、また嫌だなと思ったので、確認だけさせていただきました。りんかい線のことを、私、何回かいろいろ伺っている中で、また今日もお伺いしたいと思います。分かる範囲でお聞かせいただけますでしょうか。","respondent":"鈴木都市計画課長","answer":"昨年の８月には、評価書案についての説明会も開催されているというところで、年明けには、この環境アセスメントの手続きを終え、来年度、工事を着工していきたいというような形で、羽田空港アクセス新線のほうは聞いているところです。","voiceIndex":149,"id":"exchange-067"},{"speaker":"渡部委員","kind":"質問","question":"そのとおりだと思います。例えば、本当に駅がどこかにできれば、人工地盤だって、今は何だってできる時代になっているわけですから、そこにすごい、人が住むとかではなくても、いろいろなことが仕掛けられるわけです。そういう夢のあることを、これから時間をかけて目がけて、そろそろやっていってほしいなと思うのですけれども、課長、考えがあれば教えてください。","respondent":"鈴木都市計画課長","answer":"やはり、今、３ルートのうち東京駅に向かう１ルートが示されて進められているわけですが、このルートでいくと、やはり一番設置が可能なところは、これはＪＲも申しておりますが、貨物ターミナルの辺り、今、ＪＲの貨物が盛んに土地利用、使われているところが地上でもありますし。","voiceIndex":151,"id":"exchange-068"},{"speaker":"渡部委員","kind":"質問・要望","question":"各種お打合せといいましょうか、話合いはできているのだなというのを確認させていただきました。何せ今、これから２０２９年という旗が立っています。ということは、もう今から７年後にはできているという前提で考えていくと、意外と時間はないですね。新しいまちづくりに向かって頑張っていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-069"},{"speaker":"こんの委員","kind":"確認","question":"私からは、９９ページ、社会資本整備総合交付金、１１５ページ、高齢社会対策包括補助金、１３３ページ、教育支援体制整備事業費補助金からお伺いしたいと思います。基本的なところから確認しますが、そもそもこの事業は、どのような経緯で、どのようなねらいと意義を持って実施されているのかお聞かせください。","respondent":"竹田住宅課長","answer":"簡単に内訳をご説明しますと、今年度ですが、環境に配慮した住宅改修が２５２件、バリアフリーに関する住宅改修が２５件、その他工事が４件、同様に令和２年度ですが、環境関係が２６１件、バリアフリー関係が４１件、それから、その他工事が１０件です。","voiceIndex":155,"id":"exchange-070"},{"speaker":"こんの委員","kind":"質問・要望","question":"この事業のねらいと意義について確認させていただきました。成果についても状況を確認いたしました。私が想像したとおりといえるのでしょうか、一定以上のニーズがある事業だなというところを確認させていただきました。１２月２４日以降も申請はあったと思いますけれども、きっとお断りする事態になったであろうと想像するところです。具体的に残念な事例を１つ紹介すると、コロナ禍で資材を調達できない。","respondent":"竹田住宅課長","answer":"令和２年度につきましては、期限いっぱいまでお受けして、予算を残して終了という形になってあります。年により需要が増減している状況です。できる限り需要を正確に把握して予算化していきたいと考えています。","voiceIndex":157,"id":"exchange-071"},{"speaker":"こんの委員","kind":"質問・要望","question":"今ご紹介があった令和元年は１２月２０日、令和２年は２月９日、令和３年は１２月２４日と、年度によって申請の件数は当然変わってくるだろうというところですか。ですので、区民サービスの公平性の観点からも、積極的な事業展開を要望するところですが、区のご見解をお聞かせください。","respondent":"竹田住宅課長","answer":"委員ご指摘のとおり、非常にニーズの高い事業です。新年度につきましては、令和３年度に比べまして３００万円ほど増となっております。今後も適切な予算化に努めていきたいと考えております。","voiceIndex":159,"id":"exchange-072"},{"speaker":"こんの委員","kind":"質問・要望","question":"歳出の部分は私も見させていただきまして、増額をしてくださっているということですが、もしこれが残念ながらまた年度途中で予算がいっぱいになってしまったというときには、ぜひ積極的に補正予算などを組んでいくという考え方も持っていただきながら事業展開をお願いしたいと要望で終わります。次にまいります。高齢社会対策包括補助金の中から、高齢者のスマホ教室についてお伺いしたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"こちらのスマホ教室、全２４コースということで、大きく人数も増やしています。具体的には、今年度は、定員上は１３２人というところでしたが、来年度、それらの倍増もしくは新設の教室によりまして、５０４人分の教室の定員の確保を予定しております。","voiceIndex":161,"id":"exchange-073"},{"speaker":"こんの委員","kind":"質問・要望","question":"定員を大幅に拡充してくださったというご説明でした。そうすると、すみません、しながわシニアネットがしてくださっているコースが、１１コースから倍で２２コースということですか。こちらの定員も合わせての今の定員数だったのでしょうか。そこを確認させてください。スマホ体験教室と、あと、相談事業もあるかと思いますけれども、そちらもぜひお知らせいただきたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"こちらの５０４人分の内訳についてです。しながわシニアネットに委託のスマホ教室につきましては、今年度１３２人分だったのですけれども、倍増するということで、来年度は２６４人という内訳です。残りの２４０人分についてが民間事業者によるスマホ教室ということになります。","voiceIndex":163,"id":"exchange-074"},{"speaker":"こんの委員","kind":"質問・要望","question":"補助金の内訳もお聞きしました。もう１つ、相談事業のほうのお答えも後ほどいただきたいと思います。なので、この方たちを全員品川区だけで全て対応するというのは、これは限りがあると理解するところですが、それにしても高齢者のデジタルデバイド解消、そして社会参加促進、こうしたことのために一人も取り残すことのないように展開してほしいと考えるところです。その点いかがでしょうか。","respondent":"菅野高齢者地域支援課長","answer":"１つ目、相談のほうのお話をします。こちらは、操作方法などをマンツーマンで気軽に相談できるスマホよろず相談も、スマホ教室と併せて、できれば同じ会場で実施したいと思っているところです。相談回数は週１回、約３会場４８週で１４４回を予定しているところです。","voiceIndex":165,"id":"exchange-075"},{"speaker":"こんの委員","kind":"質問・要望","question":"今ご答弁いただきましたように、他の事例も見て、また東京都のものも活用するという考え方、確認させていただきました。ですので、こうしたことも活用して、より多くの高齢者の方に、デジタルデバイド解消、社会参加促進を図っていただくよう、積極的な展開をお願いしたいというふうに思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-076"},{"speaker":"小芝委員","kind":"質問","question":"よろしくお願いします。私からは、７７ページの戸籍証明手数料、手数料全般について、また６１ページのなぎさ会館の活用についてお伺いいたします。手数料全般について伺います。手数料の負担が軽く、かつ利便性があるにも関わらず、コンビニ交付がいま一つ伸びていないとも思えてしまう予算になっておりますが、この見込みを出しました根拠、経緯について教えていただければと思います。","respondent":"木村戸籍住民課長","answer":"もともとマイナンバーカードの普及を進めるという意味合いも込めまして、コンビニで取ると１００円安くなるというような形で導入してきた経緯がありますので、引き続き、ＰＲ、その他、努めてコンビニ交付の普及を図ってまいりたいというふうに思っております。","voiceIndex":169,"id":"exchange-077"},{"speaker":"小芝委員","kind":"質問","question":"徐々に増えているというご答弁をいただきましたが、マイナンバーカードを持ってはいるけれども、窓口で申請するという方も多分いらっしゃると思います。そういう方々に何かそういうアプローチだとか、次回申し込んだときには、こういったマイナンバーカードをぜひお使いくださいとか、そういったアナウンスとかというのはされておるのでしょうか。","respondent":"木村戸籍住民課長","answer":"新たに区役所のほうでは、今、マルチコピー機がフロアのちょっと奥のほうにあるのですけれども、実際に証明を発行する近くに持ってきまして、お持ちの方であれば、もうそこですぐというような形をとっていきたいというふうに考えて、今、準備をしておるところです。","voiceIndex":171,"id":"exchange-078"},{"speaker":"小芝委員","kind":"意見","question":"二、三年前と比べまして、マイナンバーカード交付率は、２倍以上に伸びて、今や本当に区民の半数近く、４割５分ぐらいだと思いますけれども、そのぐらいまで普及されているかなです。ホームページ等でまた分かりやすく表示していただければと思いますが、その辺、お考えをお聞かせください。","respondent":"木村戸籍住民課長","answer":"引き続き、いろいろな広報媒体、ＳＮＳも使いまして、お知らせをしてまいりたいというふうに思っております。","voiceIndex":173,"id":"exchange-079"},{"speaker":"小芝委員","kind":"質問","question":"今や確定申告もスマートフォンをマイナンバーカードに接触させることで簡単に申告できるようになってきました。このサービスを行っているのは２３区ではまだ少なくて、ほかは港区だとか、渋谷区、中野区のみでありまして、品川区の証明書交付は大変選択肢が多く、もっともっと評価されてしかるべきかなとは考えております。","respondent":"木村戸籍住民課長","answer":"委員ご指摘のとおり、まだ認知がなかなかされていないというところもあると思いますが、日に１桁台というような形で、今、推移をしています。今後も、そちらも含めましてＰＲに努めてまいりたいと思います。","voiceIndex":175,"id":"exchange-080"},{"speaker":"小芝委員","kind":"質問・要望","question":"先ほど、正午に品川区のツイッターを見ていましたら、早速、戸籍証明書をオンラインでも申請できますというツイートがされておりまして、午前中に考えていた質問を切り替えなければいけないなと思いまして、こういうふうな形で流れているということですけれども、今後も広報や案内といったものを、ホームページでは分かりやすく、またＳＮＳでは頻繁に、週に何度か表示していただければ。","respondent":"木村戸籍住民課長","answer":"現在、国税のほうの納税証明書については、委員ご指摘のとおり、画面にデータとして証明書が送られてくるという形になったことは認識しておるところです。住民票、それから戸籍についても、基本的にデジタル化の動きはこれから出てくると思います。","voiceIndex":177,"id":"exchange-081"},{"speaker":"小芝委員","kind":"質問","question":"続きまして、６１ページのなぎさ会館の活用についてお伺いいたします。コロナ禍前に比べまして、どのくらい稼働率が下がっていったのか。その低下した稼働率を受けて、どのように評価されているのか、２点について教えてください。","respondent":"木村戸籍住民課長","answer":"利用の実績、稼働率ですけれども、令和元年度が約４０％、令和２年度が約２２％と落ちております。それから令和３年度に入りまして、２月末現在ですけれども、約３２％という形で少し盛り返してきておるところです。","voiceIndex":179,"id":"exchange-082"},{"speaker":"小芝委員","kind":"質問","question":"３年前の夏から、なぎさ会館の一角に授乳室のスペースを設けているというふうに聞いておりますけれども、あれから３年がたちまして、こちらの授乳室の利用状況をまず教えてもらってもよろしいでしょうか。","respondent":"木村戸籍住民課長","answer":"授乳室を開設いたしまして、のぼりも立てまして宣伝しておるところですけれども、実際のご利用はほとんどないような状況です。","voiceIndex":181,"id":"exchange-083"},{"speaker":"小芝委員","kind":"提案","question":"コロナ禍にある中で変化してきた生活スタイルは、人生の幕引きの場面にもその変化が現れているかなと感じている次第です。コンパクトにした分、その空いたスペースでは、稼働されていない日に、例えば、会議だとか、集会だとか、また卓球など、そういった場所をとらないスポーツも運用できるのではないかなと提案したいと思いますが、お考えがありましたら、お知らせください。","respondent":"木村戸籍住民課長","answer":"やはり葬祭される方々のお気持ちというのですか、そういう部分も考えて、なかなか厳しいかなというところではありますけれども、稼働率のご指摘の部分は、私どもも認識しておるところですので、引き続き研究を続けてまいりたいというふうに思います。","voiceIndex":183,"id":"exchange-084"},{"speaker":"小芝委員","kind":"提案","question":"なぎさ会館の活用はとても魅力的でありまして、夢のある選択肢、私が先ほど提案した以外のものも残されていると考えますので、ぜひ今後とも、なぎさ会館の積極的な活用を促したいことを要望しまして、時間が余りましたが終わらせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":185,"id":"exchange-085"},{"speaker":"のだて委員","kind":"質問","question":"私からは、５０ページから始まる歳入の特徴について、あと、１５７ページの雑入に含まれる子どもすこやか医療費助成について、１１１ページの障害者福祉手当等支給事務に関連して、心身障害者医療費助成について伺います。歳入の特徴です。こうしたところを見ていくと、区の財政は随分余裕があるなというふうに感じます。納税義務者が減っているのに、特別区民税が過去最高額なのはなぜか、理由を伺います。","respondent":"提坂税務課長","answer":"コロナ禍ですけれども、令和３年度の当初より経済活動の再開の動きが見られるということと、あと、東京都の完全失業率は全国の２.８％を上回っているものの、前年同期比では若干下がっている、そのようなもろもろの事情を見込んで、令和３年度の当初見込みの納税義務者よりも。","voiceIndex":187,"id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"高所得の５０代の方が増えているというところ、ほかにもいろいろご説明されましたけれども、全体の人口は減っているというところで、そういったところが増えているということは、より高額所得者の方が転入してきているのかなというふうに感じるのですけれども、全体としては、つまり、コロナで仕事がなくなった方が増えて、納税義務者が減ったということではないかというふうに思うのですが。","respondent":"提坂税務課長","answer":"所得層のことで少し補足しますと、納税義務者のうち総所得７００万円超の方の割合が４３％を占めまして、全所得層に対する税額の比率の約５割を占めているという実情もあります。","voiceIndex":189,"id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"失業率は今後改善していくというようなお話でしたけれども、やはり依然としてコロナ禍が続いている、こうした下で、区民の生活はいまだ厳しい状況にあると思います。過去最高の歳入を福祉の増進に活用していただきたいと思うのですが、いかがでしょうか。そのためにも区民の実態を把握して予算編成に反映していくべきだと思いますが、いかがでしょうか。","respondent":"提坂税務課長","answer":"その都度、納税相談のほうで、お一人お一人の実態をよくお聞きしまして、分割納付のご相談ですとか、徴収猶予のご相談とか、その辺をじっくりと提案させていただいて、納付完結へ向けた対応をさせていただいているところです。","voiceIndex":191,"id":"exchange-088"},{"speaker":"のだて委員","kind":"質問・要望","question":"税務のほうではそういった対応もしているということですけれども、区全体の政策としても、ぜひそういった区民の苦しい実態をしっかり反映して予算組みをしていただきたいというふうに思います。コロナで減収を予測していた法人住民税が増えたと区は説明しています。コロナで打撃を受けている業種とは何か、Ｋ字回復ということは、事業者にも格差が広がっているのではないかと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"いろいろな業種、当然、対面サービスというところが非常に痛手を受けているということはご承知のことかと思いますが、同じ業種の中であっても、それぞれ対象になっている販売の相手先とかというところで、同じ業種の中であっても、うまく乗り越えられているところと。","voiceIndex":193,"id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"業種の中でもいろいろ違いがあるというような答弁だったと思いますが、つまりは、格差が広がっているということではないかと思いますけれども、改めて伺いたいと思います。その打撃を受けている業種についても伺ったので、ご答弁いただければと思います。","respondent":"遠藤商業・ものづくり課長","answer":"打撃を受けているところに対しましても、新型コロナウイルス感染症対策助成とか、あるいは、特に融資という部分では、ほかの区にもないメニューをご用意させていただいているところですので、引き続き来年度におきましても。業種につきましては、先ほど言いましたとおり、対面サービスという形になりますので、例えば飲食業とか、宿泊業というようなものが中心になるかと考えています。","voiceIndex":195,"id":"exchange-090"},{"speaker":"のだて委員","kind":"質問","question":"今、特に出されたのが飲食業と宿泊業ということですので、この際、打撃を受けている業種への支援を強めていくべきだというふうに思いますけれども、いかがでしょうか。区民が外出する機会なども減っていますので、全体的に影響が出ているという状況です。増収見込みの財政を活用して、事業復活支援金では救えない中小企業に、区独自の金額の上乗せや、対象拡大を実施すべきだと考えますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"事業復活支援金、国のほうでやっていますけれども、こちらにつきましては、国のほうで給付対象や要件、金額等を決めているところですので、私どものほうでの上乗せ助成等は考えておりません。","voiceIndex":198,"id":"exchange-091"},{"speaker":"のだて委員","kind":"質問","question":"いろいろやっているというような説明をされましたけれども、やはり直接支援が必要だと思うのです。この間、コロナが２年間続いております。こうした中で、なかなか影響が回復していかないというところもあると思いますので、そうしたところに直接支援をしていくということが必要ではないかと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"繰り返しになりますけれども、現在のところは、事業復活支援金等、国の補助金等への上乗せ助成、直接支援については考えていないところです。","voiceIndex":200,"id":"exchange-092"},{"speaker":"のだて委員","kind":"質問・要望","question":"直接支援は考えていないということですけれども、やはり過去最高の歳入を生かして、そうした事業者にも支援をしていくということが私は必要だと思いますので、ここは要望しておきたいと思います。次に、心身障害者医療費助成、いわゆるマル障の拡充について伺います。この助成対象の拡充を東京都に求めていただきたいと思いますが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"区といたしましては、この制度の趣旨に鑑みまして、対象者の拡大を、現在のところ、東京都に求めていく考えはございません。しかしながら、お困りの方については、様々な医療制度がありますので、その中で十分に相談に応じてまいりたいとも考えております。","voiceIndex":202,"id":"exchange-093"},{"speaker":"のだて委員","kind":"質問・要望","question":"精神障害の方についても、やはり２級などになっている方は仕事ができないという状況ですので、そうした下で医療費がさらにかかってくるということは、やはり負担感が強いという状況になっておりますので、こうしたところにやはり支援をしていくということが必要だと思うのですけれども、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"そういったお困りの声につきましては、東京都には情報を提供しますが、制度全般につきましては、東京都全体の制度の実態を鑑みて、改正するかどうかを決めるものと考えております。","voiceIndex":204,"id":"exchange-094"},{"speaker":"のだて委員","kind":"質問・要望","question":"全体と言いますけれども、ぜひ区としてもそこは求めていただきたいと思います。次に、１８歳までの医療費助成です。東京都が２０２３年度からの実施の準備のために予算を計上しましたが、詳細については各自治体と協議するとの説明です。東京都との協議に当たり、１８歳までの医療費助成について、所得制限なしで自己負担をなくすよう求めていただきたいと思いますが、いかがでしょうか。","respondent":"伊東子育て応援課長","answer":"東京都は、細かいことをまだ示しておりませんので、その話を聞きながら進めていきたいというふうに考えております。","voiceIndex":206,"id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ所得制限なしで、負担もなく無料でできるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-096"},{"speaker":"西本委員","kind":"質問","question":"１１５ページの保育園公設民営化について、まずお聞きします。民営化がもう始まっておりますけれども、メリットは何ですかということを聞きたいと思います。そして、今後の公立保育園の方向性、それから将来像は、どういうものなのでしょうか。様々な補助金、国等からありますけれども、運営費が、公立保育園の場合と、公設民営の場合とでは、どのぐらい違いがあるのでしょうか。残念ですよね。","respondent":"初貝保育教育運営担当課長、廣田子ども育成課長","answer":"それと、公設公営が公設民営、そして民設民営になったときですけれども、そちらは、ある一定、運営費に対して補助金が入ってくるというところで、ただ、どういう形態にするかとか、規模によって様々ありますので。課題として考えているのは、この親育ちのワークショップに親子で来てくださる方は、まだ親としてどうしていこうという問題意識がある方というふうに認識しておりますので、ここに来ていない方たちというところで。","voiceIndex":210,"id":"exchange-097"},{"speaker":"西本委員","kind":"質問・要望","question":"公立ではできないのでしょうか。なぜ民間でなければできないのですか。公立ではできないのですか。やればいいではないですか。できたはずです。民間に頼まなければいけない理由は何でしょうか。親子のつながりをつくるためのきっかけとして捉えてほしい。親としてやっていただきたいことをちゃんと踏まえた形で行政はやっていかなければいけないと思いますが、その関わり方についてお聞きしたいと思います。","respondent":"立木保育課長、廣田子ども育成課長","answer":"そうした中、やはり民間の事業者にお任せできる部分はお任せして、あと、公立保育園は、公立保育園がやるべき仕事のところを、やはりこれからもしっかりやっていくというところで、数の検討というのは必要になってくると思いますが。一方で、両親が就労、介護など、今、多様化していて、子育ての負担感を感じている方が多くいらっしゃることも認識していますので、今後どうしていくかということも含めて考えていく課題だと認識しております。","voiceIndex":213,"id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"もっと自信を持ってください。公立保育園の皆さん、頑張ってやってきているわけですから、何をしなければならないのか、公立のやるべき仕事、保育をしっかりと突き詰めてください。親のやるべきことをしっかりと踏まえた形で検討していただく。やっぱり福祉が必要なところもありますので、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":216,"id":"exchange-099"},{"speaker":"たけうち委員","kind":"質問・要望","question":"みずほ銀行は、これはちょっと単純な確認ですけれども、昨年から、また今年になってからも、いろいろシステム障害とか、区民の方が下ろすキャッシュコーナーなどのトラブルが結構続いていまして、私もみずほ銀行、個人的に口座を持っているのですけれども、変えなければいけないというふうに思うときもあるのですけれども、でも、変えるとなかなか手間で変えられないのですが、その辺のところ。","respondent":"提坂税務課長、中山会計管理者、山下子ども家庭支援センター長","answer":"経済が回復しまして、人口減に歯止めがかかったという推測ができれば、さらに税収を増加させることができるかなと考えていますけれども、２月１日の時点で。その都度、みずほ銀行のほうから、会計管理室のほうに説明も受けておりますし、２３区の会計管理者の会としても。委託先ですけれども、現時点でどこというふうに決めているところではございませんで、今後。","voiceIndex":218,"id":"exchange-100"},{"speaker":"たけうち委員","kind":"質問・要望","question":"みずほ銀行のほうは分かりました。今後、すぐどうのこうのということではないのですけれども、やっぱり非常に心配で、大事なところで何か大きなトラブルになってはいけないなということもあるので、注視していただきながら、引き続き、安心の管理をやっていただければなと、これは要望です。それから、実態把握調査委託、これは入札か何かするのですか。","respondent":"佐藤企画調整課長、山下子ども家庭支援センター長","answer":"もう一方で、コロナ禍が時代の大きな転換になりますので、そういったものにもきめ細かく対応して、区としてバランスよく政策を進めていくことが人口減少の歯止めになると考えております。委託につきましては、これからというところでございまして、実際に調査項目でしたり、先行の自治体の事例等を研究しながら、仕様書等を整えまして入札という形になるかと思いますけれども。","voiceIndex":222,"id":"exchange-101"},{"speaker":"たけうち委員","kind":"質問","question":"最初のほうの件は、昨日もお話ししたのですけれども、大変な厳しい方たちへの対応をしっかりやっていくというのは第一義ではあるのですけれども、今後の税収ですとか、また、いろいろ品川区の発展のためというか、いろいろな政策を打っていくための財源という面で見ていくと、やはり働き盛りの比較的税収の高い方たちにどうやって品川区に定住してもらう、または。","respondent":"佐藤企画調整課長","answer":"全てバランス的な事業の展開と、品川区は質素倹約で健全財政を築いておりますので、そういった強みを生かして、今後もしっかりと様々な事業を展開していきたいと考えています。","voiceIndex":225,"id":"exchange-102"},{"speaker":"西村委員","kind":"提案","question":"９５ページ、すまいるスクール運営費、９７ページ、ネウボラネットワーク経費、順不同で伺ってまいります。ネウボラネットワーク経費ですが、ドゥーラについて伺ってまいります。そこで、区民ニーズの高いドゥーラ利用の利便性をより高めるために、確認と提案をします。ドゥーラが不足していないか、マッチングについて伺います。","respondent":"山下子ども家庭支援センター長","answer":"産後の家事・育児支援、ドゥーラの利用についてのご照会です。","voiceIndex":228,"id":"exchange-103"},{"speaker":"西村委員","kind":"質問・要望","question":"ドゥーラからも実際にお声を伺っています。一度利用したことのある方であれば、区民からドゥーラに直接相談がいきまして、ドゥーラの間で連絡網を駆使して見つけてくださるというようなこともあると伺っています。利用検討者がマッチングしていない状況を把握していただきまして、今後は、ベビーシッターによる一時預かり利用支援のご案内を必ずしていただきたいと思いますが、いかがでしょうか。","respondent":"山下子ども家庭支援センター長","answer":"そちらの催物に際しましては、オリンピック・パラリンピックのノベルティ等をいただくなど、部をまたいでいろいろお力添えをいただきながら、こちらのマッチングが何とかならないかというところで取り組んでいるところですけれども、まだ形として。","voiceIndex":230,"id":"exchange-104"},{"speaker":"西村委員","kind":"質問","question":"申込み利用手続きの見直しについてですが、以前質問させていただきまして、区ホームページの利用の流れが改善されております。それぞれの予約可能日が分からず、利用者が登録ドゥーラ１人ずつに、メールアドレスをコピーして希望要件や日時を送っていると伺いました。続けて、助成金の申請の手続きも伺わせていただきます。これは役所で打ち直しておられるのかどうか伺います。","respondent":"山下子ども家庭支援センター長","answer":"通常、オンラインの手続きですと、区と区民とというように２者で終わるものにつきましては、大分デジタル化が進んでいるところですけれども、本事業におきましては、区とドゥーラと区民の方とというところで、３者が関係するところから、なかなかオンライン化というか。","voiceIndex":232,"id":"exchange-105"},{"speaker":"西村委員","kind":"確認","question":"よく分かりました。続けて、すまいるスクール運営に関して、コロナ禍における状況を伺ってまいります。このことに関しては、昨年のご答弁より、人数確認のために、ある程度利用の予定をいただいていると伺い一定の理解を示しておりますが、現状、受入体制の課題や、イレギュラーな申込みがどの程度あるのか。昨年度との比較など、実数でなくても構いませんので状況を伺います。","respondent":"廣田子ども育成課長","answer":"大分感染状況につきましても落ち着いたというか、保護者の皆さんもコロナの対応に大分なじんできたというか、就労される方も、働き方も落ち着いてきたというところで、人数については、ある程度の一定人数で落ち着いているところです。","voiceIndex":234,"id":"exchange-106"},{"speaker":"西村委員","kind":"質問・要望","question":"よく分かりました。正に、この後申し上げたかったことをご答弁いただきました。というのも、実際に保護者の方々に伺いますと、以前は、当日、すまいるカードに利用時間を書いていけば利用できたけれども、今はできないという認識がまだまだ多くあるように思うのですが、その周知も含めましてご検討いただきたいと思いますが、その辺り、状況も含めてご見解をお聞かせください。","respondent":"廣田子ども育成課長","answer":"状況によっては、就労されていなくても遊びに来ているとか、子どもの状態でここに来るほうが望ましいというお子さんに関しては、学校のほうからも、ご家庭にいるよりもこちらがという助言をいただいてお預かりしている方もいらっしゃるのですけれども、スペースの関係が。","voiceIndex":236,"id":"exchange-107"},{"speaker":"西村委員","kind":"質問・要望","question":"どうぞよろしくお願いいたします。区立学童では費用も大幅に民間と異なるため、死活問題になるという自治体があると伺っております。１６年がたつのかと思うのですけれども、今を生きる子どもたちには、今の子ども、保護者の声を基に施策を考えるべきと考えます。一概に今のお母さんたちが楽をしたいからお弁当を要望しているのではないというふうに思っています。食事は、朝食も夕食もつくっております。","respondent":"廣田子ども育成課長","answer":"食の支援のお話ですけれども、他の自治体の状況について、今後、調査をしていきたいと考えているところです。","voiceIndex":238,"id":"exchange-108"},{"speaker":"西村委員","kind":"質問・要望","question":"先ほど、つる委員もおっしゃっておられましたけれども、お母さんたちの声、全てのお母さんがおっしゃっているとは思いませんが、やはり多くの声が区民の方たちの声で届いておりますので、ここはしっかりと聞いていただきまして、行政のサービスに取り入れていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":240,"id":"exchange-109"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、９１ページの国庫補助金の個人番号カード交付事務費補助金から、マイナンバーカード、そして、デジタル化について伺いたいと思います。区の認識を改めて伺いたいのと、マイナポイントの第二弾も使ってやっているのに、伸びない理由は何だとお考えか伺います。","respondent":"宮澤情報推進課長","answer":"区のマイナンバーカードの交付率がマイナポイント第一弾のときは２０％台だったのが、令和３年１２月、マイナポイント第一弾の終了時には、約４３％ということで倍増していますので、マイナポイント事業の目的の１つにマイナンバーカードの普及がありますが。","voiceIndex":243,"id":"exchange-110"},{"speaker":"石田（ち）委員","kind":"質問","question":"伸びない理由も伺ったのですけれども、これから伸びてくるだろうというふうに見ているということでしょうか。マイナンバーは、今年３月から健康保険証との一体化が始まっています。それで、国に管理監視され、さらに企業のもうけにされていく。ＤＸ推進計画は、地方自治の本旨も、住民福祉の増進を図るという立場も欠如していると思いますけれども、区の見解を伺います。","respondent":"宮澤情報推進課長","answer":"マイナンバーカードにつきましては、それらのデジタル化を進める上での基盤となる制度ですので、普及等も進めていくという考えです。","voiceIndex":245,"id":"exchange-111"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、本来、自治体における情報通信などデジタル技術は、住民の幸福や健康に資するものでなくてはならないと思っています。地方自治の発展や住民福祉の増進のために、この技術を有効に活用することこそ求められていると。ですので、そうした立場で、地方自治の本旨、そして住民福祉の増進を図るという立場で、ぜひ進めていただきたいと思いますけれども、いかがでしょうか。","respondent":"宮澤情報推進課長","answer":"情報の管理という部分です。マイナンバーの仕組みとしまして、各行政機関等で情報連携を進めております。ただ、それは国のほうで情報を一括で管理しているというわけではなくて、各団体等で持っている情報を必要に応じて情報連携しているという形になってあります。","voiceIndex":247,"id":"exchange-112"},{"speaker":"大沢委員","kind":"質問・要望","question":"歳入全体についてと、７３ページを聞きます。６０ページ、使用料。全体的なものを伺う前に、ぜひとも今日、黒田財政課長とお話させていただきたいなと考えています。ところが、最初は、産業経済使用料でものづくり創造センター、これは、去年の予算書にはありまして、今年は見当たらないのですけれども、これはどうなってしまったのでしょうか。それを教えていただきたい。","respondent":"遠藤商業・ものづくり課長","answer":"ものづくり創造センターですけれども、こちらにつきましては、今年度で貸出しは全て終了という形になりまして、来年度につきましては、情報推進課のほうで使うという形になりますので、使用料としては発生しないという形になっているところです。","voiceIndex":250,"id":"exchange-113"},{"speaker":"大沢委員","kind":"質問","question":"ものですから、活用されたのでしょうか。活用せずして転用させたと、そこが大事なところで、お願いします。","respondent":"遠藤商業・ものづくり課長","answer":"これまではいわゆる事業者に使っていただいたところですが、ほかの施設などもできているところで、来年度につきましては、一応、別のほうに貸すという形で進めているところです。","voiceIndex":252,"id":"exchange-114"},{"speaker":"大沢委員","kind":"意見","question":"はい、結構です。歳入確保の観点から、ここのところ、財政課長が、歳入確保、今、手数料および使用料ということで、歳入確保というところで行政の方たちは行われているわけですけれども、歳入確保の観点から、各課、依命通達なるものも出て、各長の方たちには、その旨の周知がされていると思いますけれども、どのような指導、どのような助言をされているのか、ご披露ください。","respondent":"黒田財政課長","answer":"依命通達の中で歳入に関する事項といたしましては、区税収入につきましては徴収努力のところをお願いしておりまして、使用料、手数料については、受益者負担の適正化の検討、その他の収入については、税外収入の一層の確保というところで、依命通達により。","voiceIndex":254,"id":"exchange-115"},{"speaker":"大沢委員","kind":"質問","question":"本日は、使用料、手数料ですけれども、これ、歳入全般ということにもなりますので、今、３項目おっしゃっていましたけれども、最も的確な回答は、この依命通達、歳入に関する事項で、これを徹底させるべく助言、指導していると、このような考え方でいいのでしょうか。","respondent":"黒田財政課長","answer":"予算編成に関する基本方針ということを依命通達でお示ししておりますので、ここでお示ししている項目が基本的な予算編成の歳入確保の考え方ということで、各部局のほうに通達しているものです。","voiceIndex":256,"id":"exchange-116"},{"speaker":"大沢委員","kind":"質問・要望","question":"そうなると、４月になると、今度は執行に関する依命通達が出てくるのですけど、これについては、どのように、まだちょっと早いですけれども、お話しできる範囲で執行に関する依命通達をお話しいただきたいと思います。","respondent":"黒田財政課長","answer":"予算はあくまでも計画として見込みを立てているものですので、執行に当たっては、その見込みを下回らないように、いろいろな情勢の変化等ありますけれども、そういった形で歳入確保の努力、また、予算編成時にないような動きがあれば、そういったところも新たにとらまえて。","voiceIndex":258,"id":"exchange-117"},{"speaker":"大沢委員","kind":"質問","question":"約１,８９１億円ということになっておりますけれども、昨今のコロナ禍の中では、明らかにマイナス要因が発生し、全体的な予算規模よりも、実際の事業については縮小されるのではないかと予想されるのですけれども、そこらの予想されるマイナス要因について、まず伺いたいと思います。","respondent":"黒田財政課長","answer":"予算編成の中では、コロナの収束も見据えて、各事業の計画を立てて予算要求をいただいているところもありますが、当然、今、オミクロン株の収束の状況でありますとか、その他、予定どおりに活動できないということがあれば、当然予算を執行できないことがありますので。","voiceIndex":260,"id":"exchange-118"},{"speaker":"大沢委員","kind":"質問","question":"例えば、使用料ですか、これ。約４５億円という使用料の予算を見込まれております。この使用料というのは、今、課長がおっしゃったように、コロナの影響をうんと受けます。よって、本年度の初日、昨日行った補正予算でも約６,９００万円を減額補正しているところでありますけれども、来年度、この約４５億円という金額、このようなものを勘案して、どのように積算をされたのか教えてください。","respondent":"黒田財政課長","answer":"使用料につきましては、各所管課のほうで管理している施設の来年度の工事の予定ですとか、使用の予定などを勘案して、使用できるコマ数が出てまいりますので、そういった中で、一定程度、このぐらいの利用があるだろうというところを見込んで要求があり。","voiceIndex":262,"id":"exchange-119"},{"speaker":"大沢委員","kind":"提案","question":"当然ながら、予算ですから、見込みということで予算立てをしていくわけでありますが、使用の見込みを立てながら編成したという、しかしながら、消費者心理でしょうか、冷え込んでいる、施設を使う消費者心理、仮にこのオミクロン株、このコロナ禍が収束をしても、消費者心理、我々区民が区民サービスを受けるという意味での消費者心理が冷え込んでくると、そこを持ち直すことせずして。","respondent":"黒田財政課長","answer":"区の施設を使って行う区の事業であれば、当然そういった事業をＰＲする中で活発に活動していくというところを、まず区として率先して行いまして、そういった中で民間の活動が盛り上がってくれば、区の施設を使って、そういった活動も、営業というか。","voiceIndex":266,"id":"exchange-120"},{"speaker":"大沢委員","kind":"質問・要望","question":"かつての高橋区長は商人でありましたから、やはり行政サービスはサービスだというようなことを考えており、なぜ冷え込んでしまったかというと、高齢者の方が使う部分が多いので、感染を恐れるがあまり二の足、三の足を踏んでしまって、なかなか、仮に収束あるいは解除されても上がっていかないのではないかという、そういう危惧感からこの質問を最後にさせていただきましたので、そこのところも勘案しながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":268,"id":"exchange-121"},{"speaker":"若林委員","kind":"質問・要望","question":"１４３ページの歩行喫煙防止過料について伺いたいと思います。まだ年度途中といいますか、３月、今年度の状況について、大井町、青物横丁、五反田、武蔵小山、大崎というふうにありますけれども、指導件数でありますとか、過料の実績の状況をお知らせいただきたいと思います。それからもう１つは、新年度、令和４年度の、過料、歩きたばこを減らす取組みについてお聞きしたいと思います。","respondent":"森田生活安全担当課長","answer":"大崎や五反田については、指導や過料が多いです。これにつきましては、人の導入が多いところでもありますし、また、指定喫煙所が閉鎖していることもありまして、取締り、また指導が多くなっているものというふうに認識しております。","voiceIndex":270,"id":"exchange-122"},{"speaker":"若林委員","kind":"質問・要望","question":"逆に、指定喫煙所があるから、違反者、または指導がこの程度でとどまっているということも逆に言えるのかもしれません。この指定喫煙所の区の中での位置づけ、根拠というのはどういうところにあるのか、条例上か、要綱上か、どういう位置づけになっているのかを確認したいと思います。これを確認させていただきたいと思います。","respondent":"森田生活安全担当課長","answer":"これであると、違うところにまた喫煙者が行ってしまうというような、いろいろな状況もありまして、いろいろと検討しています。","voiceIndex":272,"id":"exchange-123"},{"speaker":"若林委員","kind":"質問・要望","question":"例えば、大崎駅の西口等では、パーテーションの外での路上喫煙イコール条例違反が大変多く見受けられている。地域の方からも苦情を聞いておるというところで、コンテナ型喫煙所が設置された折には、絶対にそのコンテナの外で喫煙をしない、条例違反をさせない、このことの徹底をひとつお願いしたいと思います。時間がありませんので、要望としますので、来年度もどうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":274,"id":"exchange-124"},{"speaker":"芹澤委員","kind":"提案","question":"私からは、１１３ページ、障害者施策推進包括補助金で障害者の雇用について、あと、１４３ページのオリンピック・パラリンピックスポーツ等振興事業についてお伺いします。障害者の雇用についてですが、事前に伺ったところ、品川区の障害者雇用に関しては、現時点で２.１％と伺っています。ご見解をお聞かせください。","respondent":"崎村人事課長","answer":"やはり毎日、例えば入力作業ですとか、資料作成などをしていただくにしても、やはりどうしても役所ですと紙ベースからつくるというところですとか、個人情報が含まれているものも多々ありますので、そういったところから、まず庁舎に来られない。","voiceIndex":276,"id":"exchange-125"},{"speaker":"芹澤委員","kind":"質問・要望","question":"ただ段差がないという話ではなくて、車椅子とすれ違えるかというだけでもかなり厳しいと思っていて、もちろん全てのスペースでできるとは思っていないですが、やはりこれ、模索はしていくべきだなと思っていますので、そちらも併せてご見解をいただければと思います。今年度、東京オリンピック・パラリンピックが開催されて、共生社会の実現というものもありました。ご見解をお聞かせください。","respondent":"崎村人事課長","answer":"先ほど説明が不足していた部分があるのですけれども、区では、障害者雇用を促進していく上で、来年度に向けて、障害者を対象にした会計年度任用職員を採用しまして、各課の印刷ですとか封入等の軽作業を引き受けるという業務支援室を設置する予定です。","voiceIndex":278,"id":"exchange-126"},{"speaker":"芹澤委員","kind":"提案","question":"前向きにありがとうあります。最後に、オリンピック・パラリンピックのレガシーについて伺います。これは以前もご提案をしたのですが、ぜひレガシーとして、ボッチャの大会をしていただきたいなと思っていて、ボッチャというのは、スポーツでもありますけれども、レクリエーションでもあると思っています。ご見解をお聞かせください。","respondent":"中元スポーツ推進課長","answer":"このような実践を積み重ねまして、他自治体で開かれている大会の運営手法も調査研究し、今後、大会の開催を検討してまいりたいと思っているところです。","voiceIndex":280,"id":"exchange-127"},{"speaker":"芹澤委員","kind":"意見","question":"いろいろなスポーツがあって、他のスポーツが今開催されている中、それを押しのけてやってしまうと、なかなかそれも軋轢が出てしまうので、それはぜひ逆に他のスポーツの方々にもお手伝いいただいて、協力関係を得ながら、すばらしい大会を実現していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":282,"id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"よろしくお願いします。１４０ページの寄附金ですけれども、こちらは議案の説明のときに伺いました。ＴＯＣからの寄附と伺っております。どのような公共施設の整備、また移転等に活用していくのでしょうか。そして、第一日野小学校の移転に関する問題は、様々な経緯があり、ここまで結論が出されたことは、大変多大なご苦労があったと思います、ということでお尋ねしています。","respondent":"佐藤企画調整課長","answer":"ご質問は、どのような施設に充てるのかというところだと思いますが、寄附の趣旨が、西五反田の公共施設のにぎわいといいますか、そういったものに資する施設にですので、今後、当面、暫定施設のほうで活用しますが、その後の本格活用については。","voiceIndex":284,"id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、支払い時期については、行財政改革特別委員会の資料によりますと、都市計画決定後とあります。都市計画決定の見通しについては、いかがでしょうか。その都市計画決定は、お話しできれば、どのようなものになる見込みでしょうか。そして、時期がその２か月後とあるので、これは予算案の公共施設整備基金の積立て額に含まれているのでしょうか。","respondent":"佐藤企画調整課長、鈴木都市計画課長、黒田財政課長","answer":"委員ご指摘のとおり、納付時期は都市計画決定後２か月以内ですが、都市計画決定時期は、今のところ未定というというふうに聞いております。ＴＯＣの都市計画の現時点の計画ですが、３月の品川区の都市計画審議会にお諮りをして都市計画決定を進めるというような予定になってあります。この寄附金につきましては、公共施設整備基金への積立ての財源として上げているものです。","voiceIndex":286,"id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"すみません、都市計画のほうも伺って。それで、資料には「費用負担の協定」というような表現があるのですけれども、寄附として協定締結ですけれども、負担ということであれば利害関係が生じるので、根拠を示すために、負担金の条例を設けると、この辺、私、ちょっと不勉強なので、その辺のご説明をいただきたいということです。そして、なぜ寄附という形にしたのでしょうか。","respondent":"佐藤企画調整課長","answer":"委員ご指摘のとおり、「負担」となりますと、法令等で何かしらの根拠がないと「負担」はできないというところと、私どもの方で弁護士に相談しながら、どういった形がとれるのかというところ、あと、協定のほうには負担は全額とも一部とも書いていないというところもありますので。","voiceIndex":290,"id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問","question":"現時点で今のご説明で納得、理解できました。新庁舎整備基金のほうに寄附があるというお話を課長にいただいたのですが、そこはまだ具体的にどこの方が幾らというのは出ていないのであれですけれども、それはちょっと今、そことの協定を結ばなかったものとの関係は、今お話があったＴＯＣとの関係で言うと、違いは、これまでの経緯があったというところなのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":292,"id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません。新庁舎整備基金のほうに寄附が１件あるというふうに昨日ご答弁をいただいたので、そちらについて、今みたいな協定等を結んでいないとすれば、今後結んだりするのでしょうか。","respondent":"東野庁舎計画担当課長","answer":"特に協定とか、そういうことではなくて、区民の方のご意向をそのまま庁舎計画のほうに反映させていきたい、そういう思いです。","voiceIndex":294,"id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"質問","question":"質問の趣旨が分かりにくくて申し訳ありません。それで、この国庫補助に関して算定するときに、そのかかった費用の中から、その寄附を除いて補助が出てくるのか、それとも、その補助も含まれて、費用がこれだけかかったということで補助が出てくるのか、その辺もご説明をお願いします。","respondent":"黒田財政課長","answer":"事業の種類にもよりますが、基本的に、寄附があった場合については、寄附の部分を除いたものが事業費の対象となりますので、いわゆる補助対象事業にもよりますけれども、基本的には、寄附は特定財源として除かれるというものです。","voiceIndex":296,"id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問","question":"この件はまた勉強して説明を伺いたいと思います。今、寄附していただいたというのは大変すばらしいことですが、公共施設整備基金に入れてしまうということは、ＴＯＣの気持ちといいますか、寄附したということが消えて残らないですよね。そこで、１７億円の基金のような形で設定しなかったのは、先ほどのご答弁との関係もあるのでしょうか。その点を伺います。","respondent":"佐藤企画調整課長","answer":"寄附の名目が西五反田地区公共施設整備指定寄附というところで、寄附していただいた民間事業者とも話をして、こういった公共施設整備基金に積立てて、今後の本格活用に使わせていただきますよというご説明をしているところで、両者が理解しているものだと考えております。","voiceIndex":298,"id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今ご説明があったように、そういった目的のために寄附をいただいたので、ぜひ活用して、この事業に反映させていただきたいと思います。もう１つは、基金繰入金の減債基金繰入金ですが、充当事業があって、そこの繰入金のところに１０億９,９００万円余とあります。これは減債基金を充当してもいいと思うのですが、それを入れないで一般財源となるのでしょうか。すみません、時間が厳しくて。","respondent":"黒田財政課長","answer":"そのほかの部分につきましては、その他の建設事業債の財源調整として充てておりますので、全体の特定財源等を充てた後の財源調整の中で、いわゆる建設に関する起債の返還を財源調整として使っておりますので、少し端数が出てしまうといったところがありますので。","voiceIndex":300,"id":"exchange-136"},{"speaker":"大倉委員","kind":"質問","question":"私からは、１２９ページ、都市防災不燃化促進事業から、本年度対象地域になっている放射２号線に関連して伺いたいと思います。時間があれば、雑入のほうで、品川区のＬＩＮＥ公式スタンプについて教えていただければと思います。","respondent":"鈴木都市計画課長","answer":"放射２号線の現在の用地取得率ですが、令和３年３月末のデータですが、現在、３９％というような用地取得率です。全体の計画的なところとしましては、事業期間見直しが行われまして、令和８年３月３１日までの事業期間になっているです。","voiceIndex":303,"id":"exchange-137"},{"speaker":"大倉委員","kind":"質問・要望","question":"それと、そういったところの利用というか、活用というか、使っているところがあるというふうにも伺っているのですが、そうした活用の状況とか現状、どういった活用がされているかを教えていただきたい、まずそれをお願いします。","respondent":"森木密整備推進課長","answer":"今、同じ特定整備路線の中の、補助２９号線について、木密整備推進課のほうで地域の方々と話合いをしているところがありますので、私のほうから回答します。","voiceIndex":305,"id":"exchange-138"},{"speaker":"大倉委員","kind":"質問・要望","question":"あの辺、例えば、先ほどのお話の中だったら、荏原一丁目、放射２号線のところだと、あそこは町会会館が引っかかっていて、町会会館を壊して違う公園の敷地に移設というところでは、公園が狭くなってきたりしている部分もあったりするので、そういったことも含めて影響があるところについては、ぜひともお声を聞いていただきながら進めていただきたいなと思うのですが、この利用の決まり、例えば。","respondent":"森木密整備推進課長","answer":"基本的には、特定整備路線の道路予定地ですので、できることはひとつ限られる部分があるのかなというふうには思いますけれども、せっかく地域の方々の身近にそういった部分がありますので、様々な意見を聞きながら、東京都と前向きに検討していきたいというふうに考えております。","voiceIndex":307,"id":"exchange-139"},{"speaker":"大倉委員","kind":"質問・要望","question":"以上で、この件に関しては終わります。品川区のＬＩＮＥ公式スタンプですが、令和２年、令和３年の予算だと、１０万円とか、５万８,０００円とか、ちょっと減っているなというところで、実際どのぐらいが売上げとしてあるのかというところを教えていただきたいのですが、お願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"機運醸成で作成しましたＬＩＮＥスタンプについてのご質問かと思います。こちらは、第一弾、第二弾の販売をしまして、それぞれ全体で合わせて１０万円弱です。これは売った分が全て入るわけではなく、ＬＩＮＥが販売した分の一部が配当金として入るです。","voiceIndex":309,"id":"exchange-140"},{"speaker":"大倉委員","kind":"質問","question":"今年度予算としては、どのくらい見込まれているのかというところを教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらのＬＩＮＥスタンプですが、東京２０２０大会も終わったということで、販売自体も本年度の３月をもって終了する予定です。したがいまして、令和４年度の歳入のほうには入っておりません。","voiceIndex":311,"id":"exchange-141"},{"speaker":"大倉委員","kind":"質問","question":"販売が終わるということで、非常に残念に思っております。私も第一弾、第二弾と購入して、様々なところで、ほかの自治体の議員にも送って、品川区はこういうのをやっているのだよとアピールもしてきたのですが、今回で終わってしまうということで、ＬＩＮＥスタンプ、活用してみてどうだったか。この辺の評価とか、課題も含めて、あったら教えていただければと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ある一定程度の効果はあったかなというふうに思っております。職員が手作りで登録したりもしておりましたので、そういった意味では、チャレンジする気持ちもできたかなというふうに認識しております。","voiceIndex":313,"id":"exchange-142"},{"speaker":"藤原委員","kind":"質問","question":"５６ページ、交通安全対策特別交付金、１３５ページ、参議院議員選挙費、１０３ページ、学校施設整備費、１３１ページ、いじめ防止対策事業補助金についてお伺いします。参議院議員選挙についてお伺いしますが、なぜ選挙をするのでしょうか、教えてください。","respondent":"齋藤選挙管理委員会事務局長","answer":"統治機構の担い手である一定の公職にある方、例えば、国会議員、地方議会の議員、首長につきましては、投票という行動をもって選任すると、こういった定めがあるためです。","voiceIndex":316,"id":"exchange-143"},{"speaker":"藤原委員","kind":"質問","question":"私は、一番は民意の反映、公正公平な選挙をやって民意を反映することと考えています。国の仕事は衆参含めて国会議員、東京都の仕事は知事および都議会議員、そして品川区でいうのであれば、区長、そして区議会議員、こういう意味の選挙において民意を反映し、国だからとか、都だからとか、区だからとか、上とか下とかはないと思っているのですけれども、その辺についてはいかがでしょうか。","respondent":"齋藤選挙管理委員会事務局長","answer":"それぞれ国会議員の役割、地方議会の役割、首長の役割というものが定められておりまして、その役割を全うする。そして有権者の意思を反映させて、行政のチェックをしたり、立法活動に関わる、こういったことにおいては同質なもの、同等のものと理解しております。","voiceIndex":318,"id":"exchange-144"},{"speaker":"藤原委員","kind":"意見","question":"局長と全く同じ考えです。間違いなく同等ですよね。でも、不思議なのです。でも、区議会議員の選挙は自分で印刷しなくてはならない。これはどう考えてもおかしいと私は思うのです。どう考えてもおかしい。区は区、都は都、国は国なのに、こういうふうに公費に差がつくというのは、ちょっとおかしいなと思うのですけれども、局長、この辺についてはどう思いますか。","respondent":"齋藤選挙管理委員会事務局長","answer":"これは法律で地方議会、首長は除外をしていると、こういうたてつけになっているものです。立法論の課題となりますので、区として負担すべきかどうかということについては、少し答弁は控えさせていただきたいと思います。","voiceIndex":320,"id":"exchange-145"},{"speaker":"藤原委員","kind":"質問・要望","question":"答弁を控えさせていただきたいと言えば、それしかないですけれども、せっかく選挙管理委員会もあるわけですから、ぜひこういう意見も出たということは上げてください。死亡数が減ったことについて、よかったなと思うのですけれども、その辺の分析はいかがでしょうか。","respondent":"川口交通安全担当課長","answer":"ただ、その前の年と比べますと、高齢者の方々とか、そういう方々におけるそういう重大な事故等が少なかったというのは、比較的そのような日頃のキャンペーン等を通じた広報啓発活動の形が出たのかなというふうには考えております。","voiceIndex":322,"id":"exchange-146"},{"speaker":"藤原委員","kind":"質問","question":"日頃、委員からというお話、そうなのです。今日もそこなのですけれども、眼鏡橋の先の横断歩道、そして大崎駅前の信号がない横断歩道、いまだに私など待っているでしょう、目と目が合っているのです、ドライバーと。これは事実ですから。止まってくれない。これをずっと訴えてきたのですけれども、訴えて、何か対策を、改めてこういうことをしましたということがありましたら、その辺をお伝えください。","respondent":"川口交通安全担当課長","answer":"委員ご指摘の場所に対する対策の部分ですけれども、私のほうから警察のほうにも対応の要請をいたしまして、現在、眼鏡橋のところと、また大崎のウィズタワーの前の信号機のない横断歩道、こちらにつきましては、オーバーハング式の歩行者の横断歩道ありの標識の脇に。","voiceIndex":324,"id":"exchange-147"},{"speaker":"藤原委員","kind":"質問・要望","question":"目と目が合っても。ただ何となく、これは勘かもしれませんけれども、課長が警視庁に戻ってしまうのではないかなという、何か勘ですがあるのですけれども、でも、しかし、課長、東京都、もし警視庁に戻っても、今度、東京都全部、警視庁管轄の中において、やっぱり交通弱者、歩行者を守っていくという施策をしていっていただきたいと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"川口交通安全担当課長","answer":"なかなかいまだにルールを守っていただけるような状況にないという形ではありますけれども、日本自動車連盟が、信号機のない横断歩道での停止状況等について統計をとっておりますけれども、東京都内の数字ではありますが、令和２年は６.６％だったものが、昨年ですけれども。","voiceIndex":326,"id":"exchange-148"},{"speaker":"藤原委員","kind":"質問・要望","question":"よろしくお願いします。次に、学校施設整備ですけれども、これは１点ストレートに伺いますけれども、施設整備、改築等を含めて、ちゃんと順番にやられていると思うのですが、その中で、西大井の２校、伊藤小学校と冨士見台中学校、まだなのです。何か区界だから遅れてしまっているのかもしれないですけれども、これ、やっていただきたいのです、西大井の２校。これはどうなっているのですか。","respondent":"有馬庶務課長","answer":"基本的には、老朽度ですとか、就学人口、それから地域バランス等を踏まえて計画をしていくというものですので、大井地区についても、今後、全体を見ながら改築するかどうかは検討していきたいと考えております。","voiceIndex":328,"id":"exchange-149"},{"speaker":"藤原委員","kind":"質問","question":"課長、地域ということを言うならば、あの西大井の近辺、２校ともやっていないですから、地域バランスを考えたら、やるべきではないですか。少し考えていただければ幸いです。常勤ではないですよね。もうそろそろ常勤でということを考える時期に私はなっていると思うのですけれども、その辺についてはいかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"兼職やプライベートで、この週３日、４日というのが、いいバランスなのですという方もいるので、今後、相談内容や人数、また現職スタッフの話も聞きながら検討してまいりたいと思います。","voiceIndex":330,"id":"exchange-150"},{"speaker":"中塚委員","kind":"質問・要望","question":"７７ページ、区営住宅使用料に関連して、区営住宅について、異性だけではなく同性カップルも利用できるようにすることを求めて質問したいと思います。ならば、これまで異性カップルに限定されてきた区営住宅について、改めて同性カップルも対象に加えていただきたいと思いますが、いかがでしょうか。２３区で既に同性カップルの区営住宅の利用を認めている区は何区あるのか、どこなのか、伺いたいと思います。","respondent":"竹田住宅課長","answer":"今後、区所管では、東京都の動向を注視しながら、マイセルフ品川プランの行動計画推進会議の提言を踏まえ、パートナーシップ制度の導入について検討を進めているとしております。住宅課でも、区営住宅、区民住宅について、併せて検討してまいります。","voiceIndex":334,"id":"exchange-151"},{"speaker":"中塚委員","kind":"提案","question":"パートナーシップ制度について詳しく説明があったのですけれども、伺ったのは区営住宅、区民住宅を同性カップルも対象にしてほしいということで、住宅課としても併せて検討していきたいとのご答弁でした。改めて区営住宅に同性パートナーも認めることについて、この報告書に基づいて、具体化をする立場に立っていただきたいと思いますが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"今回、東京都が、パブリックコメントを実施いたします。広く都民の皆様のご意見をお聞きできる貴重な機会と考えています。東京都の動向を注視しながら、区政運営の参考にしていきたいと考えております。","voiceIndex":336,"id":"exchange-152"},{"speaker":"中塚委員","kind":"質問・要望","question":"東京都の動向は注視していただいて結構ですけれども、品川区行動計画推進会議が出した報告書、この立場に立って具体化を進めていただくことを求めたいと思います。区営住宅に同性カップルを認めるということは、こうした差別を許さないという強いメッセージにつながると私は思いますが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"東京都が現在検討している受理証明書が、区が入居希望者から入居時に提出していただいております親族要件を確認するための住民票等に代えられるものかどうかなども含めまして、東京都の動向を注視していきたいと考えています。","voiceIndex":338,"id":"exchange-153"},{"speaker":"中塚委員","kind":"質問","question":"東京都の動向は注視していただいてもよいのですけれども、私が今伺ったのは、この区営住宅に同性カップルを認めるということは、こうした差別は許されないという強いメッセージにつながると私は思うのですけれども、品川区は、そう思うのかどうか改めて伺いたいと思います。","respondent":"竹田住宅課長","answer":"品川区でも、区営、区民住宅について、併せて検討してまいる考えです。","voiceIndex":340,"id":"exchange-154"},{"speaker":"中塚委員","kind":"質問・要望","question":"いまいち前向きなのか、どこまで何を検討するのか、中身がよく分からないのが正直なところですけれども、区営住宅について、異性カップルだけではなく同性カップルも認めることに、何か課題があると思っていらっしゃるのか、その点を伺いたいと思います。ぜひ区営住宅に同性カップルも認めると、その導入に向けた検討を今年進めていただきたいと思いますが、改めていかがでしょうか。","respondent":"竹田住宅課長","answer":"その間柄を確認するために住民票を徴取していますが、パートナーシップ制度を利用した場合に東京都が発行を検討している住民証明が住民票に代わるものかどうかということをしっかり確認して、それで結果を出していきたいと思います。","voiceIndex":342,"id":"exchange-155"},{"speaker":"高橋（伸）委員","kind":"質問","question":"よろしくお願いします。５２ページ、特別区たばこ税、同じく５２ページ、森林環境譲与税についてお伺いいたします。来年度予算ですと２９億円強ということで、マイナス４,９００万円ということですけれども、これ、たばこの愛好者が少なくなっている中で、今後の見通しというか、減少傾向にあると思うのですけれども、改めてどういうふうに区としてお考えなのかということをまず１つお伺いしたいと思います。","respondent":"提坂税務課長","answer":"たばこの売渡し本数の動向につきましては、平成１８年以降、もう２０年近くずっと減り続けております。これまで度重なる税率の引上げですとか、健康志向の高まり、あと、今、コロナの影響とかもございまして、減少傾向は続くものと思われます。","voiceIndex":345,"id":"exchange-156"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"本当に課長がおっしゃるとおり、減少傾向だと私も認識しております。それで、もしお分かりになればでいいのですが、令和２年度の特別区たばこ税の収入額、２３区中、品川区は何位だったということがお分かりになれば教えていただきたいと思います。","respondent":"提坂税務課長","answer":"すみません、順位までは把握してございません。","voiceIndex":347,"id":"exchange-157"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"はい、分かりました。それと、関連しまして、今まで各委員から喫煙所に対しての質問がありました。最初に、プレス発表の資料ですけれども、４つの視点の中に、コンテナ型の喫煙所を整備しますということが記載してあるのですけれども、これ、超長寿社会に対応する視点ということで、これは喫煙者にとって整備をしますよということでいいのかということ、確認だけさせていただきたいと思います。","respondent":"森田生活安全担当課長","answer":"今後も、人の多い駅前であるとか、そういったところの指定地区において実施をしてまいりたいと考えています。","voiceIndex":349,"id":"exchange-158"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。次の質問で、「社会への喫煙者の風当たりは強いと思いますか」ということに対して、喫煙者の回答が「とてもそう思う」、非喫煙者の回答が「とてもそう思う」、４４％です。そういう意味で、コンテナとかというのは、当然それは必要ですけれども、屋内型をパーテーション型にしっかりと改良するという手法もあると思うのですけれども、それについてお伺いしたいと思います。","respondent":"森田生活安全担当課長","answer":"ですが、なるべくその辺の煙が出ないような対策は、考えながら実施をさせていただいているところです。","voiceIndex":351,"id":"exchange-159"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。ぜひ検討の１つとして考えていただきたいと思います。続いて、同じく５２ページ、森林環境譲与税についてお伺いいたします。今朝ご説明があったとおり、予算額が４,１００万円余、２９.４％の増ということです。５月にエコルとごしが開設しますけれども、そこが、この中に入っていない理由というのですか、その記載がなかったので、どういう考え方なのか教えていただきたいと思います。","respondent":"黒田財政課長","answer":"森林環境譲与税は、使途を、間伐や人材育成、担い手の確保、木材利用の促進や普及啓発の森林整備のために充てなければならないというふうになっておりまして、区の活用見込みとしましては、早川町との交流事業として、マウントしながわ活用事業ですとか、エコライフ普及事業。","voiceIndex":353,"id":"exchange-160"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。そうしますと、林野庁の取組みで事例集があるのです。令和２年度だと、森林材を使った取組事例として、特別区だと、中央区、豊島区、江東区が記載されています。これから児童相談所が新築されるわけですけれども、来年、そのときには、この事例集に児童相談所が、林野庁に事例集として、区として、それは上げていくのかということをお聞きしたいと思います。","respondent":"黒田財政課長","answer":"区の森林環境譲与税の活用事例として、そういった調査があれば報告していきたいというふうに考えてあります。","voiceIndex":355,"id":"exchange-161"},{"speaker":"高橋（伸）委員","kind":"質問","question":"やはりこれ、２９.４％増ということで、今後も増になるのかと思うのですけれども、財政として、どういうふうにそこはお考え、今後の見通しをお聞きしたいと思います。","respondent":"黒田財政課長","answer":"森林環境譲与税につきましては、国のほうで全国上限額という予算枠を設けておりまして、その中で市町村の配分割合が決まっておりますので、令和６年度には、品川区では５,０００万円ほどの譲与が見込まれておりますので。","voiceIndex":357,"id":"exchange-162"},{"speaker":"塚本委員","kind":"質問","question":"区として、このオンライン申請、年間、住民票や戸籍の申請というのはすごい数あるわけですけれども、何％ぐらい、このオンラインというところでの申請を見込んでいるのかという見通しをお聞きしたいのと、あと、他自治体、先ほど２３区では３区が実施しているというような話がありましたけれども、他自治体、全国的に、このオンライン申請というのは、今、どれぐらい進んでやられているのか、また。","respondent":"木村戸籍住民課長","answer":"そういう課題もこれから見据えながら、やはり１０％、２０％、コンビニ交付と同じぐらいのレベルに持っていきたいなというふうには考えておるところです。","voiceIndex":360,"id":"exchange-163"},{"speaker":"塚本委員","kind":"質問・要望","question":"区として認識しているところをお伺いしたいのと、あと、区として、自治体として、国へのこういった職務上請求等について、どういった意見なり要望なりということをこれまでしてきたことがあるのかについてお伺いします。","respondent":"木村戸籍住民課長","answer":"それで、実際には、小為替も、今回のオンラインの申請も、いわゆる郵便局へ行かなくてはいけないというところを不要にするというようなところもメリットとしてはありますので、オンライン、電子決済という形は、どんどん進めていきたいなというふうに思っておるのですけれども。","voiceIndex":362,"id":"exchange-164"},{"speaker":"塚本委員","kind":"質問","question":"職務上請求、オンラインに関わらずではあるのですけれども、どうしても不正請求の話が一方であるということで、このセキュリティ上で懸念される部分もあるかなというふうには思いますので、このセキュリティについて、どういった対応が必要と考えられるかお伺いしたいと思います。","respondent":"木村戸籍住民課長","answer":"ただ、職務上求められたことを請求しているのだというところの確認ができないということで、今は専用の用紙を厳正に管理していただいて、それでやっている、それに代わるやり方があるかどうか、ここら辺を国にどう示していただけるかという辺りが。","voiceIndex":364,"id":"exchange-165"},{"speaker":"塚本委員","kind":"意見","question":"無電柱化推進計画事業補助金ということでありますけれども、品川区では、令和２年に無電柱化推進計画を策定しておりますけれども、今年度、この無電柱化推進計画事業補助金がどういうことに使われるのかということと、令和１１年までに整備効果の高い４路線、この工事を最初に着手していくということですけれども、来年、令和４年度は、どのような工事が実際に進められる予定であるのか。","respondent":"溝口道路課長","answer":"実際のところ、令和４年度の事業につきましては、２路線、工事等を予定しておりますので、その中、１つは、文庫の森から２６号に向けての路線、あと競馬場の前の通りになりますが、しながわ区民公園の北側から国道まで抜ける間、この２路線については。","voiceIndex":366,"id":"exchange-166"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"皆さん、建物を建設していく中で、どこからお金が出ているのか、それからランニング、もちろんこれは０.１％の話は分かっていますけれども、その０.１％で、例えば荒川区とか、人件費の部分も見てくると、もうランニングで多分６億円ぐらいそこだけでかかっているというふうに出ているのだけれども、そうすると、０.１％だと、１兆７,０００億円ぐらいだとしたら１７億円ぐらいで。","respondent":"黒田財政課長","answer":"いわゆるランニングと言われる経費については、これまでの開設区につきましては、全体の５５.１％の中で、東京都のほうの財調の対応補正の中で、各区の需要として算定しているところでありますが、それが足りているか足りていないかというところにつきまして。","voiceIndex":369,"id":"exchange-167"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけこれはお願いをしておきます。それの見合いもここで議論をしてもらわないと、何でもかんでも、いいや、あそこで建物を見ているからと、私はその金額が全然違うと思っているので、ぜひそこの議論も併せてやってほしいかなと思うので、そこら辺の感覚を教えていただきたい。","respondent":"黒田財政課長","answer":"いわゆる児童相談所に関する財調協議につきましては、委員ご指摘のとおり、都区の役割分担の変更であるので、特別区の主張としては、都がやっていた仕事を特別区がやるのであれば、配分割合を相応、見合う分だけ見直しせよというのが特別区の主張なのですが、東京都のほうが。","voiceIndex":371,"id":"exchange-168"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここで伺いたいのは、私が先ほどの答弁でちょっとあれだったのは、去年までは、公共建築物という建物しか使えなかったのだと思っていて、それが今度、国が指針を変えて、それを今、都道府県に出していて、東京都がその指針をまだ整理できていないと言って、４月ぐらいには方向性を出しますと言っていると思っているのだけれども、そうすることによって、６月ぐらいから、ここでも住宅改修とか。","respondent":"黒田財政課長","answer":"森林環境譲与税につきましては、委員ご指摘のとおり、市町村においては、森林環境及びその促進に関する整備の費用に充てるべきということで、公共の費用だけに限られているわけではございませんので、他の自治体の活用事例ですと、地域林政アドバイザーの雇用でありますとか。","voiceIndex":373,"id":"exchange-169"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"品川区は、そういう意味で使途を出して、ほかの区は、多い区は、みんなこれ、使途が出せなくて、基金に積んでいるところが結構ある。それは庁舎もそうなのだけれども、これからやっぱり木のぬくもり、こういう優しさ、そういうものをぜひ区民の皆様にも味わってもらえるような使い方をしていっていただきたいなと思っていますので、これはもう要望で終わりますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":375,"id":"exchange-170"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1146#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":125029,"voices":376}},{"id":"r04-20220303-10","meetingId":"r04-cm03","date":"2022年3月3日","dateIso":"2022-03-03","committee":"議会運営委員会","time":"午後 ５時４５分～午後 ６時０３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"お手元に配付させていただきましたロシア連邦のウクライナ侵略に抗議し、即時撤退を求める決議案について、説明させていただきたいと思います。内容につきましては、この後、読み上げて説明といたしますが、議会運営委員会の全員の皆さんに、是非提出者になっていただきたいと思っています。内容につきまして読み上げて説明とさせていただきたいと思います。説明は以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"今回の侵略戦争に関しては異例も異例で、こんな世界平和の中でこういうことをやる国に関して、無謀な暴挙に関しては、やはりきちっと我々で訴えるべきではないでしょうか。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"提案","question":"提案者に質問です。中塚委員になるのか。中身のことはちょっと持ち帰って、文面の修正があるかと思うのですが、スケジュール感は、今現在でどのようなイメージをされてるか。というのは、文面を検討するにしても、これだけ毎日状況が変わると本当に難しいなと。スケジュール感だけ、提案者としてのご意見を伺っておこうと思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-003"},{"speaker":"中塚委員","kind":"確認","question":"正直言いまして、今日でちょうどウクライナ侵攻から１週間ということで、ただちに本会議にかけたいという思いはもっております。しかしやはり、皆さんの意見もしっかり反映させて、全会一致と願っておりますので、今予定されている会議日程から考えると、次回の議会運営委員会で議案を確認して、最終本会議で上程したいというスケジュール感を持っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"もう１回いいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-005"},{"speaker":"大沢委員","kind":"意見","question":"今、渡辺委員の発言にもあるように、戦時中、戦時下ですので、状況がどのように変わるかも分からない部分も非常にありますので、ちょっと一呼吸置いて、持ち帰らせていただいて、様子を見つつ、やはり最も適当な決議文に導いていくのが適当だと思います。ですので、１回持ち帰らせていただいてということのほうが私もいいと思います。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問・要望","question":"私どもの会派も、中身だろうと、そのスケジュール感だろうと、もちろん出す、出さないの含めて、私もちょっと持ち帰らせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5450#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":5408,"voices":33}}]);
